INSERT INTO m239_art VALUES
(0,0,$m239$الديباجة$m239$,$m239$قانون رقم 82 لسنة 2002 بإصدار قانون حماية حقوق الملكية الفكرية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m239$,'51374f949d35d0e6b5ff348308a1cfa0'),
(1,-1,$m239$المادة الأولى إصدار$m239$,$m239$يعمل بأحكام القانون المرافق فى شأن حماية حقوق الملكية الفكرية .$m239$,'48bd1cb387939748ff867963beaa1620'),
(2,-1,$m239$المادة الثانية إصدار$m239$,$m239$تلغى القوانين الآتية :
( أ ) القانون رقم 57 لسنة 1939 بشأن العلامات والبيانات التجارية .
( ب ) القانون رقم 132 لسنة 1949 بشأن براءات الاختراع والرسوم والنماذج الصناعية ، عدا أحكام براءات الاختراع الخاصة بالمنتجات الكيميائية المتعلقة بالأغذية والمنتجات الكيميائية الصيدلية فتلغى اعتبارا من أول يناير سنة 2005
( ج ) القانون رقم 354 لسنة 1954 بشأن حماية حق المؤلف .
كما يلغى كل حكم يخالف أحكام القانون المرافق .$m239$,'9e8b7e0cb04e8f81359d8d9d47dc9345'),
(3,-1,$m239$المادة الثالثة إصدار$m239$,$m239$يصدر مجلس الوزراء بناء على عرض الوزراء المختصين اللائحة التنفيذية فى مدة لا تزيد على شهر من تاريخ العمل بهذا القانون . ويصدر الوزراء المختصون كل فى حدود اختصاصه القرارات اللازمة لتنفيذ أحكام القانون المرافق .
وعلى الوزراء كل فيما يخصه اتخاذ التدابير اللازمة لحماية الصحة العامة والتغذية ، أو تنمية القطاعات الحيوية فى المجال الاجتماعى والاقتصادى والتكنولوجى ، وذلك فى حدود أحكام القانون المرافق .
وللوزراء كل فيما يخصه اتخاذ الإجراءات اللازمة فى إطار هذا القانون لمنع حائزى الملكية الفكرية من إساءة استخدامها أو منع اللجوء إلى الممارسات التى تسفر عن تقييد غير مناسب للتجارة ، أو تؤثر سلبا على النقل الدولى للتكنولوجيا ، وذلك كله على النحو المبين فى القانون المرافق .$m239$,'42aeb7a7faa3ea9940b2467b9cff6499'),
(4,-1,$m239$المادة الرابعة إصدار$m239$,$m239$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتبارا من اليوم التالى لتاريخ نشره ، عدا أحكام براءات الاختراع الخاصة بالمنتجات الكيميائية المتعلقة بالأغذية ، والمنتجات الكيميائية الصيدلية والكائنات الدقيقة والمنتجات التى لم تكن محل حماية قبل صدور هذا القانون فيعمل بها اعتبارا من أول يناير سنة 2005 ، وذلك دون الإخلال بأحكام المادتين ( 44 ، 45 ) من القانون المرافق .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 21 ربيع الأول سنة 1423 هـ . ( الموافق 2 يونية سنة 2002 م ) .
حسنى مبارك$m239$,'711d5a3cc0f7629cf0c4520655785cce'),
(1,0,$m239$المادة 1$m239$,$m239$تمنح براءة اختراع طبقا لأحكام هذا القانون عن كل اختراع قابل للتطبيق الصناعى ، يكون جديدا ، ويمثل خطوة إبداعية ، سواء كان الاختراع متعلقا بمنتجات صناعية جديدة أو بطرق صناعية مستحدثة ، أو بتطبيق جديد لطرق صناعية معروفة .
كما تمنح البراءة استقلالا ، عن كل تعديل أو تحسين أو إضافة ترد على اختراع سبق أن منحت عنه براءة ، إذا توافرت فيه شروط الجدة والإبداع والقابلية للتطبيق الصناعى على النحو المبين فى الفقرة السابقة ، ويكون منح البراءة لصاحب التعديل أو التحسين أو الإضافة وفقا لأحكام هذا القانون .$m239$,'a5ca9490ba8e429338a765d1cd6d7825'),
(2,0,$m239$المادة 2$m239$,$m239$لا تمنح براءة اختراع لما يلى :
1 - الاختراعات التى يكون من شأن استغلالها المساس بالأمن القومى أو الإخلال بالنظام العام أو الآداب العامة أو الإضرار الجسيم بالبيئة أو الإضرار بحياة أو صحة الإنسان أو الحيوان أو النبات .
2 - الاكتشافات والنظريات العلمية والطرق الرياضية والبرامج والمخططات .
3 - طرق تشخيص وعلاج وجراحة الإنسان أو الحيوان .
4 - النباتات والحيوانات أيا كانت درجة ندرتها أو غرابتها وكذلك الطرق التى تكون فى أساسها بيولوجية لإنتاج النباتات أو الحيوانات ، عدا الكائنات الدقيقة والطرق غير البيولوجية والبيولوجية الدقيقة لإنتاج النباتات أو الحيوانات .
5 - الأعضاء والأنسجة والخلايا الحية والمواد البيولوجية الطبيعية والحمض النووى والجينوم .$m239$,'e83c453531baf2d00b5c870dbe433baa'),
(3,0,$m239$المادة 3$m239$,$m239$لا يعتبر الاختراع جديدا كله أو جزء منه فى الحالتين الآتيتين :
1 - إذا كان قد سبق طلب إصدار براءة اختراع أو صدرت براءة عنه أو عن جزء منه فى جمهورية مصر العربية أو فى الخارج قبل تاريخ تقديم طلب البراءة .
2 - إذا كان قد سبق استعمال الاختراع أو استغلاله فى جمهورية مصر العربية أو فى الخارج بصفة علنية أو كان قد أفصح عن وصفه على نحو يمكن ذوى الخبرة من استغلاله قبل تقديم طلب البراءة .
ولا يعد إفصاحا فى حكم البند السابق الكشف عن الاختراع فى المعارض الوطنية أو الدولية خلال الستة الأشهر السابقة على تاريخ التقدم بطلب البراءة .
وتحدد اللائحة التنفيذية لهذا القانون أوضاع وإجراءات الكشف عن الاختراع .$m239$,'ed5889fcde3507297950be72cd8f694c'),
(4,0,$m239$المادة 4$m239$,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، الحق فى التقدم بطلب براءة اختراع لمكتب براءات الاختراع فى جمهورية مصر العربية وما يترتب على ذلك من حقوق طبقا لأحكام هذا القانون .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بالحقوق المنصوص عليها فى هذا الباب ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'65ea23dfb802291488d0db081b991866'),
(5,0,$m239$المادة 5$m239$,$m239$يعد بمكتب براءات الاختراع سجل خاص معتمد تقيد فيه طلبات براءات الاختراع ونماذج المنفعة وجميع البيانات المتعلقة بكل منها وباستغلالها والتصرفات التى ترد عليها وفقا لأحكام هذا القانون وذلك على النحو المبين فى لائحته التنفيذية .$m239$,'0056f3d629122cb07e90304e55d8e4a4'),
(6,0,$m239$المادة 6$m239$,$m239$يثبت الحق فى البراءة للمخترع أو لمن آلت إليه حقوقه .
وإذا كان الاختراع نتيجة عمل مشترك بين عدة أشخاص ، ثبت حقهم فى البراءة بالتساوى فيما بينهم ما لم يتفقوا على غير ذلك .
أما إذا كان قد توصل إلى ذات الاختراع أكثر من شخص يستقل كل منهم عن الآخر ، يثبت الحق للأسبق فى تقديم طلب البراءة .$m239$,'a98ebab9e2e2deae793f8d200f7ae0cb'),
(7,0,$m239$المادة 7$m239$,$m239$إذا كلف شخص آخر الكشف عن اختراع معين فجميع الحقوق المترتبة على هذا الاختراع تكون للأول ، وكذلك لصاحب العمل جميع الحقوق المترتبة على الاختراعات التى يستحدثها العامل أو المستخدم أثناء قيام رابطة العمل أو الاستخدام ، متى كان الاختراع فى نطاق العقد أو رابطة العمل أو الاستخدام .
ويذكر اسم المخترع فى البراءة ، وله أجره على اختراعه فى جميع الحالات فإذا لم يتفق على هذا الأجر كان له الحق فى تعويض عادل ممن كلفه الكشف عن الاختراع ، أو من صاحب العمل .
وفى غير الأحوال السابقة ، وعندما يكون الاختراع ضمن نشاط المنشأة العامة أو الخاصة الملحق بها المخترع ، يكون لصاحب العمل الخيار بين استغلال الاختراع ، أو شراء البراءة مقابل تعويض عادل يدفعه للمخترع ، على أن يتم الاختيار فى خلال ثلاثة أشهر من تاريخ الإخطار بمنح البراءة .
وفى جميع الأحوال يبقى الاختراع منسوبا إلى المخترع .$m239$,'bcde7f3099361bdfabf81340a266a582'),
(8,0,$m239$المادة 8$m239$,$m239$الطلب المقدم من المخترع للحصول على براءة اختراع فى خلال سنة من تاريخ تركه المنشأة الخاصة أو العامة ، يعتبر كأنه قدم فى خلال تنفيذ العقد أو قيام رابطة العمل أو الاستخدام ، ويكون لكل من المخترع وصاحب العمل جميع الحقوق المنصوص عليها فى المادة السابقة تبعا للأحوال .
وتزداد المدة إلى ثلاث سنوات إذا أنشأ العامل أو التحق بمنشأة منافسة ، وكان الاختراع نتيجة مباشرة لنشاطه وخبرته السابقة بالمنشأة التى كان يعمل بها .$m239$,'66b1cf126fd7f428ebcaa88f4b858755'),
(9,0,$m239$المادة 9$m239$,$m239$مدة حماية براءة الاختراع عشرون سنة تبدأ من تاريخ تقديم طلب البراءة فى جمهورية مصر العربية .$m239$,'e6741480e24b25d43491729dde6be293'),
(10,0,$m239$المادة 10$m239$,$m239$تخول البراءة مالكها الحق فى منع الغير من استغلال الاختراع بأية طريقة .
ويستنفد حق مالك البراءة فى منع الغير من استيراد أو استخدام أو بيع أو توزيع السلعة ، إذا قام بتسويقها فى أية دولة أو رخص للغير بذلك .
ولا يعتبر اعتداء على هذا الحق ما يقوم به الغير من الأعمال الآتية :
1 - الأعمال المتصلة بأغراض البحث العلمى .
2 - قيام الغير فى جمهورية مصر العربية ، بصنع منتج ، أو باستعمال طريقة صنع منتج معين أو باتخاذ ترتيبات جدية لذلك ما لم يكن سىء النية ، وذلك قبل تاريخ تقديم طلب البراءة من شخص آخر عن المنتج ذاته ، أو عن طريقة صنعه ، ولهذا الغير رغم صدور البراءة حق الاستمرار لصالح منشأته فقط فى القيام بالأعمال المذكورة ذاتها دون التوسع فيها ، ولا يجوز التنازل عن حق القيام بهذه الأعمال ، أو نقل هذا الحق إلا مع باقى عناصر المنشأة .
3 - الاستخدامات غير المباشرة لطريقة الإنتاج ، التى يتكون منها موضوع الاختراع وذلك للحصول على منتجات أخرى .
4 - استخدام الاختراع فى وسائل النقل البرى أو البحرى أو الجوى التابعة لإحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، وذلك فى حالة وجود أى من هذه الوسائل فى جمهورية مصر العربية بصفة وقتية أو عارضة .
5 - قيام الغير بصنع أو تركيب أو استخدام أو بيع المنتج أثناء فترة حمايته بهدف استخراج ترخيص لتسويقه ، على ألا يتم التسويق إلا بعد انتهاء تلك الفترة .
6 - الأعمال التى يقوم بها الغير خلاف ما تقدم ، شريطة ألا تتعارض بشكل غير معقول مع الاستخدام العادى للبراءة ، وألا تضر بصورة غير معقولة بالمصالح المشروعة لصاحب البراءة ، مع مراعاة المصالح المشروعة للغير .$m239$,'50eb344c31ac8658c43184e53203441a'),
(11,0,$m239$المادة 11$m239$,$m239$يستحق رسم عند تقديم طلب براءة الاختراع كما يستحق رسم سنوى يتدرج بالزيادة اعتبارا من بداية السنة الثانية وحتى انتهاء مدة حماية البراءة .
وتحدد اللائحة التنفيذية قيمة هذه الرسوم بما لا يجاوز ألفى جنيه عند تقديم الطلب ، وبما لا يجاوز ألف جنيه بالنسبة للرسم السنوى .
كما تحدد اللائحة قواعد تخفيض هذه الرسوم وأحوال الإعفاء منها .
ويتحمل مقدم طلب الحصول على البراءة أتعاب الخبراء الذين يستعين بهم مكتب البراءات ومصروفات الفحص .$m239$,'07f5cd7e3e54fb3627e6e9b6a3f0aa73'),
(12,0,$m239$المادة 12$m239$,$m239$يقدم طلب البراءة من المخترع أو ممن آلت إليه حقوقه إلى مكتب براءات الاختراع وفقا للأوضاع والشروط التى تحددها اللائحة التنفيذية لهذا القانون ، ولا يجوز أن يتضمن طلب البراءة أكثر من اختراع واحد ، ويعتبر فى حكم الاختراع الواحد مجموعة الاختراعات التى تشكل فكرة إبداعية متكاملة .$m239$,'ff3f778ecd489e7a1aaaea963b809b18'),
(13,0,$m239$المادة 13$m239$,$m239$يرفق بطلب البراءة وصف تفصيلى للاختراع يتضمن بيانا كاملا عن موضوعه ، وعن أفضل أسلوب يمكن ذوى الخبرة من تنفيذه ، وذلك بالنسبة لكل واحد من المنتجات والطرق محل الطلب .
ويجب أن يشتمل الوصف بطريقة واضحة على العناصر الجديدة التى يطلب صاحب الشأن حمايتها ، وأن يرفق بالطلب رسم هندسى للاختراع عند الاقتضاء .
وإذا كان الطلب متعلقا باختراع يتضمن مواد بيولوجية نباتية أو حيوانية ، أو معارف تقليدية طبية أو زراعية أو صناعية أو حرفية ، أو تراثا حضاريا أو بيئيا ، فيجب أن يكون المخترع حاصلا على مصدرها بطريقة مشروعة .
فإذا كان الطلب متعلقا بكائنات دقيقة وجب على الطالب أن يفصح عن هذه الكائنات ، وأن يودع مزرعة حية منها لدى الجهة التى تحددها اللائحة التنفيذية لهذا القانون .
ومع مراعاة أحكام المادة ( 38 ) من هذا القانون يلتزم الطالب فى جميع الأحوال بتقديم بيانات ومعلومات كاملة عن الطلبات التى سبق أن قدمها فى الخارج عن نفس الاختراع أو ما يتصل بموضوعه وكذلك نتائج البت فى هذه الطلبات .
وتحدد اللائحة التنفيذية لهذا القانون مرفقات طلب براءة الاختراع والمواعيد الواجب تقديمها خلالها والأحوال التى تستوجب رفضه .$m239$,'3c915485ce42da8077c40ff9806771a1'),
(14,0,$m239$المادة 14$m239$,$m239$لمكتب براءات الاختراع أن يكلف طالب البراءة بإجراء التعديلات أو الاستيفاءات التى يراها على الطلب إعمالا لأحكام المادة ( 13 ) من هذا القانون ، وذلك على النحو الذى تبينه اللائحة التنفيذية ، فإذا لم يقم الطالب بهذا الإجراء خلال ثلاثة أشهر من تاريخ إخطاره اعتبر متنازلا عن طلبه .
وللطالب أن يتظلم من قرار مكتب براءات الاختراع بشأن هذا التكليف أمام اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ، وذلك خلال ثلاثين يوما ووفقا للإجراءات التى تبينها اللائحة التنفيذية .$m239$,'fd24284125398ef9507fac208336b6bb'),
(15,0,$m239$المادة 15$m239$,$m239$يجوز لطالب براءة الاختراع أن يقدم فى أى وقت قبل الإعلان عن قبول طلب البراءة طلبا بتعديل مواصفات الاختراع أو رسمه الهندسى مع بيان ماهية التعديل وأسبابه ويشرط ألا يؤدى التعديل إلى المساس بذاتية الاختراع ، وتتبع فى هذا الشأن ذات الإجراءات الخاصة بطلب البراءة .$m239$,'0fd5b7353b710e6d3e3bd888b657bf57'),
(16,0,$m239$المادة 16$m239$,$m239$يفحص مكتب براءات الاختراع طلب البراءة ومرفقاته للتحقق من أن الاختراع جديد ويمثل خطوة إبداعية وقابل للتطبيق الصناعى طبقا لأحكام المواد ( 1 ) ، ( 2 ) ، ( 3 ) من هذا القانون .
فإذا توافرت فى الاختراع الشروط المشار إليها ، وروعيت فى طلب البراءة الأحكام المنصوص عليها فى المادتين ( 12 ) ، ( 13 ) من هذا القانون قام مكتب براءات الاختراع بالإعلان عن قبول الطلب فى جريدة براءات الاختراع بالطريقة التى تحددها اللائحة التنفيذية .
ويجوز لكل ذى شأن أن يعترض كتابة على السير فى إجراءات إصدار البراءة بإخطار يوجه إلى مكتب براءات الاختراع متضمنا أسباب الاعتراض وذلك خلال ستين يوما من تاريخ الإعلان عن قبول الطلب فى جريدة براءات الاختراع ، ووفقا للأوضاع التى تحددها اللائحة التنفيذية لهذا القانون .
ويؤدى مقدم الإخطار بالاعتراض رسما تحدده اللائحة التنفيذية لهذا القانون بما لا يقل عن مائة جنيه ولا يجاوز ألف جنيه ويسترد الرسم فى حالة قبول الاعتراض .
وتختص بنظر الاعتراضات اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية .$m239$,'cd94cd21a1157c09d122211881084392'),
(17,0,$m239$المادة 17$m239$,$m239$يرسل مكتب براءات الاختراع إلى وزارة الدفاع أو وزارة الإنتاج الحربى أو وزارة الداخلية أو وزارة الصحة على حسب الأحوال صورا من طلبات براءات الاختراع التى تتصل بشئون الدفاع أو الإنتاج الحربى أو الأمن العام أو التى لها قيمة عسكرية أو أمنية أو صحية ، مع مرفقات هذه الطلبات ، وذلك خلال عشرة أيام من تاريخ الانتهاء من الفحص مع إخطار الطالب بذلك خلال سبعة أيام من تاريخ الإرسال ، ولوزير الدفاع أو وزير الإنتاج الحربى أو وزير الداخلية أو وزير الصحة على حسب الأحوال أن يعترض على الإعلان عن قبول طلب البراءة ، خلال تسعين يوما من تاريخ الإرسال .
وللوزير المختص - على حسب الأحوال - بعد الإعلان عن قبول طلب البراءة الاعتراض على السير فى إجراءات إصدارها وذلك إذا يتبين له أن الطلب يتعلق بشئون الدفاع أو الإنتاج الحربى أو الأمن العام أو أن له قيمة عسكرية أو أمنية أو صحية ، ويكون الاعتراض خلال تسعين يوما من تاريخ الإعلان عن قبول طلب البراءة فى جريدة براءات الاختراع .
ويترتب على الاعتراض فى الحالات المشار إليها وقف السير فى إجراءات إصدار البراءة .$m239$,'8d8a550dc722bc771e5f0cbd2afcdd23'),
(18,0,$m239$المادة 18$m239$,$m239$ينشأ صندوق لموازنة أسعار الدواء - غير المعد للتصدير - وتكون له الشخصية الاعتبارية ، ويتبع وزير الصحة والسكان ، وذلك لتحقيق التنمية الصحية وضمان عدم تأثر تلك الأسعار بما يطرأ من متغيرات ، ويصدر بتنظيم الصندوق وتحديد موارده قرار من رئيس الجمهورية على أن يكون من بين هذه الموارد ما تقبله الدولة من مساهمات من الدول المانحة والمنظمات الدولية الحكومية وغير الحكومية .$m239$,'3f657dcf0b66418e45da069729e6de79'),
(19,0,$m239$المادة 19$m239$,$m239$لا يتم الإعلان عن قبول طلب البراءة إلا بعد انقضاء سنة تبدأ من تاريخ تقديمه ويظل الطلب سريا خلال تلك الفترة .
ويكون منح البراءة بقرار من الوزير المختص أو من يفوضه فى ذلك وينشر هذا القرار فى جريدة براءات الاختراع بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'ed0d3e2d20c83f6787999d299d88061a'),
(20,0,$m239$المادة 20$m239$,$m239$للكافة بعد الإعلان عن قبول الطلب الاطلاع عليه وعلى مستنداته وما دون عنه فى سجل براءات الاختراع ، كما يجوز لأى منهم الحصول على صورة مما تقدم وذلك مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه ، ووفقا للأوضاع والإجراءات التى تقررها هذه اللائحة .$m239$,'61b08ac3ece7ec712a905a5daebc1a40'),
(21,0,$m239$المادة 21$m239$,$m239$يجوز نقل ملكية البراءة كلها أو بعضها بعوض أو بغير عوض ، كما يجوز رهنها أو تقرير حق الانتفاع عليها .
ومع عدم الإخلال بالأحكام الخاصة ببيع المحال التجارية ورهنها لا تنتقل ملكية البراءة ولا يكون رهنها أو تقرير حق انتفاع عليها حجة على الغير إلا من تاريخ التأشير بذلك فى سجل البراءات .
ويكون النشر عن انتقال ملكية البراءة أو رهنها أو تقرير حق الانتفاع عليها وفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية .$m239$,'a6b9461811a813970303f802764b36f3'),
(22,0,$m239$المادة 22$m239$,$m239$يجوز للدائن أن يوقع الحجز على براءة الاختراع الخاصة بمدينه وفقا لقواعد الحجز على المنقول تحت يد المدين ولدى الغير ، ولا يلتزم مكتب البراءات بالأحكام المتعلقة بإقرار المحجوز لديه بما فى الذمة قبل المحجوز عليه .
ويجب على الدائن أن يعلن الحجز ومحضر مرسى المزاد لمكتب البراءات التأشير بهما فى السجل ولا يكون أيهما حجة على الغير إلا من تاريخ ذلك التأشير .
وينشر عن الحجز بالطريقة التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'1deb828e2e2ef7015fe7f5ab00acf051'),
(23,0,$m239$المادة 23$m239$,$m239$يمنح مكتب براءات الاختراع - وبعد موافقة لجنة وزارية تشكل بقرار من رئيس مجلس الوزراء - تراخيص إجبارية باستغلال الاختراع ، وتحدد اللجنة الحقوق المالية لصاحب البراءة عند إصدار هذه التراخيص . وذلك فى الحالات الآتية :
أولا - إذا رأى الوزير المختص - بحسب الأحوال - أن استغلال الاختراع يحقق ما يلى :
1 - أغراض المنفعة العامة غير التجارية :
ويعتبر من هذا القبيل أغراض المحافظة على الأمن القومى ، والصحة ، وسلامة البيئة والغذاء .
2 - مواجهة حالات الطوارىء أو ظروف الضرورة القصوى .
ويصدر الترخيص الإجبارى لمواجهة الحالات الواردة فى البندين ( 1 ) ، ( 2 ) دون الحاجة لتفاوض مسبق مع صاحب البراءة ، أو لانقضاء فترة من الزمن على التفاوض معه ، أو لعرض شروط معقولة للحصول على موافقته بالاستغلال .
3 - دعم الجهود الوطنية فى القطاعات ذات الأهمية للتنمية الاقتصادية والاجتماعية والتكنولوجية ، وذلك دون إخلال غير معقول بحقوق مالك البراءة ، ومع مراعاة المصالح المشروعة للغير .
ويلزم إخطار صاحب البراءة بقرار الترخيص الإجبارى بصورة فورية فى الحالات الواردة فى البندين ( 1 ) ، ( 3 ) وفى أقرب فرصة معقولة تتيحها الحالات الواردة فى البند ( 2 ) .
ثانيا - إذا طلب وزير الصحة فى أية حالة من حالات عجز كمية الأدوية المحمية بالبراءة عن سد احتياجات البلاد ، أو انخفاض جودتها ، أو الارتفاع غير العادى فى أسعارها ، أو إذا تعلق الاختراع بأدوية الحالات الحرجة أو الأمراض المزمنة أو المستعصية أو المتوطنة أو بالمنتجات التى تستخدم فى الوقاية من هذه الأمراض ، وسواء تعلق الاختراع بالأدوية ، أو بطريقة إنتاجها ، أو بالمواد الخام الأساسية التى تدخل فى إنتاجها ، أو بطريقة تحضير المواد الخام اللازمة لإنتاجها .
ويجب فى جميع هذه الحالات إخطار صاحب البراءة بقرار الترخيص الإجبارى بصورة فورية .
ثالثا - إذا رفض صاحب البراءة الترخيص للغير باستغلال الاختراع - أيا كان الغرض من الاستغلال - رغم عرض شروط مناسبة عليه ، وانقضاء فترة تفاوض معقولة .
ويتعين على طالب الترخيص الإجبارى فى هذه الحالة أن يثبت أنه قد بذل محاولات جدية للحصول على الترخيص الاختيارى من صاحب البراءة .
رابعا - إذا لم يقم صاحب البراءة باستغلالها فى جمهورية مصر العربية ، بمعرفته أو أو بموافقته أو كان استغلالها استغلالا غير كاف ، رغم مضى أربع سنوات من تاريخ تقديم طلب البراءة أو ثلاث سنوات من تاريخ منحها أيهما أطول ، وكذلك إذا أوقف صاحب البراءة استغلال الاختراع بدون عذر مقبول لمدة تزيد على سنة .
ويكون الاستغلال بإنتاج المنتج موضوع الحماية فى جمهورية مصر العربية ، أو باستخدام طريقة الصنع المحمية ببراءة الاختراع فيها .
ومع ذلك ، إذا رأى مكتب براءات الاختراع ، رغم فوات أى من المدتين المشار إليهما ، أن عدم استغلال الاختراع يرجع إلى أسباب قانونية أو فنية أو اقتصادية خارجة عن إرادة صاحب البراءة ، جاز أن يمنحه مهلة أخرى كافية لاستغلال الاختراع .
خامسا - إذا ثبت تعسف صاحب البراءة أو قيامه بممارسة حقوقه التى يستمدها من البراءة على نحو مضاد للتنافس ويعتبر من قبيل ذلك ما يلى :
1 - المبالغة فى أسعار بيع المنتجات المشمولة بالحماية ، أو التمييز بين العملاء فيما يتعلق بأسعار وشروط بيعها .
2 - عدم توفير المنتج المشمول بالحماية فى السوق ، أو طرحه بشروط مجحفة .
3 - وقف إنتاج السلعة المشمولة بالحماية أو إنتاجها بكمية لا تحقق التناسب بين الطاقة الإنتاجية وبين احتياجات السوق .
4 - القيام بأعمال أو تصرفات تؤثر سلبا على حرية المنافسة ، وفقا للضوابط القانونية المقررة .
5 - استعمال الحقوق التى يخولها القانون على نحو يؤثر سلبا على نقل التكنولوجيا .
وفى جميع الأحوال السابقة يصدر الترخيص الإجبارى دون حاجة للتفاوض ، أو انقضاء مهلة على حصوله ، ولو كان الترخيص الإجبارى لا يستهدف الوفاء باحتياجات السوق المحلى .
ويكون لمكتب براءات الاختراع أن يرفض إنهاء الترخيص الإجبارى إذا كانت الظروف التى دعت لإصداره تدل على استمرارها أو تنبئ بتكرار حدوثها .
ويراعى عند تقدير التعويض المستحق لصاحب البراءة الأضرار التى سببتها ممارساته التعسفية أو المضادة للتنافس .
ويجوز لمكتب براءات الاختراع إسقاط البراءة إذا تبين بعد مضى سنتين من منح الترخيص الإجبارى أن ذلك الترخيص لم يكن كافيا لتدارك الآثار السلبية التى لحقت بالاقتصاد القومى بسبب تعسف صاحب البراءة فى استعمال حقوقه أو لممارساته المضادة للتنافس .
ويجوز لكل ذى مصلحة الطعن فى قرار إسقاط البراءة أمام اللجنة المنصوص عليها فى المادة ( 36 ) ، ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
سادسا - إذا كان استغلال صاحب الحق فى براءة اختراع لا يتم إلا باستغلال اختراع آخر لازم له وكان منطويا على تقدم تقنى ملموس وأهمية فنية واقتصادية مقارنة بهذا الآخر ، فإنه يحق له الحصول على ترخيص إجبارى فى مواجهة الآخر ويكون لهذا الآخر ذات الحق فى هذه الحالة .
ولا يجوز التنازل عن الاستخدام المرخص به لإحدى البراءتين إلا بالتنازل عن استخدام البراءة الأخرى .
سابعا - فى حالات الاختراعات المتعلقة بتكنولوجيا أشباه الموصلات ، لا يمنح الترخيص الإجبارى إلا لأغراض المنفعة العامة غير التجارية ، أو لمعالجة الآثار التى يثبت أنها مضادة للتنافس .
ويكون منح التراخيص الإجبارية فى الحالات المنصوص عليها فى هذه المادة وفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'813e1e4a084ced6f8f30a77f03c024f7'),
(24,0,$m239$المادة 24$m239$,$m239$يراعى عند إصدار الترخيص الإجبارى ما يلى :
1 - أن يبت فى طلب إصدار الترخيص الإجبارى ، وفقا لظروف كل حالة على حدة ، وأن يستهدف الترخيص أساسا توفير احتياجات السوق المحلية .
2 - أن يثبت طالب الترخيص الإجبارى أنه بذل خلال مدة معقولة محاولات جدية للحصول على ترخيص اختيارى من صاحب البراءة نظير مقابل عادل ، وأنه أخفق فى ذلك .
3 - أن يكون لصاحب البراءة حق التظلم من القرار الصادر بمنح الترخيص الإجبارى للغير أمام اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون وذلك خلال ثلاثين يوما من تاريخ إخطاره بصدور هذا الترخيص ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية .
4 - أن يكون طالب الحصول على الترخيص الإجبارى ، أو من يصدر ، لصالحه قادرا على استغلال الاختراع بصفة جدية فى جمهورية مصر العربية .
5 - أن يلتزم المرخص له ترخيصا إجباريا باستخدام الاختراع فى النطاق وبالشروط وخلال المدة التى يحددها قرار منح هذا الترخيص الإجبارى .
فإذا انتهت مدة الترخيص الإجبارى دون تحقيق الغرض من هذا الاستخدام جاز لمكتب براءات الاختراع تجديد المدة .
6 - يقتصر استخدام الترخيص الإجبارى على طالبه ، ومع ذلك يجوز لمكتب براءات الاختراع منحه لغيره .
7 - عدم أحقية المرخص له ترخيصا إجباريا فى التنازل عنه للغير إلا مع المشروع أو مع الجزء المتعلق باستخدام الاختراع .
8 - أن يكون لصاحب البراءة الحق فى الحصول على تعويض عادل مقابل استغلال اختراعه ، وتراعى فى تقدير هذا التعويض القيمة الاقتصادية للاختراع .
ويكون لصاحب البراءة الحق فى التظلم من قرار تقدير التعويض أمام اللجنة المنصوص عليها فى المادة ( 36 ) ، وذلك خلال ثلاثين يوما من تاريخ إخطاره بالقرار ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
9 - أن ينقضى الترخيص الإجبارى بانتهاء مدته . ومع ذلك لمكتب براءات الاختراع أن يقرر إلغاء الترخيص الإجبارى قبل نهاية مدته إذا زالت الأسباب التى أدت إلى منحه ولم يكن مرجحا قيام هذه الأسباب مرة أخرى ، وتتبع فى ذلك الإجراءات التى تنص عليها اللائحة التنفيذية .
10 - أن يكون لصاحب الاختراع أن يطلب إنهاء الترخيص الإجبارى ، قبل نهاية المدة المحددة له ، وذلك إذا زالت الأسباب التى أدت إلى الحصول عليه ولم يعد مرجحا قيامها مرة أخرى .
11 - أن تراعى المصالح المشروعة للمرخص له عند إنهاء الترخيص الإجبارى قبل نهاية مدته .
12 - أن يكون لمكتب براءات الاختراع تعديل شروط الترخيص الإجبارى أو إلغاؤه سواء من تلقاء نفسه أو بناء على طلب كل ذى شأن ، وذلك إذا لم يقم المرخص له باستخدام الترخيص خلال سنتين من تاريخ منحه ، أو إذا أخل بالتزاماته المنصوص عليها فى الترخيص .$m239$,'3ae6a151ac58f7ec6a7c82527f6d7205'),
(25,0,$m239$المادة 25$m239$,$m239$يجوز بقرار من الوزير المختص - بعد موافقة اللجنة الوزارية المشار إليها فى المادة ( 23 ) من هذا القانون - نزع ملكية براءة الاختراع لأسباب تتعلق بالأمن القومى ، وفى حالات الضرورة القصوى التى لا يكون فيها الترخيص الإجبارى كافيا لمواجهتها .
ويجوز أن يكون نزع الملكية مقصورا على نزع حق استغلال الاختراع لحاجات الدولة .
وفى جميع الأحوال يكون نزع الملكية مقابل تعويض عادل ، ويكون تقدير التعويض بواسطة اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ، ووفقا للقيمة الاقتصادية السائدة وقت إصدار قرار نزع الملكية .
وينشر قرار نزع الملكية فى جريدة براءات الاختراع ، ويكون الطعن فى قرار نزع الملكية وفى قرار اللجنة بتقدير التعويض أمام محكمة القضاء الإدارى ، وذلك خلال ستين يوما من تاريخ إخطار صاحب الشأن بالقرار بموجب خطاب مسجل موصى عليه مصحوبا بعلم الوصول وتفصل المحكمة فى هذا الطعن على وجه الاستعجال .$m239$,'189f0c6a6ca15245996d45ab2bb8e30e'),
(26,0,$m239$المادة 26$m239$,$m239$تنقضى الحقوق المترتبة على براءة الاختراع بما يسقطها فى الملك العام فى الأحوال الآتية :
1 - انقضاء مدة الحماية وفقا لنص المادة ( 9 ) من هذا القانون .
2 - تنازل صاحب براءة الاختراع عن حقوقه عليها دون الإخلال بحقوق الغير .
3 - صدور حكم بات ببطلان براءة الاختراع .
4 - الامتناع لمدة سنة من تاريخ الاستحقاق عن دفع الرسوم السنوية أو الغرامة التأخيرية ومقدارها ( 7 ٪ ) من هذه الرسوم ، بعد إخطاره بالدفع وفقا للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
5 - عدم استغلال الاختراع فى مصر فى السنتين التاليتين لمنح الترخيص الإجبارى وذلك بناء على طلب يتقدم به كل ذى شأن إلى مكتب براءات الاختراع .
6 - تعسف صاحب براءة الاختراع فى استعمال حقوقه فى الحالات التى لا يكون الترخيص الإجبارى فيها كافيا لتدارك ذلك التعسف .
ويعلن عن البراءة التى انقضت حقوق أصحابها عليها وفقا للأحكام السابقة ، بالنشر فى جريدة براءات الاختراع بالطريقة التى تحددها اللائحة التنفيذية .$m239$,'227fec0f383e4c2bd712bc9ef8621084'),
(27,0,$m239$المادة 27$m239$,$m239$تختص محكمة القضاء الإدارى بنظر الدعاوى المتعلقة بالقرارات الصادرة بشأن براءات الاختراع .$m239$,'0553c83cbdcd22784b62e44a53176038'),
(28,0,$m239$المادة 28$m239$,$m239$يجوز لمحكمة القضاء الإدارى أن تحكم بناء على طلب مكتب براءات الاختراع أو بناء على طلب ذى الشأن بإضافة أى بيان للسجل قد أغفل تدوينه أو بتعديل أى بيان وارد فيه غير مطابق للحقيقة أو بحذف أى بيان دون به بغير وجه حق .
كما يجوز لمكتب براءات الاختراع ولكل ذى شأن أن يطلب إلى المحكمة الحكم بإبطال البراءات التى تمنح مخالفة لأحكام المادتين ( 2 ) ، ( 3 ) من هذا القانون ، وتقوم الإدارة المذكورة بإلغاء هذه البراءات متى تقدم لها حكم بذلك حائز لقوة الشىء المقضى به .$m239$,'4b51f59e1d6f180a8b008d9d65c0720f'),
(29,0,$m239$المادة 29$m239$,$m239$تمنح براءة نموذج المنفعة طبقا لأحكام هذا القانون عن كل إضافة تقنية جديدة فى بناء أو تكوين وسائل أو أدوات أو عدد أو أجزائها أو منتجات أو مستحضرات أو طرق إنتاج كل ما تقدم ، وغير ذلك مما يستخدم فى الاستعمال الجارى .
ولمقدم الطلب تحويله إلى طلب براءة اختراع ، كما يحق لطالب براءة الاختراع تحويل طلبه إلى طلب براءة لنموذج منفعة .
ويرتد القيد فى الحالتين إلى تاريخ تقديم الطلب الأصلى .
ولمكتب براءات الاختراع - من تلقاء نفسه - تحويل طلب براءة نموذج المنفعة إلى طلب براءة اختراع متى توافرت شروطه .$m239$,'337b19863e418e32713a21666188a16f'),
(30,0,$m239$المادة 30$m239$,$m239$مدة حماية نموذج المنفعة سبع سنوات غير قابلة للتجديد تبدأ من تاريخ تقديم طلب براءة نموذج المنفعة إلى مكتب براءات الاختراع فى جمهورية مصر العربية .$m239$,'cae0af0824f8060f92202e7d46d45cb1'),
(31,0,$m239$المادة 31$m239$,$m239$يستحق رسم عند تقديم طلب براءة نموذج المنفعة كما يستحق رسم سنوى يتدرج بالزيادة اعتبارا من بداية السنة الثانية وحتى انتهاء مدة البراءة .
وتحدد اللائحة التنفيذية لهذا القانون قيمة هذه الرسوم بما لا يجاوز ألف جنيه لكل طلب ، وكذلك قواعد تخفيضها وحالات الإعفاء منها .$m239$,'96bfcced727252099787c857ad86c3c5'),
(32,0,$m239$المادة 32$m239$,$m239$مع عدم الإخلال بأحكام المادة ( 10 ) من هذا القانون ، يعاقب بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه :
1 - كل من قلد بهدف التداول التجارى موضوع اختراع أو نموذج منفعة منحت براءة عنه وفقا لأحكام هذا القانون .
2 - كل من باع أو عرض للبيع أو للتداول أو استورد أو حاز بقصد الاتجار منتجات مقلدة مع علمه بذلك ، متى كانت براءة الاختراع أو براءة نموذج المنفعة صادرة عنها أو عن طرق إنتاجها ونافذة فى جمهورية مصر العربية ،
3 - كل من وضع بغير حق على المنتجات أو الإعلانات أو العلامات التجارية أو أدوات التعبئة أو غير ذلك ، بيانات تؤدى إلى الاعتقاد بحصوله على براءة اختراع أو براءة نموذج منفعة .
وفى حالة العود تكون العقوبة الحبس مدة لا تزيد على سنتين والغرامة التى لا تقل عن أربعين ألف جنيه ولا تجاوز مائتى ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة الأشياء المقلدة محل الجريمة والأدوات التى استخدمت فى التقليد وينشر الحكم الصادر بالإدانة فى جريدة يومية واحدة أو أكثر على نفقة المحكوم عليه .$m239$,'0ffc7380d1424a9141e3d700cdd64c73'),
(33,0,$m239$المادة 33$m239$,$m239$يجوز لصاحب براءة الاختراع أو نموذج المنفعة أن يطلب من رئيس المحكمة المختصة بحسب الأحوال إصدار أمر بإجراء تحفظى بشأن المنتجات أو البضائع المدعى بتقليدها للمنتج الصادر عنه البراءة وفقا للوصف التفصيلى الذى تم الإفصاح عنه فى وثيقة براءة الاختراع أو نموذج المنفعة ، ويصدر الأمر بالإجراءات التحفظية اللازمة لحفظ هذه المنتجات والبضائع على النحو الذى يضمن بقاءها بحالتها .
ويجوز أن يصدر الأمر المشار إليه قبل رفع الدعوى ويسقط بعدم رفعها خلال ثمانية أيام من تاريخ الصدور .$m239$,'5f976c54083439debba0112548967a17'),
(34,0,$m239$المادة 34$m239$,$m239$يعتبر المنتج المطابق قد تم الحصول عليه وفقا للطريقة المشمولة بالبراءة إذا أثبت المدعى فى دعواه المدنية :
1 - أن المنتج المطابق قد تم الحصول عليه بالاستخدام المباشر للطريقة المشمولة بالبراءة .
2 - أو أنه قد بذل الجهد المعقول للكشف عن الطريقة التى استخدمت فى الإنتاج .
وفى هذه الحالة يجوز للمحكمة أن تأمر المدعى عليه بأن يثبت أن الطريقة التى استخدمها فى الحصول على المنتج المطابق تختلف عن الطريقة المشمولة بالبراءة والمملوكة للمدعى .
وعلى المحكمة أن تراعى فى اتخاذ إجراءات الإثبات حق المدعى عليه فى حماية أسراره الصناعية والتجارية .$m239$,'329445a78793896d18a0be32014a299e'),
(35,0,$m239$المادة 35$m239$,$m239$لرئيس المحكمة المختصة بأصل النزاع بناء على طلب كل ذى شأن وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة وفاء لما يقضى به من الغرامات أو التعويضات ، كما له أن يأمر بإتلاف الأشياء المتحفظ عليها عند الاقتضاء .$m239$,'fadeda3be254e3ba1dbb7487a93168ee'),
(36,0,$m239$المادة 36$m239$,$m239$تشكل بقرار من الوزير المختص لجنة تختص بنظر التظلمات من القرارات التى يصدرها مكتب براءات الاختراع تطبيقا لأحكام هذا القانون برئاسة مستشار بمحاكم الاستئناف أو من فى درجته من أعضاء الهيئات القضائية وعضوية مستشار مساعد من مجلس الدولة وثلاثة من ذوى الخبرة .
ويكون التظلم أمام اللجنة مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز خمسمائة جنيه .
ويجب على اللجنة البت فى التظلم فى موعد غايته ستون يوما من تاريخ تقديم التظلم ، ويكون قرارها فى هذا الشأن نهائيا .
وفيما عدا طلبات الإلغاء المقترنة بطلب وقف التنفيذ لا يجوز قبول الدعوى أمام القضاء بشأن قرارات مكتب براءات الاختراع إلا بعد الفصل فى التظلم أو فوات ستين يوما من تاريخ تقديمه دون البت فيه .
وتنظم اللائحة التنفيذية لهذا القانون إجراءات عمل هذه اللجنة .$m239$,'6d0dc8c23d7eb5e20a86163bd84e00ef'),
(37,0,$m239$المادة 37$m239$,$m239$يكون لمكتب براءات الاختراع ولذوى الشأن الطعن فى القرار الصادر من اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ، وذلك أمام محكمة القضاء الإدارى خلال ستين يوما من تاريخ إخطار المكتب به أو ذوى الشأن بموجب كتاب مسجل موصى عليه مصحوبا بعلم الوصول وتفصل المحكمة فى الطعن على وجه الاستعجال .$m239$,'bf0539155a2aae45f68456ba60764bca'),
(38,0,$m239$المادة 38$m239$,$m239$إذا قدم طلب للحصول على براءة اختراع فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، جاز لمقدم الطلب أو لمن آلت إليه حقوقه خلال السنة التالية لتاريخ تقديم الطلب ، أن يتقدم إلى مكتب براءات الاختراع فى جمهورية مصر العربية بطلب مماثل عن ذات الموضوع وذلك وفقا للشروط والأوضاع المنصوص عليها فى هذا القانون ولائحته التنفيذية ، وفى هذه الحالة يعتد فى تحديد الأولوية بتاريخ تقديم الطلب الأول فى البلد الأجنبى .$m239$,'a37f19c51b132a4e4736ac2e4a8337c2'),
(39,0,$m239$المادة 39$m239$,$m239$لا يجوز للعاملين بمكتب براءات الاختراع أن يقدموا بالذات أو بالواسطة طلبات للحصول على براءات إلا بعد مضى ثلاث سنوات على الأقل من تاريخ تركهم الخدمة بالمكتب .$m239$,'4a8185cdb5b0c54f644d9bbb1e02523c'),
(40,0,$m239$المادة 40$m239$,$m239$تسرى الأحكام الخاصة ببراءات الاختراع على كل ما لم يرد به نص خاص فى شأن براءات نماذج المنفعة .$m239$,'4d214f5ced7eab8d94f16f515a0bad6c'),
(41,0,$m239$المادة 41$m239$,$m239$تسرى أحكام هذا القانون على كل طلب تم تقديمه لمكتب براءات الاختراع ولم تصدر بشأنه براءة اختراع قبل تاريخ العمل بهذا القانون وللطالب أن يعدل طلبه بما يتفق وأحكام هذا القانون ،
وتسرى مدة الحماية المقررة بهذا القانون على براءات الاختراع التى لم تنته مدتها فى تاريخ العمل به بما يكمل مدة حمايتها إلى المدة الواردة بالمادة ( 9 ) من هذا القانون .$m239$,'51c8cc9bae7002fff1f43195604eb241'),
(42,0,$m239$المادة 42$m239$,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الكتاب .$m239$,'dfb4027cbc42947a57f7bfe418a18ca0'),
(43,0,$m239$المادة 43$m239$,$m239$يتلقى مكتب براءات الاختراع طلبات براءات الاختراع الخاصة بالمنتجات الكيميائية الزراعية المتعلقة بالأغذية ، والمنتجات الكيميائية الصيدلية لحفظها هى والطلبات الخاصة بذات النوعية من المنتجات والتى قدمت اعتبارا من أول يناير 1995 وذلك لحين البدء فى فحصها اعتبارا من أول يناير سنة 2005 ميلادية .
وفى حالة منح البراءة المقررة للاختراعات المتعلقة بالمنتجات المنصوص عليها فى الفقرة السابقة ، تبدأ حمايتها اعتبارا من تاريخ المنح وذلك حتى نهاية المدة المنصوص عليها فى المادة ( 9 ) من هذا القانون وذلك اعتبارا من تاريخ تقديم الطلب .$m239$,'fc71ded74a74738a4b47b280228db2e3'),
(44,0,$m239$المادة 44$m239$,$m239$مع مراعاة الميعاد المقرر لبدء الفحص فى طلبات براءات الاختراع المتعلقة بالمنتجات المنصوص عليها فى المادة ( 43 ) من هذا القانون يحق لطالب البراءة أن يطلب من السلطة الحكومية المختصة منحه حقوقا تسويقية استثنائية لمنتجه فى جمهورية مصر العربية ، وذلك بالشروط الآتية :
1 - أن يكون الطالب قد أودع طلبا لهذا المنتج بمكتب البراءات المصرى اعتبارا من أول يناير سنة 1995
2 - أن يكون المنتج ذاته قد نال براءة اختراع لحمايته فى دولة عضو فى منظمة التجارة العالمية بناء على طلب قدم فى تلك الدولة اعتبارا من أول يناير سنة 1995
3 - أن يكون الطالب قد حصل على موافقة بتداول هذا المنتج فى ذات الدولة التى نال فيها البراءة اعتبارا من أول يناير سنة 1995
4 - أن يكون الطالب قد حصل على موافقة من الوزارة المختصة بتداول هذا المنتج داخل جمهورية مصر العربية .
ويمنح مكتب براءات الاختراع المصرى شهادة حق التسويق الاستئثارى بعد موافقة لجنة وزارية تشكل لهذا الغرض بقرار من رئيس الوزراء .
ولا يمنح حق التسويق الاستئثارى إذا كان واضحا من ظاهر الأوراق التى تقدم إلى مكتب براءات الاختراع للحصول على شهادة حق التسويق الاستئثارى ، أن الطلب المودع بالمكتب للحصول على البراءة قد نشر عنه قبل سنة من تاريخ إيداع الطلب .
ويتمتع الطالب بالحقوق التسويقية الاستئثارية لمنتجه والتى توافق السلطة الحكومية المختصة على منحها له ، وذلك إلى أن يبت مكتب براءات الاختراع المصرى فى طلب الحصول على البراءة ، أو لمدة خمس سنوات تحسب من تاريخ الموافقة على منحه تلك الحقوق أى المدتين أقل .
ويلغى حق التسويق الاستئثارى السابق منحه بإلغاء القرار الصادر بالتداول من الوزارة المختصة أو إذا تعسف صاحب الحق فى استعمال حقه .$m239$,'9c7f97ba337055d292e395fa3b46b8ca'),
(45,0,$m239$المادة 45$m239$,$m239$يقصد بالدائرة المتكاملة فى تطبيق أحكام هذا القانون كل منتج فى هيئته النهائية أو فى هيئته الوسيطة يتضمن مكونات - أحدها على الأقل يكون عنصرا نشطا - مثبتة على قطعة من مادة عازلة ، وتشكل مع بعض الوصلات أو كلها كيانا متكاملا يستهدف تحقيق وظيفة الكترونية محددة .
كما يقصد بالتصميم التخطيطى كل ترتيب ثلاثى الأبعاد معد لدائرة متكاملة بغرض التصنيع .$m239$,'8661a014d6bb4ec8ed3d5f60ecce7c60'),
(46,0,$m239$المادة 46$m239$,$m239$يتمتع بالحماية طبقا لأحكام هذا القانون التصميم التخطيطى الجديد للدوائر المتكاملة .
ويعد التصميم التخطيطى جديدا متى كان نتاج جهد فكرى بذله صاحبه ، ولم يكن من بين المعارف العامة الشائعة لدى أرباب الفن الصناعى المعنى .
ومع ذلك يعتبر التصميم التخطيطى جديدا إذا كان اقتران مكوناته واتصالها ببعضها جديدا فى ذاته على الرغم من أن المكونات التى يتكون منها قد تقع ضمن المعارف العامة الشائعة لدى أرباب الفن الصناعى المعنى .$m239$,'5338afd73457572366f0a0802c7067a6'),
(47,0,$m239$المادة 47$m239$,$m239$لا يتمتع بالحماية أى مفهوم أو طريقة أو نظام فنى أو معلومات مشفرة يمكن أن يشتمل عليها التصميم التخطيطى للدوائر المتكاملة .$m239$,'61dbd3c6bfb83607650d97334041a129'),
(48,0,$m239$المادة 48$m239$,$m239$تكون مدة حماية التصميمات التخطيطية للدوائر المتكاملة عشر سنوات تبدأ من تاريخ تقديم طلب تسجيلها فى جمهورية مصر العربية ، أو من تاريخ أول استغلال تجارى له فى جمهورية مصر العربية أو فى الخارج أى التاريخين أسبق .
وتنقضى مدة حماية التصميمات التخطيطية فى جميع الأحوال بمرور خمس عشرة سنة من تاريخ إعداد التصميم .$m239$,'7e175f70f766361f3edc1f3eb831bd5b'),
(49,0,$m239$المادة 49$m239$,$m239$يقدم طلب تسجيل التصميم التخطيطى من صاحب الحق فيه إلى مكتب براءات الاختراع ، ويجب أن يرفق بالطلب صورة أو رسم لهذا التصميم وعينة من كل دائرة متكاملة كانت موضع استغلال تجارى والمعلومات التى توضح الوظيفة الالكترونية للتصميم .
ويجوز للطالب أن يستبعد جزءا أو أكثر من التصميم إذا كانت الأجزاء المقدمة منه كافية لتحديد هذا التصميم وبيان وظيفته .
ويعد فى المكتب سجل لقيد طلبات التسجيل وفقا للشروط والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون ، ويستحق عن كل طلب رسم تحدده اللائحة بما لا يجاوز ألف جنيه .
ولا يقبل الطلب إذا قدم بعد انقضاء سنتين من تاريخ أول استغلال تجارى للتصميم من صاحب الحق فيه سواء فى مصر أو فى الخارج .$m239$,'45e47857955e1697c420e8f54dd989dc'),
(50,0,$m239$المادة 50$m239$,$m239$لا يجوز بغير تصريح كتابى مسبق من صاحب الحق فى التصميم التخطيطى المحمى قيام أى شخص طبيعى أو اعتبارى بأى عمل من الأعمال التالية :
1 - نسخ التصميم التخطيطى بكامله أو أى جزء جديد منه سواء تم النسخ بإدماجه فى دائرة متكاملة أو بأى طريق آخر .
2 - استيراد التصميم التخطيطى أو بيعه أو توزيعه لأغراض التجارة سواء تم ذلك على وجه الانفراد أو كان مندمجا فى دائرة متكاملة أو كان أحد المكونات لسلعة .$m239$,'1470fa4f4fa16cdcc45f1b94a80e2d33'),
(51,0,$m239$المادة 51$m239$,$m239$مع عدم الإخلال بأحكام الحماية المقررة فى هذا الباب ، يجوز لأى شخص طبيعى أو اعتبارى القيام بغير ترخيص من صاحب الحق بعمل أو أكثر مما يلى :
1 - النسخ أو الاستغلال التجارى الذى يشمل الاستيراد أو البيع أو التوزيع لدائرة متكاملة تحتوى على تصميم تخطيطى محمى أو لسلعة تدخل فى صنعها تلك الدائرة المتكاملة ، إذا وقع الفعل من شخص لا يعلم أو لم يكن متاحا له أن يعلم وقت الفعل أن تلك الدائرة المتكاملة أو السلعة تتضمن تصميما تخطيطيا محميا .
وفى هذه الحالة يجوز للحائز ، مقابل أداء تعويض عادل لصاحب الحق ، أن يتصرف فيما لديه من مخزون سلعى أو سلع أمر بشرائها ، وذلك بعد إخطاره من صاحب الحق بكتاب مسجل مصحوبا بعلم الوصول بأن الدائرة المتكاملة أو السلعة التى فى حوزته تتضمن تصميما تخطيطيا محميا .
2 - الاستخدام الشخصى أو لأغراض الاختبار أو الفحص أو التحليل أو التعليم أو التدريب أو البحث العلمى لتصميم تخطيطى محمى ، فإذا أسفر ذلك الاستخدام عن ابتكار تصميم تخطيطى جديد ، يكون للمبتكر الحق فى حمايته .
3 - ابتكار تصميم تخطيطى مطابق لتصميم تخطيطى آخر محمى وذلك نتيجة جهود مستقلة .
4 - استيراد تصميم تخطيطى محمى أو الدائرة المتكاملة التى تم إنتاجها باستخدام تصميم تخطيطى محمى سواء كانت هذه الدائرة منفردة أو مندمجة فى سلعة ، أو السلعة التى تحوى دائرة متكاملة تتضمن تصميما تخطيطيا محميا ، وذلك متى تم تداول أيها فى جمهورية مصر العربية أو فى الخارج .$m239$,'e8bf4c31b6c65c4dedf65047cc50c240'),
(52,0,$m239$المادة 52$m239$,$m239$يجوز لمكتب براءات الاختراع أن يمنح للغير ترخيصا إجباريا باستخدام تصميم تخطيطى محمى وفقا لأحكام الترخيص الإجبارى لبراءات الاختراع والمنصوص عليها فى المادتين ( 23 ) ، ( 24 ) من هذا القانون .$m239$,'1bf3177ba3f8b6a8b02c13e01421877a'),
(53,0,$m239$المادة 53$m239$,$m239$يعاقب على مخالفة أحكام المادة ( 50 ) من هذا القانون بغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مائة ألف جنيه .
وفى حالة العود تكون العقوبة الحبس الذى لا تزيد مدته على سنتين والغرامة التى لا تقل عن أربعين ألف جنيه ولا تزيد على مائتى ألف جنيه .$m239$,'aaab8eb1d9421e9867b7455b411bd2e9'),
(54,0,$m239$المادة 54$m239$,$m239$تسرى أحكام المواد ( 4 ) ، ( 33 ) ، ( 35 ) ، ( 42 ) على هذا الباب .$m239$,'75daa090a259859a545a279cf35de0f4'),
(55,0,$m239$المادة 55$m239$,$m239$تتمتع بالحماية طبقا لأحكام هذا القانون المعلومات غير المفصح عنها ، بشرط أن يتوافر فيها ما يأتى :
1 - أن تتصف بالسرية ، وذلك بأن تكون المعلومات فى مجموعها أو فى التكوين الذى يضم مفرداتها ليست معروفة أو غير متداولة بشكل عام لدى المشتغلين بالفن الصناعى الذى تقع المعلومات فى نطاقه .
2 - أن تستمد قيمتها التجارية من كونها سرية .
3 - أن تعتمد فى سريتها على ما يتخذه حائزها القانونى من إجراءات فعالة للحفاظ عليها .$m239$,'67949955329f0c9bbf588f443d21d4c8'),
(56,0,$m239$المادة 56$m239$,$m239$تمتد الحماية التى تقررها أحكام هذا القانون إلى المعلومات غير المفصح عنها التى كانت ثمرة جهود كبيرة والتى تقدم إلى الجهات المختصة بناء على طلبها للسماح بتسويق المنتجات الكيميائية الصيدلية أو الزراعية ، التى تستخدم كيانات كيميائية جديدة ، لازمة للاختبارات الواجب إجراؤها للسماح بالتسويق .
وتلتزم الجهات المختصة التى تتلقى هذه المعلومات بحمايتها من الإفشاء والاستخدام التجارى غير المنصف وذلك من تاريخ تقديم المعلومات إليها وحتى زوال صفة السرية عنها ، أو لمدة لا تزيد عن خمس سنوات أى الفترتين أقل .
ولا يعتبر تعديا على حقوق صاحب هذه المعلومات ما تقوم به الجهات المختصة من الكشف عنها لضرورة تقتضيها حماية الجمهور .$m239$,'6c0173240fc2cb756eff2fbca682118d'),
(57,0,$m239$المادة 57$m239$,$m239$يلتزم الحائز القانونى للمعلومات غير المفصح عنها باتخاذ الإجراءات الكفيلة بالمحافظة على هذه المعلومات لمنع تعرضها للتداول بمعرفة غير المختصين .
كما يلتزم بتنظيم تداول هذه المعلومات داخل المنشأة ، وقصره على الملتزمين قانونا ، بالحفاظ عليها ومنع تسريبها للغير .
ولا تنتفى مسئولية الحائز القانونى بتعدى الغير على هذه المعلومات إلا إذا أثبت أنه بذل فى الحفاظ عليها جهدا كافيا ومعقولا .
وتستمر صفة السرية للمعلومات وما يترتب عليها من حقوق فى منع الغير من التعدى عليها ، إذا ظلت معلومات غير مفصح عنها طبقا لحكم المادة ( 55 ) من هذا القانون .
وتقتصر حقوق الحائز القانونى للمعلومات غير المفصح عنها على منع الغير من التعدى عليها بأى من الأفعال التى تتعارض مع الممارسات التجارية الشريفة ، والمشار إليها فى المادة ( 58 ) من هذا القانون ، ويكون للحائز القانونى اللجوء إلى القضاء فى حالة ثبوت ارتكاب الغير لأى من هذه الأفعال .$m239$,'15aca207126b3c64f0a6a396f01b7b4b'),
(58,0,$m239$المادة 58$m239$,$m239$تعد الأفعال الآتية ، على الأخص ، متعارضة مع الممارسات التجارية الشريفة ، وينطوى ارتكابها على منافسة غير مشروعة :
1 - رشوة العاملين فى الجهة التى تحوز المعلومات بغرض الحصول عليها .
2 - التحريض على إفشاء المعلومات من جانب العاملين إذا كانت تلك المعلومات قد وصلت إلى علمهم بحكم وظيفتهم .
3 - قيام أحد المتعاقدين فى « عقود سرية المعلومات » بإفشاء ما وصل إلى علمه منها .
4 - الحصول على المعلومات من أماكن حفظها بأية طريقة من الطرق غير المشروعة كالسرقة أو التجسس أو غيرها .
5 - الحصول على المعلومات باستعمال الطرق الاحتيالية .
6 - استخدام الغير للمعلومات التى وردت إليه نتيجة الحصول عليها بأى من الأفعال السابقة مع علمه بسريتها وبأنها متحصلة عن أى من هذه الأفعال .
ويعتبر تعديا على المعلومات غير المفصح عنها ما يترتب على الأفعال المشار إليها من كشف للمعلومات ، أو حيازتها ، أو استخدامها بمعرفة الغير الذى لم يرخص له الحائز القانونى بذلك .$m239$,'3ab2d0172bb91d460309a5912fbf43bd'),
(59,0,$m239$المادة 59$m239$,$m239$لا تعد من قبيل الأفعال المتعارضة مع الممارسات التجارية الشريفة الأفعال الآتية :
1 - الحصول على المعلومات من المصادر العامة المتاحة كالمكتبات ومنها مكتبات براءات الاختراع والسجلات الحكومية المفتوحة والبحوث والدراسات والتقارير المنشورة .
2 - الحصول على المعلومات نتيجة بذل الجهود الذاتية والمستقلة التى تستهدف استخراج المعلومات من خلال الفحص والاختبار والتحليل للسلعة المتداولة فى السوق والتى تتجسد فيها المعلومات غير المفصح عنها .
3 - الحصول على المعلومات نتيجة جهود البحث العلمى والابتكار والاختراع والتطوير والتعديل والتحسين التى يبذلها المجتهدون مستقلين عن صاحب المعلومات غير المفصح عنها .
4 - حيازة واستعمال المعلومات المعروفة والمتاحة والتى يجرى تداولها فيما بين المشتغلين بالفن الصناعى الذى تقع المعلومات فى نطاقه .$m239$,'72d6c53fe7fa606559715adc95ce88d7'),
(60,0,$m239$المادة 60$m239$,$m239$يحق لصاحب المعلومات غير المفصح عنها أو لخلفه أن يتنازل عنها للغير بعوض أو بغير عوض .$m239$,'19f401083c0fca8c87781b61a28418c6'),
(61,0,$m239$المادة 61$m239$,$m239$مع عدم الإخلال بأية عقوبة أشد ينص عليها أى قانون آخر ، يعاقب كل من يقوم بوسيلة غير مشروعة بالكشف عن المعلومات المحمية طبقا لأحكام هذا القانون أو بحيازتها أو باستخدامها مع علمه بسريتها وبأنها متحصلة عن تلك الوسيلة ، بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على خمسين ألف جنيه .
وفى حالة العود تكون العقوبة الحبس مدة لا تزيد على سنتين والغرامة التى لا تقل عن خمسين ألف جنيه ولا تزيد على مائة ألف جنيه .$m239$,'93c484f0e892a49d4842b930869fcd26'),
(62,0,$m239$المادة 62$m239$,$m239$تسرى أحكام المواد ( 4 ) ، ( 33 ) ، ( 35 ) ، ( 42 ) على هذا الباب .$m239$,'75daa090a259859a545a279cf35de0f4'),
(63,0,$m239$المادة 63$m239$,$m239$العلامة التجارية هى كل ما يميز منتجا سلعة كان أو خدمة عن غيره ، وتشمل على وجه الخصوص الأسماء المتخذة شكلا مميزا ، والإمضاءات ، والكلمات ، والحروف ، والأرقام ، والرسوم ، والرموز ، وعناوين المحال ، والدمغات ، والأختام ، والتصاوير ، والنقوش البارزة ، ومجموعة الألوان التى تتخذ شكلا خاصا ومميزا ، وكذلك أى خليط من هذه العناصر إذا كانت تستخدم أو يراد أن تستخدم إما فى تمييز منتجات عمل صناعى ، أو استغلال زراعى ، أو استغلال للغابات ، أو لمستخرجات الأرض ، أو أية بضاعة ، وإما للدلالة على مصدر المنتجات ، أو البضائع ، أو نوعها ، أو مرتبتها ، أو ضمانها ، أو طريقة تحضيرها وإما للدلالة على تأدية خدمة من الخدمات .
وفى جميع الأحوال يتعين أن تكون العلامة التجارية مما يدرك بالبصر .$m239$,'a8414db3a607ca370ea8b23c9be3687a'),
(64,0,$m239$المادة 64$m239$,$m239$تختص مصلحة التسجيل التجارى بتسجيل العلامات التجارية فى السجل الخاص بهذه العلامات وفقا لأحكام هذا القانون ولائحته التنفيذية وذلك مع مراعاة حكم المادتين ( 3 ، 4 ) من القرار بقانون رقم 115 لسنة 1958 فى المكاتبات واللافتات بوجوب استعمال اللغة العربية .$m239$,'0352727502ad6e4b5369996b78e5f019'),
(65,0,$m239$المادة 65$m239$,$m239$يعتبر من قام بتسجيل العلامة مالكا لها متى اقترن ذلك باستعمالها خلال الخمس السنوات التالية للتسجيل ، ما لم يثبت أن أولوية الاستعمال كانت لغيره .
ويحق لمن كان أسبق إلى استعمال العلامة ممن سجلت باسمه الطعن ببطلان التسجيل خلال الخمس السنوات المذكورة .
ومع ذلك يجوز الطعن ببطلان تسجيل العلامة دون التقيد بأى مدة متى اقترن التسجيل بسوء نية .$m239$,'1ff5491a43ce1d46b28f4c5918878a1e'),
(66,0,$m239$المادة 66$m239$,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل الحق فى التقدم إلى مصلحة التسجيل فى جمهورية مصر العربية وما يترتب على ذلك من حقوق طبقا لأحكام هذا القانون بطلب تسجيل علامة تجارية .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بالحقوق المنصوص عليها فى هذا الباب ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'2cccd85e6b22df0caca6033225b7e4cd'),
(67,0,$m239$المادة 67$m239$,$m239$لا يسجل كعلامة تجارية أو كعنصر منها ما يأتى :
1 - العلامات الخالية من أية صفة مميزة أو المكونة من عبارات أو بيانات ليست إلا التسمية التى يطلقها العرف على المنتجات أو الرسم أو الصور العادية لها .
2 - العلامات المخلة بالنظام العام أو الآداب العامة .
3 - الشعارات العامة والأعلام وغيرها من الرموز الخاصة بالدولة أو الدول الأخرى أو المنظمات الإقليمية أو الدولية ، وكذلك أى تقليد لها .
4 - العلامات المطابقة أو المشابهة للرموز ذات الصبغة الدينية .
5 - رموز الصليب الأحمر أو الهلال الأحمر أو غيرها من الرموز المشابهة وكذلك العلامات التى تكون تقليدا لها .
6 - صور الغير أو شعاراته ما لم يوافق على استعمالها .
7 - البيانات الخاصة بدرجات الشرف التى لا يثبت طالب التسجيل حصوله عليها .
8 - العلامات والمؤشرات الجغرافية التى من شأنها أو تضلل الجمهور أو تحدث لبسا لديه أو التى تتضمن بيانات كاذبة عن مصدر المنتجات من السلع أو الخدمات أو عن صفاتها الأخرى ، وكذلك العلامات التى تحتوى على بيان اسم تجارى وهمى مقلد أو مزور .$m239$,'afb1ac9f596aa2f29a35a6f00529701f'),
(68,0,$m239$المادة 68$m239$,$m239$يكون لصاحب العلامة التجارية المشهورة عالميا وفى جمهورية مصر العربية حق التمتع بالحماية المقررة فى هذا القانون ولو لم تسجل فى جمهورية مصر العربية .
ويجب على المصلحة أن ترفض من تلقاء نفسها أى طلب لتسجيل علامة مطابقة لعلامة مشهورة يتضمن استخدام العلامة لتمييز منتجات تماثل المنتجات التى تستخدم العلامة المشهورة فى تمييزها ، ما لم يكن الطلب مقدما من صاحب العلامة المشهورة .
ويسرى الحكم المتقدم على طلبات التسجيل التى تنصب على منتجات لا تماثل المنتجات التى تستخدم العلامة المشهورة فى تمييزها إذا كانت العلامة المشهورة مسجلة فى إحدى الدول الأعضاء فى منظمة التجارة العالمية وفى جمهورية مصر العربية وكان استخدام العلامة على المنتجات غير المماثلة من شأنها أن يحمل الغير على الاعتقاد بوجود صلة بين صاحب العلامة المشهورة وتلك المنتجات ، وأن يؤدى هذا الاستخدام إلى إلحاق ضرر بصاحب العلامة المشهورة .$m239$,'cebb5af1e1222d9e4bdb3e0b2def99e1'),
(69,0,$m239$المادة 69$m239$,$m239$تستخدم العلامة التجارية الجماعية لتمييز منتج ينتجه مجموعة من الأشخاص ينتمون إلى كيان معين ولو كان لا يملك بذاته منشأة صناعية أو تجارية .
ويقدم طلب تسجيل العلامة بواسطة ممثل هذا الكيان .$m239$,'ffa13bbb6e041018e32f2f5f6572f992'),
(70,0,$m239$المادة 70$m239$,$m239$للوزير المختص - تحقيقا للمصلحة العامة - أن يرخص للأشخاص الطبيعيين أو الاعتباريين الذين يزاولون أعمال مراقبة المنتجات أو فحصها بتسجيل علامة تخصص للدلالة على إجراء المراقبة أو الفحص لتلك المنتجات وذلك فيما يتعلق بمصدرها أو عناصر تركيبها أو طريقة إنتاجها أو صفتها أو حقيقتها أو أية خاصية أخرى تميزها .
ولا يجوز التصرف فى تلك العلامة إلا بموجب ترخيص خاص من الوزير المختص .$m239$,'6d745efe16c0d1605b1f9f1d11dcfd23'),
(71,0,$m239$المادة 71$m239$,$m239$يستنفد حق مالك العلامة فى منع الغير من استيراد أو استخدام أو بيع أو توزيع المنتجات التى تميزها هذه العلامة إذا قام بتسويق تلك المنتجات فى أية دولة أو رخص للغير بذلك .$m239$,'b866dfe817d28bcbe88ed9efc79de6ec'),
(72,0,$m239$المادة 72$m239$,$m239$تمنح العلامة الموضوعة على منتجات معروضة فى المعارض الوطنية أو الدولية حماية مؤقتة ، ولا يترتب على تلك الحماية امتداد المدة المنصوص عليها فى المادة ( 75 ) من هذا القانون .
ويعين الوزير المختص هذه المعارض بموجب قرار يصدره وتحدد اللائحة التنفيذية لهذا القانون شروط وأوضاع وإجراءات منح تلك الحماية .$m239$,'0a4e8e853787ee60237a1a50a812a11e'),
(73,0,$m239$المادة 73$m239$,$m239$يقدم طلب تسجيل العلامة إلى مصلحة التسجيل التجارى وفقا للأوضاع وبالشروط التى تقررها اللائحة التنفيذية لهذا القانون ، وتحدد هذه اللائحة فئات الرسوم المستحقة على الطلب وسائر الإجراءات المتعلقة بالعلامة بما لا يجاوز فى مجموعه خمسة آلاف جنيه .$m239$,'993dd52baf748b746de27ee83efcf503'),
(74,0,$m239$المادة 74$m239$,$m239$تسجل العلامة عن فئة أو نوعية واحدة أو أكثر من المنتجات التى ينتجها طالب التسجيل ، أو يعتزم إنتاجها وذلك وفقا للأوضاع والشروط التى تحددها اللائحة التنفيذية لهذا القانون .
ويقتصر استخدامها على الفئة أو الفئات أو نوعية المنتجات المسجلة عنها .
وتسرى أحكام المادة ( 91 ) من هذا القانون على الفئات التى لم تستخدم فى شأنها العلامة بصفة جدية .$m239$,'bebaeb9e3c746708054a718070c12250'),
(75,0,$m239$المادة 75$m239$,$m239$إذا أودع طلب تسجيل علامة فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، جاز لمقدم الطلب أو لمن آلت إليه حقوقه - خلال الستة الأشهر التالية لتاريخ تقديم الطلب - أن يتقدم إلى المصلحة فى جمهورية مصر العربية بطلب مماثل يتعلق بذات العلامة ، وينصب على ذات المنتجات التى يشملها الطلب السابق ، وذلك كله وفقا للشروط والأوضاع المنصوص عليها فى هذا القانون ولائحته التنفيذية .
وفى هذه الحالة يعتد فى تحديد الأولوية بتاريخ تقديم الطلب الأول فى البلد الأجنبى .$m239$,'0ea1ae5bc4bc85d90b036e49c8984355'),
(76,0,$m239$المادة 76$m239$,$m239$إذا طلب شخصان أو أكثر فى وقت واحد تسجيل ذات العلامة أو تسجيل علامات متشابهة عن فئة واحدة من المنتجات ، توقف إجراءات التسجيل إلى أن يقدم أحدهم تنازلا من منازعيه أو حكما واجب النفاذ صادرا لصالحه .$m239$,'b4bb65af23a3940de3134755d8c077d4'),
(77,0,$m239$المادة 77$m239$,$m239$يجوز لمصلحة التسجيل التجارى بقرار مسبب أن تكلف طالب التسجيل بإجراء التعديلات اللازمة على العلامة المطلوب تسجيلها لتحديدها وتوضيحها لتفادى التباسها بعلامة أخرى سبق تسجيلها أو تقديم طلب بذلك .
ويخطر الطالب بهذا القرار بموجب كتاب موصى عليه مصحوبا بعلم الوصول وذلك خلال ثلاثين يوما من تاريخ صدوره .
ويجوز للمصلحة أن ترفض الطلب إذا لم ينفذ الطالب ما كلفته به المصلحة من تعديلات خلال ستة أشهر من تاريخ الإخطار .$m239$,'5d58331ba6026acef29d1d1592c0afa1'),
(78,0,$m239$المادة 78$m239$,$m239$يجوز للطالب أن يتظلم من قرار المصلحة المشار إليها فى المادة ( 77 ) من هذا القانون وذلك خلال ثلاثين يوما من تاريخ إخطاره به ، وتنظر التظلمات لجنة أو أكثر تشكل بقرار من الوزير المختص من ثلاثة أعضاء أحدهم من أعضاء مجلس الدولة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد تشكيل اللجنة وإجراءات تقديم التظلمات ونظرها والبت فيها .$m239$,'109ac2b7afd5f29e94709978fe47c4c5'),
(79,0,$m239$المادة 79$m239$,$m239$دون إخلال بحق صاحب الشأن فى الطعن طبقا للقانون إذا أيدت اللجنة المشار إليها فى المادة السابقة القرار الصادر برفض طلب تسجيل العلامة لتشابهها مع علامة أخرى سبق تسجيلها عن منتجات واحدة أو عن فئة واحدة منها فلا يجوز تسجيل هذه العلامة للطالب إلا بناء على حكم قضائى واجب النفاذ .$m239$,'0fc6cf240866b6fbaa46fa402787cfee'),
(80,0,$m239$المادة 80$m239$,$m239$يجب على المصلحة نشر قرار قبول طلب تسجيل العلامة فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية ، وذلك بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .
ويجوز لكل ذى شأن أن يعترض كتابة على تسجيل العلامة بإخطار يوجه إلى المصلحة متضمنا أسباب الاعتراض وذلك خلال ستين يوما من تاريخ النشر وفقا للأوضاع التى تحددها اللائحة التنفيذية لهذا القانون .
وعلى المصلحة أن ترسل صورة من إخطار الاعتراض إلى طالب التسجيل وذلك خلال ثلاثين يوما من تاريخ ورود الإخطار إليها .
وعلى طالب التسجيل أن يقدم للمصلحة ردا كتابيا مسببا على الاعتراض ، خلال ثلاثين يوما من تاريخ تسلمه الإخطار ، وإلا اعتبر متنازلا عن طلب التسجيل .
وتحدد اللائحة التنفيذية لهذا القانون القواعد والإجراءات المنظمة لذلك .$m239$,'1bbef4e0a7222038e4539abbc093a109'),
(81,0,$m239$المادة 81$m239$,$m239$تصدر المصلحة قرارها فى الاعتراض مسببا إما بقبول التسجيل أو رفضه ، وذلك بعد سماع طرفى النزاع ، ويجوز لها أن تضمن قرارها بالقبول إلزام الطالب بتنفيذ ما تراه ضروريا من الاشتراطات لتسجيل العلامة .$m239$,'9e3e47473326efa853fd5a012463dc2a'),
(82,0,$m239$المادة 82$m239$,$m239$يجوز الطعن فى قرار المصلحة المشار إليه فى المادة ( 81 ) من هذا القانون أمام محكمة القضاء الإدارى المختصة وفقا للإجراءات والمواعيد التى ينص عليها قانون مجلس الدولة .$m239$,'792bd68e4fe6da7bb4cbcde7b60f3c89'),
(83,0,$m239$المادة 83$m239$,$m239$يكون تسجيل العلامة بقرار من المصلحة ، وينشر هذا القرار فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .
ويبدأ أثر التسجيل من تاريخ تقديم الطلب .$m239$,'2deb4cb542e5b05fbe7d316f74dac77e'),
(84,0,$m239$المادة 84$m239$,$m239$تمنح المصلحة مالك العلامة المسجلة شهادة بالبيانات التى نشرت عنها فى الجريدة المشار إليها .$m239$,'611146b867ac7fac48a8760296159655'),
(85,0,$m239$المادة 85$m239$,$m239$لمالك العلامة المسجلة أن يطلب من المصلحة كتابة إدخال أى تعديل على العلامة لا يمس بذاتيتها مساسا جوهريا ، وله كذلك طلب إدخال أى تعديل بالحذف دون الإضافة على بيان المنتجات الخاصة بالعلامة .
ويصدر القرار بقبول طلب التعديل أو رفضه وفقا للشروط المقررة لقرارات قبول طلبات التسجيل الأصلية .
وتسرى فى هذا الشأن الأحكام المقررة للاعتراض والتظلم والطعن والنشر بالنسبة لهذه القرارات .$m239$,'cadc786a3aaea5cfbf2e45a2410f4d61'),
(86,0,$m239$المادة 86$m239$,$m239$لكل شخص أن يطلب الاطلاع على العلامات المسجلة أو الحصول على مستخرجات أو صور من السجل الخاص بتسجيلها وذلك وفقا للقواعد والإجراءات التى تقررها اللائحة التنفيذية لهذا القانون ومقابل رسم تحدده هذه اللائحة بما لا يجاوز مائة جنيه .$m239$,'a3734bb41e93ba864c19201b36c434a6'),
(87,0,$m239$المادة 87$m239$,$m239$يجوز نقل ملكية العلامة أو تقرير أى حق عينى عليها أو الحجز عليها استقلالا عن المحل التجارى أو مشروع الاستغلال ، وذلك وفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'5611a10618d28d97968f449eea91e9df'),
(88,0,$m239$المادة 88$m239$,$m239$يشمل نقل ملكية المحل التجارى أو مشروع الاستغلال العلامات المسجلة باسم المالك إذا كانت ذات ارتباط وثيق بالمحل التجارى أو بمشروع الاستغلال ما لم يتفق على غير ذلك .
وإذا لم يشمل نقل ملكية المحل التجارى أو مشروع الاستغلال العلامة التجارية كان لمالك العلامة استخدامها على ذات نوعية المنتجات أو الفئة أو الفئات المسجلة عنها ، ما لم يتفق على غير ذلك .$m239$,'bcfe176c4c6adb04d154a30cc898186d'),
(89,0,$m239$المادة 89$m239$,$m239$لا يكون نقل ملكية العلامة أو تقرير حق الانتفاع عليها أو رهنها حجة على الغير إلا بعد التأشير بذلك فى السجل ونشره بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'b248e15df66be2346d7b501c9efd0144'),
(90,0,$m239$المادة 90$m239$,$m239$مدة الحماية المترتبة على تسجيل العلامة عشر سنوات ، وتمتد لمدة أو لمدد مماثلة بناء على طلب صاحبها فى كل مرة خلال السنة الأخيرة من مدة الحماية ومقابل سداد الرسم المستحق على طلب التسجيل لأول مرة .
ويجوز بعد فوات تلك المدة بما لا يجاوز ستة شهور أن يتقدم صاحبها بطلب تجديد مدة الحماية ، وذلك مقابل أداء الرسم المقرر ورسم إضافى تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز خمسمائة جنيه وإلا قامت المصلحة بشطب العلامة .$m239$,'c0245f2cb3ed171106a55e0f7a8ef46f'),
(91,0,$m239$المادة 91$m239$,$m239$يجوز للمحكمة المختصة بناء على طلب كل ذى شأن أن تقضى بشطب تسجيل العلامة بحكم قضائى واجب النفاذ ، إذا ثبت لديها أنها لم تستعمل بصفة جدية - دون مبرر تقدره - لمدة خمس سنوات متتالية .$m239$,'8aa172f3b683696ed7ddac8f38a4e753'),
(92,0,$m239$المادة 92$m239$,$m239$يجوز إعادة تسجيل العلامة بعد شطبها - لصاحبها دون غيره - وذلك خلال ثلاث سنوات من تاريخ الشطب طبقا للأوضاع وبذات الإجراءات المقررة للتسجيل ومقابل سداد رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه .
ويجوز بعد فوات المدة المذكورة تسجيل العلامة لصاحبها ولغيره عن ذات المنتجات وذلك طبقا للأوضاع وبذات الإجراءات والرسوم المقررة للتسجيل أول مرة .
ومع ذلك إذا كان الشطب تنفيذا لحكم قضائى واجب النفاذ بعدم الأحقية فى تسجيل العلامة جاز تسجيلها لصالح الغير فور الشطب .$m239$,'1ae585a9c7f9dcd425bff2e1eec1a893'),
(93,0,$m239$المادة 93$m239$,$m239$ينشر قرار مد التسجيل أو تجديده أو شطبه أو إعادته بعد الشطب فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'1277879f4c6609c49e22d1f27f2ea162'),
(94,0,$m239$المادة 94$m239$,$m239$يكون للمصلحة ولكل ذى شأن فى غير الأحوال المنصوص عليها فى المادة ( 85 ) من هذا القانون اللجوء إلى المحكمة المختصة بطلب إضافة أى بيان للسجل أغفل تدوينه أو بحذف أو تعديل أى بيان دون فيه دون وجه حق أو كان غير مطابق للحقيقة .$m239$,'5bb6a3259f0047957a9c39bbde9576b3'),
(95,0,$m239$المادة 95$m239$,$m239$لمالك العلامة أن يرخص لشخص أو أكثر طبيعى أو اعتبارى باستعمال العلامة على كل أو بعض المنتجات المسجلة عنها العلامة ، ولا يحول الترخيص للغير دون استعمال مالك العلامة لها ما لم يتفق على غير ذلك .
ولا يجوز لمالك العلامة إنهاء عقد الترخيص أو عدم تجديده إلا لسبب مشروع .$m239$,'c456f4c57b96b24d36c6fc4b4f106a30'),
(96,0,$m239$المادة 96$m239$,$m239$يشترط لقيد عقد الترخيص فى سجل العلامات التجارية أن يكون موثقا أو مصدقا على صحة التوقيعات عليه . ولا يكون الترخيص نافذا فى حق الغير إلا بعد إجراء هذا القيد والنشر عنه بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'dc6bde6f964d8628f0929e9b9142d2ff'),
(97,0,$m239$المادة 97$m239$,$m239$لا يجوز للمرخص له التنازل عن عقد الترخيص للغير إلا مع التنازل عن المحل التجارى أو مشروع الاستغلال الذى تستخدم العلامة فى تمييز منتجاته وذلك ما لم يتفق على خلافه .
ولا يكون رهنه أو تقرير حق الانتفاع عليه حجة قبل الغير إلا بعد قيده فى السجل والنشر عنه بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'6f7324b2dc77b7bf3fda76c742dd79b9'),
(98,0,$m239$المادة 98$m239$,$m239$لا يجوز أن يتضمن عقد الترخيص أية شروط تقيد المرخص له بقيود غير ضرورية للحفاظ على الحقوق المترتبة على تسجيل العلامة .
ومع ذلك يجوز أن يتضمن عقد الترخيص الشروط التالية :
1 - تحديد مدة الترخيص باستعمال العلامة .
2 - الشروط المعقولة التى تكفل لمالك العلامة مراقبة جودة المنتجات التى تميزها العلامة موضوع الترخيص وبما لا يتعارض مع حرية المرخص له فى الإدارة والتشغيل .
3 - إلزام المرخص له بالامتناع عن أى عمل من شأنه أن يؤدى إلى الإقلال من شأن المنتجات التى تميزها العلامة .$m239$,'ae765cdb743ad93a90e324ebb9c442b7'),
(99,0,$m239$المادة 99$m239$,$m239$لمالك العلامة أو المرخص له أن يطلب شطب قيد عقد الترخيص ، وتخطر المصلحة الطرف الآخر بهذا الطلب .
ويكون الشطب فى الحالات وبالإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'bf5834ac928b1a2b84bdda9a5bca1b15'),
(100,0,$m239$المادة 100$m239$,$m239$يعتبر بيانا تجاريا فى نطاق تطبيق أحكام هذا القانون ، أى إيضاح يتعلق بصفة مباشرة أو غير مباشرة بما يأتى :
1 - عدد المنتجات أو مقدارها ، أو مقاسها ، أو كيلها ، أو طاقتها ، أو وزنها .
2 - الجهة أو البلد الذى صنعت أو أنتجت فيه المنتجات .
3 - طريقة صنع أو إنتاج المنتجات .
4 - العناصر والمكونات الداخلة فى تركيب المنتجات .
5 - اسم أو صفة الصانع أو المنتج .
6 - وجود براءات اختراع أو غيرها من حقوق الملكية الصناعية أو أية امتيازات أو جوائز أو مميزات تجارية أو صناعية .
7 - الاسم أو الشكل الذى تعرف به بعض المنتجات .$m239$,'2aa4735ee50bd88239270cbfaf2b6a72'),
(101,0,$m239$المادة 101$m239$,$m239$يجب أن يكون البيان التجارى مطابقا للحقيقة من جميع الوجوه سواء أكان موضوعا على ذات المنتجات أو على الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلان أو غير ذلك مما يستعمل فى عرض المنتجات على الجمهور ، أو كان موضوعا على المحال أو المخازن أو بها أو على عناوينها .$m239$,'adc5c298024eb5841fe4c1f6d6c4475c'),
(102,0,$m239$المادة 102$m239$,$m239$لا يجوز ذكر ميداليات أو دبلومات أو جوائز أو درجات فخرية من أى نوع إلا بالنسبة للمنتجات التى تنطبق عليها هذه المميزات ، وبالنسبة للأشخاص والأسماء التجارية الذين اكتسبوها أو لمن آلت إليهم حقوقهم ، ويجب أن يشتمل ذلك على بيان صحيح بتاريخها ونوعها وجهة منحها والمناسبة التى منحت فيها .
ولا يجوز لمن اشترك مع آخرين فى عرض منتجات أن يستعمل لمنتجاته الخاصة المميزات التى منحت للمعروضات المشتركة ما لم يبين بطريقة واضحة مصدر تلك المميزات ونوعها .$m239$,'25b7967605e93ac01eae65cfb463bbbd'),
(103,0,$m239$المادة 103$m239$,$m239$إذا كان مقدار المنتجات أو مقاسها أو كيلها أو طاقتها أو وزنها أو مصدرها أو العناصر الداخلة فى تركيبها من العوامل التى لها دخل فى تقدير قيمتها ، جاز بقرار من الوزير المختص منع بيع تلك المنتجات أو عرضها للبيع أو استيرادها ما لم تحمل هذه البيانات .
ويصدر قرار من الوزير المختص بتحديد الكيفية التى توضع بها هذه البيانات على المنتجات باللغة العربية ، وبالإجراءات التى يستعاض عنها بها عند الاقتضاء .$m239$,'5ddeaad4c0d5ef173f823f37f2fd660a'),
(104,0,$m239$المادة 104$m239$,$m239$المؤشرات الجغرافية هى التى تحدد منشأ سلعة ما فى منطقة أو جهة فى دولة عضو فى منظمة التجارة العالمية أو تعامل جمهورية مصر العربية معاملة المثل متى كانت النوعية أو السمعة أو السمات الأخرى لهذه السلعة والمؤثرة فى ترويجها راجعة بصورة أساسية إلى منشأها الجغرافى .
ويشترط لحماية هذه المؤشرات أن تكون قد اكتسبت الحماية فى بلد المنشأ .$m239$,'158144b65f6adfee41c76c75634c29ad'),
(105,0,$m239$المادة 105$m239$,$m239$لا يجوز لأى شخص فى جهة ذات شهرة خاصة فى إنتاج سلعة ما أن يضع على المنتجات التى يتجر فيها مؤشرات جغرافية بطريقة تضلل الجمهور بأنها نشأت فى الجهة ذات الشهرة الخاصة .$m239$,'9d1b04df140b611cf8ad7b4eec4ede41'),
(106,0,$m239$المادة 106$m239$,$m239$لا يجوز استخدام أية وسيلة فى تسمية أو عرض سلعة ما توحى بطريقة تضلل الجمهور بأنها نشأت فى منطقة جغرافية على خلاف المنشأ الحقيقى لها .$m239$,'f9dda70e08ea2105602d80d07edaa911'),
(107,0,$m239$المادة 107$m239$,$m239$لا يجوز لمنتج سلعة فى جهة ذات شهرة خاصة فى إنتاجها أن يضع مؤشرا جغرافيا على ما ينتجه من سلع شبيهة فى مناطق أخرى يكون من شأنها أن توحى بأنها منتجة فى الجهة المشار إليها .$m239$,'c6fbd3d5093fbb632e92966b4637819c'),
(108,0,$m239$المادة 108$m239$,$m239$يجوز أن تطلق على بعض المنتجات أسماء جغرافية أصبحت تدل فى الاصطلاح التجارى بصورة أساسية على جنس المنتج دون المنشأ الجغرافى له .$m239$,'34b5a6a86ba48d7505c08cdceddf870a'),
(109,0,$m239$المادة 109$m239$,$m239$يشترط لتسجيل علامة تجارية تشتمل على مؤشر جغرافى أن يكون إنتاج السلعة بصفة مستمرة بمعرفة طالب التسجيل فى المنطقة الجغرافية ذات الشهرة الخاصة .$m239$,'e686803167f144168ded3a164853265f'),
(110,0,$m239$المادة 110$m239$,$m239$لا يجوز تسجيل العلامة التجارية التى تشتمل على مؤشر جغرافى إذا كان استعمالها من شأنه أن يضلل الجمهور فيما يتعلق بالمنشأ الحقيقى للسلعة .$m239$,'0556504ca117a4ffee0bbbd59a2aadb1'),
(111,0,$m239$المادة 111$m239$,$m239$يجوز تسجيل العلامة التجارية التى تشتمل على مؤشر جغرافى إذا كان الحق فى هذه العلامة قد اكتسب من خلال استعمالها بحسن نية قبل تاريخ العمل بهذا القانون أو قبل منح المؤشر الجغرافى الحماية فى بلد المنشأ .$m239$,'084ad0e869d795b07437b2d655ffefe7'),
(112,0,$m239$المادة 112$m239$,$m239$يجوز لكل ذى مصلحة رفع الدعوى أمام المحكمة الابتدائية المختصة بالطرق المعتادة بطلب منع استخدام أى مؤشر جغرافى لم تتضمنه علامة تجارية مسجلة إذا كان من شأن هذا الاستخدام تضليل الجمهور بشأن المنشأ الحقيقى للسلعة .
وتكون المحكمة الابتدائية المختصة هى المحكمة التى يقع فى دائرتها مكان استخدام المؤشر الجغرافى .$m239$,'5fa522cded8a5ee0a76c3b239b35225a'),
(113,0,$m239$المادة 113$m239$,$m239$مع عدم الإخلال بأية عقوبة أشد فى أى قانون آخر ، يعاقب بالحبس مدة لا تقل عن شهرين وبغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه أو بإحدى هاتين العقوبتين :
1 - كل من زور علامة تجارية تم تسجيلها طبقا للقانون أو قلدها بطريقة تدعو إلى تضليل الجمهور .
2 - كل من استعمل بسوء قصد علامة تجارية مزورة أو مقلدة .
3 - كل من وضع بسوء قصد على منتجاته علامة تجارية مملوكة لغيره .
4 - كل من باع أو عرض للبيع أو التداول أو حاز بقصد البيع أو التداول منتجات عليها علامة تجارية مزورة أو مقلدة أو موضوعة بغير حق مع علمه بذلك .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن شهرين والغرامة التى لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة المنتجات محل الجريمة أو المبالغ أو الأشياء المتحصلة منها ، وكذلك الأدوات التى استخدمت فى ارتكابها .
ويجوز للمحكمة عند الحكم بالإدانة أن تقضى بغلق المنشأة التى استغلها المحكوم عليه فى ارتكاب الجريمة مدة لا تزيد على ستة أشهر ، ويكون الغلق وجوبيا فى حالة العود .$m239$,'5459a301c06370488fda8a4e6b62eef4'),
(114,0,$m239$المادة 114$m239$,$m239$مع عدم الإخلال بأية عقوبة أشد فى أى قانون آخر ، يعاقب بالحبس مدة لا تزيد على ستة أشهر وبغرامة لا تقل عن ألفى جنيه ولا تجاوز عشرة آلاف جنيه أو بإحدى هاتين العقوبتين :
1 - كل من وضع بيانا تجاريا غير مطابق للحقيقة على منتجاته أو محاله أو مخازنه أو بها أو على عناوينها أو على الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلام أو على غير ذلك مما يستعمل فى عرض المنتجات على الجمهور .
2 - كل من ذكر بغير حق على علاماته أو أوراقه التجارية بيانا يؤدى إلى الاعتقاد بحصول تسجيلها .
3 - كل من استعمل علامة غير مسجلة فى الأحوال المنصوص عليها فى الفقرات ( 2 ، 3 ، 5 ، 7 ، 8 ) من المادة ( 67 ) من هذا القانون .
4 - كل من ذكر ميداليات أو دبلومات أو جوائز أو درجات فخرية من أى نوع كان على منتجات لا تتعلق بها أو على أشخاص أو أسماء تجارية لم يكتسبوها .
5 - كل من اشترك مع آخرين فى عرض منتجات واستعمل لمنتجاته الخاصة المميزات التى منحت للمعروضات المشتركة ما لم يبين بطريقة واضحة مصدر تلك المميزات ونوعها .
6 - كل من وضع على السلع التى يتجر بها - فى جهة ذات شهرة خاصة فى إنتاج سلعة معينة - مؤشرات جغرافية بطريقة تضلل الجمهور بأنها نشأت فى هذه الجهة .
7 - كل من استخدم أية وسيلة فى تسمية أو عرض سلعة ما توحى بطريقة تضلل الجمهور بأنها نشأت فى منطقة جغرافية ذات شهرة خاصة على خلاف المنشأ الحقيقى لها .
8 - كل منتج سلعة فى جهة ذات شهرة خاصة فى إنتاجها وضع مؤشرا جغرافيا على ما ينتجه من سلع شبيهة فى مناطق أخرى يكون من شأنها أن توحى بأنها منتجة فى الجهة المشار إليها .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن شهر والغرامة التى لا تقل عن أربعة آلاف جنيه ولا تجاوز عشرين ألف جنيه .$m239$,'3f1cc4b7f38991d8ae5f28bebc1bc56e'),
(115,0,$m239$المادة 115$m239$,$m239$لرئيس المحكمة المختصة بأصل النزاع بناء على طلب كل ذى شأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة وعلى وجه الخصوص :
1 - إثبات واقعة الاعتداء على الحق محل الحماية .
2 - إجراء حصر ووصف تفصيلى للآلات والأدوات التى تستخدم أو تكون قد استخدمت فى ارتكاب الجريمة والمنتجات أو البضائع أو عناوين المحال أو الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلان أو غير ذلك مما تكون قد وضعت عليه العلامة أو البيان أو المؤشر الجغرافى موضوع الجريمة ، وكذلك البضائع المستوردة من الخارج إثر ورودها .
3 - توقيع الحجز على الأشياء المذكورة فى البند ( 2 ) .
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة المختصة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'7430444a44417a44a015496e863ce09a'),
(116,0,$m239$المادة 116$m239$,$m239$يجوز لمن صدر ضده الأمر أن يتظلم منه إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدوره أو إعلانه له حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا .$m239$,'59d66e3b82313a84eeef3db9017fdfde'),
(117,0,$m239$المادة 117$m239$,$m239$يجوز للمحكمة فى أية دعوى مدنية أو جنائية أن تحكم ببيع الأشياء المحجوزة أو التى تحجز فيما بعد واستنزال ثمنها من التعويضات أو الغرامات أو الأمر بالتصرف فيها بأية طريقة أخرى تراها المحكمة مناسبة .
وتأمر المحكمة بإتلاف العلامات المخالفة ، ويجوز لها - عند الاقتضاء - الأمر بإتلاف المنتجات أو البضائع أو عناوين المحال أو الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلان أو غير ذلك مما يحمل تلك العلامة أو يحمل بيانات أو مؤشرات جغرافية بالمخالفة لأحكام هذا الكتاب ، وكذلك إتلاف الآلات والأدوات التى استعملت بصفة خاصة فى ارتكاب الجريمة .
ويجوز للمحكمة أيضا أن تأمر بنشر الحكم فى جريدة واحدة أو أكثر على نفقة المحكوم عليه .
وللمحكمة أن تأمر بكل أو ببعض ما سبق حتى فى حالة الحكم بالبراءة .$m239$,'05aaa322f7f70f2f10fdac45427c30ee'),
(118,0,$m239$المادة 118$m239$,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الباب .$m239$,'7b313a3096de9ba76b500f5910c2c6b0'),
(119,0,$m239$المادة 119$m239$,$m239$يعتبر تصميما أو نموذجا صناعيا كل ترتيب للخطوط وكل شكل مجسم ، بألوان أو بغير ألوان إذا اتخذ مظهرا مميزا يتسم بالجدة وكان قابلا للاستخدام الصناعى .$m239$,'68dcead76fdd5498ea79305b114c9cc9'),
(120,0,$m239$المادة 120$m239$,$m239$يفقد التصميم أو النموذج الصناعى وصف الجدة إذا :
1 - تم عرضه على الجمهور أو وصفه أو عرض استخداماته قبل تاريخ إيداع طلب تسجيله .
ومع ذلك لا يفقد التصميم أو النموذج الصناعى وصف الجدة إذا كان هذا العرض أو الوصف قد تم بعد تقديم طلب تسجيله فى دولة عضو فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل أو كان العرض فى أحد المعارض الوطنية أو الدولية أو نشر عن التصميم أو النموذج الصناعى فى أحد المؤتمرات أو إحدى الدوريات العلمية ، وذلك كله خلال فترة لا تجاوز ستة أشهر سابقة على تاريخ إيداع طلب التسجيل فى جمهورية مصر العربية .
2 - اشتمل على اختلافات غير جوهرية بالنسبة لتصميم أو نموذج صناعى سابق أو خصص لنوع آخر من المنتجات غير ما خصص له التصميم أو النموذج السابق تسجيله .$m239$,'f7d674f9c495a93635608ee797743d42'),
(121,0,$m239$المادة 121$m239$,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل الحق فى التقدم بطلب تسجيل تصميم أو نموذج صناعى لمصلحة التسجيل التجارى ، وما يترتب على ذلك من حقوق طبقا لأحكام هذا القانون .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بالحقوق المنصوص عليها فى هذا الباب ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'75d6ef19940f8481aff4588df6123493'),
(122,0,$m239$المادة 122$m239$,$m239$تختص مصلحة التسجيل التجارى بتسجيل التصميمات والنماذج الصناعية فى السجل المعد لذلك .
ويجوز أن يشتمل الطلب على عدد من التصميمات والنماذج لا يجاوز الخمسين بشرط أن تكون فى مجموعها وحدة متجانسة .
وتحدد اللائحة التنفيذية لهذا القانون إجراءات طلب التسجيل وعدد التصميمات والنماذج التى يمكن أن يشتمل عليها الطلب الواحد وإجراءات الفحص والإشهار عن قرار المصلحة بقبول الطلب وإجراءات المعارضة فيه وغيرها من الإجراءات اللازمة ، وكذلك الرسوم المقررة على هذه الطلبات وتجديدها وعلى كافة الإجراءات المتعلقة بها على ألا تجاوز هذه الرسوم فى مجموعها ثلاثة آلاف جنيه .$m239$,'6505861c16b4e834c00b3182c27cd7eb'),
(123,0,$m239$المادة 123$m239$,$m239$لا يجوز للقائمين بالعمل فى مصلحة التسجيل التجارى أن يقدموا بالذات أو بالواسطة طلبات تسجيل لتصميمات أو نماذج صناعية إلا بعد مضى ثلاث سنوات على الأقل من تاريخ تركهم الخدمة .$m239$,'d87b3c6970e22bfbe6c0b7bd84c2026e'),
(124,0,$m239$المادة 124$m239$,$m239$لا يجوز تسجيل أى تصميم أو نموذج صناعى من التصميمات والنماذج الصناعية الآتية :
1 - التصميم أو النموذج الذى تستلزمه عادة الاعتبارات الفنية أو الوظيفية للمنتج .
2 - التصميم أو النموذج الذى يتضمن شعارات أو رموزا دينية أو أختاما أو أعلاما خاصة بجمهورية مصر العربية أو بالدول الأجنبية أو الذى ينشأ عن استخدامه إخلال بالنظام العام أو الآداب العامة .
3 - التصميم أو النموذج الذى يتطابق أو يتماثل أو يتشابه مع علامة تجارية مسجلة أو علامة مشهورة .
وعلى المصلحة فى جميع أحوال رفض طلب التسجيل إخطار الطالب بقرار الرفض مسببا ، وذلك خلال ثلاثين يوما من تاريخ صدوره بموجب كتاب موصى عليه مصحوبا بعلم الوصول .
ويجوز التظلم من هذا القرار فى ميعاد لا يجاوز ثلاثين يوما من تاريخ الإخطار به .
وتنظر التظلم لجنة تشكل بقرار من الوزير المختص من ثلاثة أحدهم من أعضاء مجلس الدولة ، وللجنة أن تستعين بمن تراه من ذوى الخبرة .
وتنظم اللائحة التنفيذية لهذا القانون إجراءات عمل هذه اللجنة وتحدد الرسم المقرر للتظلم بما لا يجاوز خمسمائة جنيه .
وتصدر اللجنة قرارها مسببا خلال تسعين يوما من تاريخ تقديم التظلم .
ويكون الطعن على قرار اللجنة أمام محكمة القضاء الإدارى خلال ثلاثين يوما من تاريخ الإعلان به .$m239$,'dccda1d2fcc1abbfe708de23b69b2301'),
(125,0,$m239$المادة 125$m239$,$m239$للمصلحة أن تكلف طالب التسجيل بإجراء التعديلات أو الاستيفاءات التى تراها إعمالا لأحكام المادة ( 124 ) على النحو الذى تبينه اللائحة التنفيذية لهذا القانون ، فإذا لم يقم الطالب بهذا الإجراء عد متنازلا عن طلبه .
وللطالب أن يتظلم من قرار المصلحة بشأن هذا التكليف أمام اللجنة المنصوص عليها فى المادة ( 124 ) وذلك خلال ثلاثين يوما من تاريخ إخطاره بالقرار ووفقا للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
ويجوز للطالب من تلقاء نفسه أن يتقدم للمصلحة بطلب بإجراء التعديلات أو الاستيفاءات المشار إليها وذلك بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'d283fe4ba8f0c5452de4fd1d57405121'),
(126,0,$m239$المادة 126$m239$,$m239$مدة الحماية المترتبة على تسجيل التصميم أو النموذج الصناعى عشر سنوات تبدأ من تاريخ تقديم طلب التسجيل فى جمهورية مصر العربية .
وتجدد الحماية لمدة خمس سنوات أخرى إذا قدم مالك التصميم أو النموذج طلبا بالتجديد فى خلال السنة الأخيرة من المدة ، وذلك وفقا للأوضاع المنصوص عليها فى اللائحة التنفيذية لهذا القانون .
ومع ذلك يحق للمالك أن يقدم طلبا بالتجديد خلال الثلاثة الأشهر التالية لتاريخ انتهاء مدة الحماية وإلا قامت المصلحة بشطب التسجيل من تلقاء نفسها .$m239$,'83982670e93162523f49f625da4c025c'),
(127,0,$m239$المادة 127$m239$,$m239$يترتب على تسجيل التصميم أو النموذج الصناعى حق صاحبه فى منع الغير من صنع أو بيع أو استيراد المنتجات المتخذة شكل هذا التصميم أو النموذج أو تتضمنه .
ويستنفد الحق فى منع الغير من استيراد أو بيع أو توزيع المنتجات المشار إليها إذا قام صاحبه بتسويق تلك المنتجات فى أية دولة أو رخص للغير بذلك .
ولا يعتبر اعتداء على هذا الحق ما يقوم به الغير من استخدام للتصميم أو النموذج الصناعى المحمى من الأعمال الآتية :
1 - الأعمال المتصلة بأغراض البحث العلمى .
2 - أغراض التعليم أو التدريب .
3 - الأنشطة غير التجارية .
4 - تصنيع أو بيع أجزاء من المنتجات المشار إليها ، وذلك بقصد إصلاحها مقابل أداء تعويض عادل .
5 - الاستخدامات الأخرى التى لا تتعارض بشكل غير معقول مع الاستغلال العادى للتصميم أو النموذج الصناعى المحمى ولا تضر بصورة غير معقولة بالمصالح المشروعة لصاحبه مع مراعاة المصالح المشروعة للغير .$m239$,'2f2265314ebecb1dbeb742472fa514a6'),
(128,0,$m239$المادة 128$m239$,$m239$يجوز نقل ملكية التصميم أو النموذج الصناعى كله أو بعضه بعوض أو بغير عوض ، كما يجوز رهنه أو تقرير حق الانتفاع عليه .
ومع عدم الإخلال بالأحكام الخاصة ببيع المحال التجارية ورهنها لا تنتقل ملكية التصميم أو النموذج الصناعى ولا يكون رهنه أو تقرير حق الانتفاع عليه حجة على الغير إلا من تاريخ التأشير بذلك فى سجل التصميمات والنماذج الصناعية .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات اللازمة لتنفيذ ذلك .$m239$,'f3e44d3a84086007c7a4b7693fcfa519'),
(129,0,$m239$المادة 129$m239$,$m239$يجوز لمصلحة التسجيل التجارى لدواعى المصلحة العامة وبعد موافقة لجنة وزارية تشكل بقرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص أن تصدر قرارا مسببا بمنح الغير ترخيصا إجباريا غير استئثارى باستخدام التصميم أو النموذج الصناعى المحمى وذلك مقابل تعويض عادل . وتحدد اللائحة التنفيذية لهذا القانون شروط وأوضاع وإجراءات منح هذا الترخيص .$m239$,'61a69305c1ff88759cc89fc6a5948961'),
(130,0,$m239$المادة 130$m239$,$m239$تنشر المصلحة قرارات التسجيل والتجديد والشطب فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية مشفوعة بصورة من التصميم أو النموذج الصناعى بحسب الأحوال ، وذلك وفقا للأوضاع المنصوص عليها فى اللائحة التنفيذية لهذا القانون .
وتسرى أحكام المواد 80 ، 81 ، 82 ، 83 على هذا الباب .$m239$,'ee93699de0cac53232123df799b9f88b'),
(131,0,$m239$المادة 131$m239$,$m239$لكل شخص أن يطلب الاطلاع على التصميم أو النموذج الصناعى المسجل أو الحصول على مستخرجات أو صور من السجل الخاص بتسجيله وذلك وفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون ومقابل رسم تحدده هذه اللائحة بما لا يجاوز مائة جنيه .$m239$,'6a40e3d57d64da74673679d799cf7f98'),
(132,0,$m239$المادة 132$m239$,$m239$تتمتع بحماية مؤقتة التصميمات أو النماذج الصناعية التى تتوافر فيها شروط التسجيل والتى تعرض فى المعارض الوطنية أو الدولية التى يصدر بتحديدها قرار من الوزير المختص .
وتحدد اللائحة التنفيذية لهذا القانون شروط وأوضاع وإجراءات منح تلك الحماية .$m239$,'faf52cd8b427f1fdf11b52108dccb525'),
(133,0,$m239$المادة 133$m239$,$m239$للمصلحة ولكل ذى شأن أن يرفع الدعوى إلى محكمة القضاء الإدارى بطلب شطب تسجيل التصميم أو النموذج الصناعى الذى تم بدون وجه حق ، وتقوم المصلحة بشطب التسجيل متى قدم لها حكم واجب النفاذ بذلك .$m239$,'c29581a2df98bb58715e31046620b6de'),
(134,0,$m239$المادة 134$m239$,$m239$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر يعاقب بغرامة لا تقل عن أربعة آلاف جنيه ولا تجاوز عشرة آلاف جنيه :
1 - كل من قلد تصميما أو نموذجا صناعيا محميا تم تسجيله وفقا لأحكام هذا القانون .
2 - كل من صنع أو باع أو عرض للبيع أو حاز بقصد الاتجار أو التداول منتجات تتخذ تصميما أو نموذجا صناعيا مقلدا مع علمه بذلك .
3 - كل من وضع بغير حق على منتجات أو إعلانات أو علامات تجارية أو أدوات معينة أو غيرها بيانات تؤدى إلى الاعتقاد بتسجيله تصميما أو نموذجا صناعيا .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن شهر والغرامة التى لا تقل عن ثمانية آلاف جنيه ولا تجاوز عشرين ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة التصميم أو النموذج الصناعى المضبوط والمنتجات محل الجريمة والأدوات التى استخدمت فى ارتكابها وبنشر الحكم الصادر بالإدانة فى جريدة واحدة أو أكثر على نفقة المحكوم عليه .$m239$,'18662fea65aabcbebe72a337f290ee77'),
(135,0,$m239$المادة 135$m239$,$m239$لرئيس المحكمة المختصة بأصل النزاع وبناء على طلب كل ذى شأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة ، وعلى وجه الخصوص :
1 - إثبات واقعة الاعتداء على الحق محل الحماية .
2 - إجراء حصر ووصف تفصيلى للمنتجات المخالفة والأدوات التى استخدمت أو تستخدم فى ارتكاب الجريمة .
3 - توقيع الحجز على الأشياء المذكورة فى البند ( 2 )
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة المختصة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'3c4f44814d0844fb36b071f94a648246'),
(136,0,$m239$المادة 136$m239$,$m239$يجوز لمن صدر ضده الأمر أن يتظلم منه إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدوره أو إعلانه له على حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا .$m239$,'ba1b9de69f9fc36e8d35d248b5ab2702'),
(137,0,$m239$المادة 137$m239$,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الباب .$m239$,'7b313a3096de9ba76b500f5910c2c6b0'),
(138,0,$m239$المادة 138$m239$,$m239$فى تطبيق أحكام هذا القانون ، يكون للمصطلحات التالية المعنى الوارد قرين كل منها :
1 - المصنف : كل عمل مبتكر أدبى أو فنى أو علمى أيا كان نوعه أو طريقة التعبير عنه أو أهميته أو الغرض من تصنيفه .
2 - الابتكار : الطابع الإبداعى الذى يسبغ الأصالة على المصنف .
3 - المؤلف : الشخص الذى يبتكر المصنف ، ويعد مؤلفا للمصنف من يذكر اسمه عليه أو ينسب إليه عند نشره باعتباره مؤلفا له ما لم يقم الدليل على غير ذلك .
ويعتبر مؤلفا للمصنف من ينشره بغير اسمه أو باسم مستعار بشرط ألا يقوم شك فى معرفة حقيقة شخصه ، فإذا قام الشك اعتبر ناشر أو منتج المصنف سواء أكان شخصا طبيعيا أم اعتباريا ممثلا للمؤلف فى مباشرة حقوقه إلى أن يتم التعرف على حقيقة شخص المؤلف .
4 - المصنف الجماعى : المصنف الذى يضعه أكثر من مؤلف بتوجيه شخص طبيعى أو اعتبارى يتكفل بنشره باسمه وتحت إدارته ، ويندمج عمل المؤلفين فيه فى الهدف العام الذى قصد إليه هذا الشخص بحيث يستحيل فصل عمل كل مؤلف وتمييزه على حدة .
5 - المصنف المشترك : المصنف الذى لا يندرج ضمن المصنفات الجماعية ، ويشترك فى وضعه أكثر من شخص سواء أمكن فصل نصيب كل منهم فيه أو لم يمكن .
6 - المصنف المشتق : المصنف الذى يستمد أصله من مصنف سابق الوجود كالترجمات والتوزيعات الموسيقية وتجميعات المصنفات بما فى ذلك قواعد البيانات المقروءة سواء من الحاسب أو من غيره ، ومجموعات التعبير الفلكلورى ما دامت مبتكرة من حيث ترتيب أو اختيار محتوياتها .
7 - الفلكلور الوطنى : كل تعبير يتمثل فى عناصر متميزة تعكس التراث الشعبى التقليدى الذى نشأ أو استمر فى جمهورية مصر العربية ، وبوجه خاص التعبيرات الآتية :
( أ ) التعبيرات الشفوية مثل : الحكايات والأحاجى والألغاز والأشعار الشعبية وغيرها من المأثورات .
( ب ) التعبيرات الموسيقية مثل : الأغانى الشعبية المصحوبة بموسيقى .
( جـ ) التعبيرات الحركية مثل : الرقصات الشعبية والمسرحيات والأشكال الفنية والطقوس .
( د ) التعبيرات الملموسة مثل : منتجات الفن الشعبى التشكيلى وبوجه خاص الرسومات بالخطوط والألوان ، والحفر ، والنحت ، والخزف ، والطين والمنتجات المصنوعة من الخشب أو ما يرد عليه من تطعيمات تشكيلية مختلفة أو الموزاييك أو المعدن أو الجواهر ، والحقائب المنسوجة يدويا وأشغال الإبرة والمنسوجات والسجاد والملبوسات .
الآلات الموسيقية .
الأشكال المعمارية .
8 - الملك العام : الملك الذى تؤول إليه جميع المصنفات المستبعدة من الحماية بداية أو التى تنقضى مدة حماية الحقوق المالية عليها طبقا لأحكام هذا الكتاب .
9 - النسخ : استحداث صورة أو أكثر مطابقة للأصل من مصنف أو تسجيل صوتى بأية طريقة أو فى أى شكل بما فى ذلك التخزين الالكترونى الدائم أو الوقتى للمصنف أو للتسجيل الصوتى .
10 - النشر : أى عمل من شأنه إتاحة المصنف أو التسجيل الصوتى أو البرنامج الإذاعى أو فنانى الأداء للجمهور أو بأى طريقة من الطرق .
وتكون إتاحة المصنف للجمهور بموافقة المؤلف أو مالك حقوقه ، أما التسجيلات الصوتية أو البرامج الإذاعية أو الأداءات فتكون إتاحتها للجمهور بموافقة منتجها أو خلفه .
11 - منتج المصنف السمعى أو السمعى البصرى : الشخص الطبيعى أو الاعتبارى الذى يبادر إلى إنجاز المصنف السمعى أو المصنف السمعى البصرى ويضطلع بمسئولية هذا الإنجاز .
12 - فنانو الأداء : الأشخاص الذين يمثلون أو يغنون أو يلقون أو ينشدون أو يعزفون أو يرقصون فى مصنفات أدبية أو فنية محمية طبقا لأحكام هذا القانون أو آلت إلى الملك العام ، أو يؤدون فيها بصورة أو بأخرى ، بما فى ذلك التعبيرات الفلكلورية .
13 - منتج التسجيلات الصوتية : الشخص الطبيعى أو الاعتبارى الذى يسجل لأول مرة مصنفا تسجيلا صوتيا أو أداء لأحد فنانى الأداء ، وذلك دون تثبيت الأصوات على الصورة فى إطار إعداد مصنف سمعى بصرى .
14 - الإذاعة : البث السمعى أو السمعى البصرى للمصنف أو للأداء أو للتسجيل الصوتى أو لتسجيل المصنف أو الأداء وذلك إلى الجمهور بطريقة لاسلكية ، ويعد كذلك البث عبر التوابع الصناعية .
15 - الأداء العلنى : أى عمل من شأنه إتاحة المصنف بأى صورة من الصور للجمهور مثل التمثيل أو الإلقاء أو العزف أو البث بحيث يتصل الجمهور بالمصنف عن طريق الأداء أو التسجيل الصوتى أو المرئى أو المسموع اتصالا مباشرا .
16 - التوصيل العلنى : البث السلكى أو اللاسلكى لصور أو أصوات أو لصور وأصوات لمصنف ، أو أداء أو تسجيل صوتى ، أو بث إذاعى بحيث يمكن التلقى عن طريق البث وحده لغير أفراد العائلة والأصدقاء المقربين ، فى أى مكان مختلف عن المكان الذى يبدأ منه البث . وبغض النظر عن الزمان أو المكان الذى يتم فيه التلقى ، بما فى ذلك أى زمان أو مكان يختاره المتلقى منفردا عبر جهاز الحاسب أو أى وسيلة أخرى .
17 - هيئة الإذاعة : كل شخص أو جهة منوط بها أو مسئولة عن البث الإذاعى اللاسلكى السمعى أو السمعى البصرى .
18 - الوزير المختص : وزير الثقافة ، ويكون وزير الإعلام هو المختص بالنسبة لهيئات الإذاعة ، ويكون وزير الاتصالات والمعلومات هو المختص بالنسبة إلى برامج الحاسب وقواعد البيانات .
19 - الوزارة المختصة : وزارة الثقافة ، وتكون وزارة الإعلام هى المختصة بالنسبة لهيئات الإذاعة ، وتكون وزارة الاتصالات والمعلومات هى المختصة بالنسبة إلى برامج الحاسب وقواعد البيانات .$m239$,'a1082ab09f8f26ebbdf4a8ab5a0dba7d'),
(139,0,$m239$المادة 139$m239$,$m239$تشمل الحماية المقررة لحقوق المؤلف والحقوق المجاورة لها المصريين والأجانب من الأشخاص الطبيعيين والاعتباريين الذين ينتمون إلى إحدى الدول الأعضاء فى منظمة التجارة العالمية ومن فى حكمهم .
ويعتبر فى حكم رعايا الدول الأعضاء :
( أ ) بالنسبة لحق المؤلف :
1 - المؤلفون الذين تنشر مصنفاتهم لأول مرة إحدى الدول الأعضاء فى المنظمة ، أو تنشر فى إحدى الدول غير الأعضاء وإحدى الدول الأعضاء فى آن واحد . ويعتبر المصنف منشورا فى آن واحد فى عدة دول إذا ظهر فى دولتين أو أكثر خلال ثلاثين يوما من تاريخ نشره لأول مرة .
ولا يعد نشرا تمثيل مصنف مسرحى أو مصنف مسرحى موسيقى أو سينمائى وأداء مصنف موسيقى والقراءة العلنية لمصنف أدبى والنقل السلكى أو إذاعة المصنفات الأدبية والفنية وعرض مصنف فنى وتنفيذ مصنف معمارى .
2 - منتجو ومؤلفو المصنفات السينمائية التى يكون مقر منتجها أو محل إقامته فى إحدى الدول الأعضاء فى تلك المنظمة .
3 - مؤلفو المصنفات المعمارية المقامة فى إحدى الدول الأعضاء أو المصنفات الفنية الأخرى الداخلة فى مبنى أو منشأة أخرى كائنة فى إحدى الدول الأعضاء .
( ب ) بالنسبة للحقوق المجاورة لحق المؤلف :
1 - فنانو الأداء إذا توافر أى شرط من الشروط التالية :
( أ ) إذا تم الأداء فى دولة عضو فى منظمة التجارة العالمية .
( ب ) إذا تم تفريغ الأداء فى تسجيلات صوتية ينتمى منتجها لدولة عضو فى منظمة التجارة العالمية ، أو تم التثبيت الأول للصوت فى إقليم دولة عضو فى المنظمة .
( جـ ) إذا تم بث الأداء عن طريق هيئة إذاعة يقع مقرها فى دولة عضو فى منظمة التجارة العالمية ، وأن يكون البرنامج الإذاعى قد تم بثه من جهاز إرسال يقع أيضا فى دولة عضو .
2 - منتجو التسجيلات الصوتية إذا كان التثبيت الأول للصوت قد تم فى دولة عضو فى المنظمة .
3 - هيئات الإذاعة إذا كان مقر هيئة الإذاعة كائنا فى إقليم دولة عضو فى منظمة التجارة العالمية ، وأن يكون البرنامج الإذاعى قد تم بثه من جهاز إرسال يقع أيضا فى إقليم دولة عضو فى المنظمة .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بحقوق الملكية الفكرية طبقا لهذا القانون ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'25f7f3c031ec24ec01930361b072d0b2'),
(140,0,$m239$المادة 140$m239$,$m239$تتمتع بحماية هذا القانون حقوق المؤلفين على مصنفاتهم الأدبية والفنية ، وبوجه خاص المصنفات الآتية :
1 - الكتب ، والكتيبات ، والمقالات والنشرات وغيرها من المصنفات المكتوبة .
2 - برامج الحاسب الآلى .
3 - قواعد البيانات سواء كانت مقروءة من الحاسب الآلى أو من غيره .
4 - المحاضرات ، والخطب ، والمواعظ ، وأية مصنفات شفوية أخرى إذا كانت مسجلة .
5 - المصنفات التمثيلية والتمثيليات الموسيقية والتمثيل الصامت ( البانتوميم ) .
6 - المصنفات الموسيقية المقترنة بالألفاظ أو غير المقترنة بها .
7 - المصنفات السمعية البصرية .
8 - مصنفات العمارة .
9 - مصنفات الرسم بالخطوط أو بالألوان ، والنحت ، والطباعة على الحجر ، وعلى الأقمشة وأية مصنفات مماثلة فى مجال الفنون الجميلة .
10 - المصنفات الفوتوغرافية وما يماثلها .
11 - مصنفات الفن التطبيقى والتشكيلى .
12 - الصور التوضيحية ، والخرائط الجغرافية والرسومات التخطيطية ( الاسكتشات ) والمصنفات الثلاثية الأبعاد المتعلقة بالجغرافيا أو الطبوغرافيا أو التصميمات المعمارية .
13 - المصنفات المشتقة ، وذلك دون الإخلال بالحماية المقررة للمصنفات التى اشتقت منها .
وتشمل الحماية عنوان المصنف إذا كان مبتكرا .$m239$,'8cc2ca29f9e1865d7eef9cae28a49f77'),
(141,0,$m239$المادة 141$m239$,$m239$لا تشمل الحماية مجرد الأفكار والإجراءات وأساليب العمل وطرق التشغيل والمفاهيم والمبادىء والاكتشافات والبيانات ، ولو كان معبرا عنها أو موصوفة أو موضحة أو مدرجة فى مصنف .
كذلك لا تشمل ما يلى :
أولا - الوثائق الرسمية ، أيا كانت لغتها الأصلية أو اللغة المنقولة إليها ، مثل نصوص القوانين ، واللوائح ، والقرارات ، والاتفاقيات الدولية ، والأحكام القضائية ، وأحكام المحكمين ، والقرارات الصادرة من اللجان الإدارية ذات الاختصاص القضائى .
ثانيا - أخبار الحوادث والوقائع الجارية التى تكون مجرد أخبار صحفية .
ومع ذلك تتمتع مجموعات ما تقدم بالحماية إذا تميز جمعها بالابتكار فى الترتيب والعرض أو بأى مجهود شخصى جدير بالحماية .$m239$,'acd03b3e50857df0dc2f980bb7c630b5'),
(142,0,$m239$المادة 142$m239$,$m239$يعتبر الفلكلور الوطنى ملكا عاما للشعب ، وتباشر الوزارة المختصة عليه حقوق المؤلف الأدبية والمالية وتعمل على حمايته ودعمه .$m239$,'f294e187834f363365250f4e04c4c323'),
(143,0,$m239$المادة 143$m239$,$m239$يتمتع المؤلف وخلفه العام - على المصنف - بحقوق أدبية أبدية غير قابلة للتقادم أو للتنازل عنها ، وتشمل هذه الحقوق ما يلى :
أولا - الحق فى إتاحة المصنف للجمهور لأول مرة .
ثانيا - الحق فى نسبة المصنف إلى مؤلفه .
ثالثا - الحق فى منع تعديل المصنف تعديلا يعتبره المؤلف تشويها أو تحريفا له ، ولا يعد التعديل فى مجال الترجمة اعتداء إلا إذا أغفل المترجم الإشارة إلى مواطن الحذف أو التغيير أو أساء بعمله لسمعة المؤلف ومكانته .$m239$,'e019530588f641d9500f280df6faabc4'),
(144,0,$m239$المادة 144$m239$,$m239$للمؤلف وحده - إذا طرأت أسباب جدية - أن يطلب من المحكمة الابتدائية الحكم بمنع طرح مصنفه للتداول أو بسحبه من التداول أو بإدخال تعديلات جوهرية عليه برغم تصرفه فى حقوق الاستغلال المالى ، ويلزم المؤلف فى هذه الحالة أن يعوض مقدما من آلت إليه حقوق الاستغلال المالى تعويضا عادلا يدفع فى غضون أجل تحدده المحكمة وإلا زال كل أثر للحكم .$m239$,'8609384c57cf7f7893b89cf09afb52ee'),
(145,0,$m239$المادة 145$m239$,$m239$يقع باطلا بطلانا مطلقا كل تصرف يرد على أى من الحقوق الأدبية المنصوص عليها فى المادتين ( 143 ) ، ( 144 ) من هذا القانون .$m239$,'6b38d35165c0b3ae7d63d73676ffc224'),
(146,0,$m239$المادة 146$m239$,$m239$تباشر الوزارة المختصة ، الحقوق الأدبية المنصوص عليها فى المادتين ( 143 ) و ( 144 ) من هذا الكتاب ، فى حالة عدم وجود وارث أو موصى له ، وذلك بعد انقضاء مدة حماية الحقوق المالية المقررة فيه .$m239$,'f45ea30b7376f5d6866cc43aacda2e1a'),
(147,0,$m239$المادة 147$m239$,$m239$يتمتع المؤلف وخلفه العام من بعده ، بحق استئثارى فى الترخيص أو المنع لأى استغلال لمصنفه بأى وجه من الوجوه وبخاصة عن طريق النسخ أو البث الإذاعى أو إعادة البث الإذاعى أو الأداء العلنى أو التوصيل العلنى ، أو الترجمة أو التحوير أو التأجير أو الإعارة أو الإتاحة للجمهور ، بما فى ذلك إتاحته عبر أجهزة الحاسب الآلى أو من خلال شبكات الإنترنت أو شبكات المعلومات أو شبكات الاتصالات وغيرها من الوسائل .
ولا ينطبق الحق الاستئثارى فى التأجير على برامج الحاسب الآلى إذا لم تكن هى المحل الأساسى للتأجير ، ولا على تأجير المصنفات السمعية البصرية متى كان لا يؤدى إلى انتشار نسخها على نحو يلحق ضررا ماديا بصاحب الحق الاستئثارى المشار إليه .
كما يتمتع المؤلف وخلفه من بعده بالحق فى تتبع أعمال التصرف فى النسخة الأصلية لمصنفه ، والذى يخوله الحصول على نسبة مئوية معينة لا تجاوز عشرة فى المائة من الزيادة التى تحققت من كل عملية تصرف فى هذه النسخة .
ويستنفد حق المؤلف فى منع الغير من استيراد أو استخدام أو بيع أو توزيع مصنفه المحمى وفقا لأحكام هذا القانون إذا قام باستغلاله وتسويقه فى أية دولة أو رخص للغير بذلك .$m239$,'3e6a63682f61440fa1dde3168ce18cc7'),
(148,0,$m239$المادة 148$m239$,$m239$تنتهى حماية حق المؤلف وحق من ترجم مصنفه إلى لغة أجنبية أخرى فى ترجمة ذلك المصنف إلى اللغة العربية إذا لم يباشر المؤلف أو المترجم هذا الحق بنفسه أو بواسطة غيره فى مدى ثلاث سنوات من تاريخ أول نشر للمصنف الأصلى أو المترجم .$m239$,'db31dbbeac9545ae7caa96f6f562a7df'),
(149,0,$m239$المادة 149$m239$,$m239$للمؤلف أن ينقل إلى الغير كل أو بعض حقوقه المالية المبينة فى هذا القانون .
ويشترط لانعقاد التصرف أن يكون مكتوبا وأن يحدد فيه صراحة وبالتفصيل كل حق على حدة يكون محلا للتصرف مع بيان مداه والغرض منه ومدة الاستغلال ومكانه .
ويكون المؤلف مالكا لكل ما لم يتنازل عنه صراحة من حقوق مالية ، ولا يعد ترخيصه باستغلال أحد هذه الحقوق ترخيصا منه باستغلال أى حق مالى آخر يتمتع به على المصنف نفسه .
ومع عدم الإخلال بحقوق المؤلف الأدبية المنصوص عليها فى هذا القانون ، يمتنع عليه القيام بأى عمل من شأنه تعطيل استغلال الحق محل التصرف .$m239$,'5feeb0717e51233e27d89b7405355573'),
(150,0,$m239$المادة 150$m239$,$m239$للمؤلف أن يتقاضى المقابل النقدى أو العينى الذى يراه عادلا نظير نقل حق أو أكثر من حقوق الاستغلال المالى لمصنفه إلى الغير ، على أساس مشاركة نسبية فى الإيراد الناتج من الاستغلال ، كما يجوز له التعاقد على أساس مبلغ جزافى أو بالجمع بين الأساسين .$m239$,'21c32af80560ef53c394c2e1dd0210c2'),
(151,0,$m239$المادة 151$m239$,$m239$إذا تبين أن الاتفاق المشار إليه فى المادة ( 150 ) من هذا القانون مجحف بحقوق المؤلف أو أصبح كذلك ، لظروف طرأت بعد التعاقد ، يكون للمؤلف أو خلفه أن يلجأ إلى المحكمة الابتدائية بطلب إعادة النظر فى قيمة المقابل المتفق عليه مع مراعاة حقوق المتعاقد معه وعدم الإضرار به .$m239$,'5cfe24ae6e7a8dd910f830fc945847ac'),
(152,0,$m239$المادة 152$m239$,$m239$لا يترتب على تصرف المؤلف فى النسخة الأصلية من مصنفه ، أيا كان نوع هذا التصرف ، نقل حقوقه المالية .
ومع ذلك لا يجوز إلزام المتصرف إليه بأن يمكن المؤلف من نسخ أو نقل أو عرض النسخة الأصلية ، وذلك كله ما لم يتفق على غير ذلك .$m239$,'d2db9faf0e8449f531fd0d566c5679be'),
(153,0,$m239$المادة 153$m239$,$m239$يقع باطلا بطلانا مطلقا كل تصرف للمؤلف فى مجموع إنتاجه الفكرى المستقبلى .$m239$,'20a0e594f19a7ca0244fb9c32541efb4'),
(154,0,$m239$المادة 154$m239$,$m239$يجوز الحجز على الحقوق المالية للمؤلفين على المنشور أو المتاح للتداول من مصنفاتهم . ولا يجوز الحجز على المصنفات التى يتوفى صاحبها قبل نشرها ما لم يثبت أن إرادته كانت قد انصرفت إلى نشرها قبل وفاته .$m239$,'d15e498565dc3094ceabbe49ab4a1bcd'),
(155,0,$m239$المادة 155$m239$,$m239$يتمتع فنانو الأداء وخلفهم العام بحق أدبى أبدى لا يقبل التنازل عنه أو التقادم يخولهم ما يلى :
1 - الحق فى نسبة الأداء الحى أو المسجل إلى فنانى الأداء ، على النحو الذى أبدعوه عليه .
2 - الحق فى منع أى تغيير أو تحريف أو تشويه فى أدائهم .
وتباشر الوزارة المختصة هذا الحق الأدبى فى حالة عدم وجود وارث أو موصى له وذلك بعد انقضاء مدة حماية الحقوق المالية المنصوص عليها فى هذا القانون .$m239$,'b489b070ee53d1434bdd03cb58403bf7'),
(156,0,$m239$المادة 156$m239$,$m239$يتمتع فنانو الأداء بالحقوق المالية الاستئثارية الآتية :
1 - توصيل أدائهم إلى الجمهور والترخيص بالإتاحة العلنية أو التأجير أو الإعارة للتسجيل الأصلى للأداء أو لنسخ منه .
2 - منع أى استغلال لأدائهم ، بأية طريقة من الطرق ، بغير ترخيص كتابى مسبق منهم ، ويعد استغلالا محظورا بوجه خاص تسجيل هذا الأداء الحى على دعامة أو تأجيرها بهدف الحصول على عائد تجارى مباشر أو غير مباشر أو البث الإذاعى لها إلى الجمهور .
3 - تأجير أو إعارة الأداء الأصلى أو نسخ منه لتحقيق غرض تجارى مباشر أو غير مباشر ، بغض النظر عن ملكية الأصل أو النسخ المؤجرة .
4 - الإتاحة العلنية لأداء مسجل عبر الإذاعة أو أجهزة الحاسب الآلى أو غيرها من الوسائل ، وذلك بما يحقق تلقيه على وجه الانفراد فى أى زمان أو مكان .
ولا يسرى حكم هذه المادة على تسجيل فنانى الأداء لأدائهم ضمن تسجيل سمعى بصرى ما لم يتفق على غير ذلك .$m239$,'e87c9110e15f6c293d52c044e7555544'),
(157,0,$m239$المادة 157$m239$,$m239$يتمتع منتجو التسجيلات الصوتية بالحقوق المالية الاستئثارية الآتية :
1 - منع أى استغلال لتسجيلاتهم بأية طريقة من الطرق بغير ترخيص كتابى مسبق منهم ، ويعد بوجه خاص استغلالا محظورا فى هذا المعنى نسخها أو تأجيرها أو البث الإذاعى لها أو إتاحتها عبر أجهزة الحاسب الآلى أو غيرها من الوسائل .
2 - الإتاحة العلنية لتسجيل صوتى بوسائل سلكية أو لاسلكية أو عبر أجهزة الحاسب الآلى أو غيرها من الوسائل .$m239$,'bcfe973ff2b0ca6b95de98238f5f7738'),
(158,0,$m239$المادة 158$m239$,$m239$تتمتع هيئات الإذاعة بالحقوق المالية الاستئثارية الآتية :
1 - منح الترخيص باستغلال تسجيلاتها .
2 - منع أى توصيل لتسجيلها التليفزيونى لبرامجها إلى الجمهور بغير ترخيص كتابى مسبق منها ، ويعد بوجه خاص استغلالا محظورا تسجيل هذه البرامج أو عمل نسخ منها أو بيعها أو تأجيرها أو إعادة بثها أو توزيعها أو نقلها إلى الجمهور بأية وسيلة كانت بما فى ذلك الإزالة أو الإتلاف لأية حماية تقنية لهذه البرامج كالتشفير أو غيره .$m239$,'fc8b55e08acf84f08fde82b78de14d3d'),
(159,0,$m239$المادة 159$m239$,$m239$تنطبق الأحكام الخاصة بتنازل المؤلف عن حقوقه المالية وفقا لهذا القانون على أصحاب الحقوق المجاورة .
ومع عدم الإخلال بما نص عليه فى هذا القانون من حقوق استئثارية لفنانى الأداء وهيئات الإذاعة لا يكون لهؤلاء إلا حق الحصول على مقابل مالى عادل لمرة واحدة نظير الاستخدام المباشر أو غير المباشر للبرامج المنشورة فى الأغراض التجارية للإذاعة أو التوصيل إلى الجمهور ما لم يتفق على غير ذلك .$m239$,'1b055b568eb41a1ffd9bbeacea5ba0dd'),
(160,0,$m239$المادة 160$m239$,$m239$تحمى الحقوق المالية للمؤلف المنصوص عليها فى هذا القانون مدة حياته ولمدة خمسين سنة تبدأ من تاريخ وفاة المؤلف .$m239$,'0f944608b7eff6a84dc8924aae54d1ed'),
(161,0,$m239$المادة 161$m239$,$m239$تحمى الحقوق المالية لمؤلفى المصنفات المشتركة مدة حياتهم جميعا ولمدة خمسين سنة تبدأ من وفاة آخر من بقى حيا منهم .$m239$,'14de60a948f9bdaa10d2dba837e921ae'),
(162,0,$m239$المادة 162$m239$,$m239$تحمى الحقوق المالية لمؤلفى المصنفات الجماعية - باستثناء مؤلفى مصنفات الفن التطبيقى - مدة خمسين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد . وذلك إذا كان مالك حقوق المؤلف شخصا اعتباريا ، أما إذا كان مالك هذه الحقوق شخصا طبيعيا فتكون مدة الحماية طبقا للقاعدة المنصوص عليها فى المادتين ( 160 ) ، ( 161 ) من هذا القانون .
وتنقضى الحقوق المالية على المصنفات التى تنشر لأول مرة بعد وفاة مؤلفها بمضى خمسين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد .$m239$,'9c9930ec8da504572a80aa29406f8223'),
(163,0,$m239$المادة 163$m239$,$m239$تحمى الحقوق المالية على المصنفات التى تنشر بدون اسم مؤلفها أو باسم مستعار لمدة خمسين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد ، فإذا كان مؤلفها شخصا معروفا ومحددا أو كشف مؤلفها عن شخصه فتكون مدة الحماية طبقا للقاعدة المنصوص عليها فى المادة ( 160 ) من هذا القانون .$m239$,'2e5cd20114e9afab2df2bc5dc723e932'),
(164,0,$m239$المادة 164$m239$,$m239$تنقضى الحقوق المالية لمؤلفى مصنفات الفن التطبيقى بانقضاء خمس وعشرين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد .$m239$,'71d409a18da9b8fb94d963e7c183bea0'),
(165,0,$m239$المادة 165$m239$,$m239$فى الأحوال التى تحسب فيها مدة الحماية من تاريخ النشر أو الإتاحة للجمهور لأول مرة ، يتخذ تاريخ أول نشر أو أول إتاحة للجمهور أيهما أبعد مبدأ لحساب المدة ، بغض النظر عن إعادة النشر أو إعادة الإتاحة للجمهور إلا إذا أدخل المؤلف على مصنفه عند الإعادة تعديلات جوهرية بحيث يمكن اعتباره مصنفا جديدا .
فإذا كان المصنف يتكون من عدة أجزاء أو مجلدات نشرت منفصلة وعلى فترات ، فيعتبر كل جزء أو مجلد مصنفا مستقلا عند حساب مدة الحماية .$m239$,'dfc1740a3579792aeb1b4cd15cde782d'),
(166,0,$m239$المادة 166$m239$,$m239$يتمتع فنانو الأداء بحق مالى استئثارى فى مجال أدائهم ، على النحو المبين فى المادة ( 156 ) من هذا القانون وذلك لمدة خمسين سنة تبدأ من تاريخ الأداء أو التسجيل على حسب الأحوال .$m239$,'17197d02c977e37a36e14b65d7c169b1'),
(167,0,$m239$المادة 167$m239$,$m239$يتمتع منتجو التسجيلات الصوتية بحق مالى استئثارى فى مجال استغلال تسجيلاتهم ، على النحو المبين فى المادة ( 157 ) ، وذلك لمدة خمسين سنة تبدأ من تاريخ التسجيل أو النشر أيهما أبعد ، وذلك فى الحدود المنصوص عليها فى هذا القانون .$m239$,'c4ae9a6071d761ad4870a721d4be1298'),
(168,0,$m239$المادة 168$m239$,$m239$تتمتع هيئات البث الإذاعى ، بحق مالى استئثارى يخول لها استغلال برامجها لمدة عشرين سنة تبدأ من التاريخ الذى تم فيها أول بث لهذه البرامج .$m239$,'06832d7cccc8dd4ff1bf56e930d150fb'),
(169,0,$m239$المادة 169$m239$,$m239$لهيئات البث الإذاعى ، الحق فى إذاعة المصنفات التى تؤدى فى أى مكان عام . وتلتزم هذه الهيئات بإذاعة اسم المؤلف وعنوان المصنف وبسداد مقابل عادل نقدى أو عينى للمؤلف . كما تلتزم بسداد أى تعويض آخر إذا كان لذلك مقتضى .$m239$,'9d1a7f4b065a82e3bbec999039521a74'),
(170,0,$m239$المادة 170$m239$,$m239$يجوز لأى شخص أن يطلب من الوزارة المختصة منحه ترخيصا شخصيا للنسخ أو الترجمة أو بهما معا لأى مصنف محمى طبقا لأحكام هذا القانون ، وذلك دون إذن المؤلف وللأغراض المبينة فى الفقرة التالية نظير سداد تعويض عادل للمؤلف أو خلفه ، وبشرط ألا يتعارض هذا الترخيص مع الاستغلال العادى للمصنف ، أو يلحق ضررا غير مبرر بالمصالح المشروعة للمؤلف أو لأصحاب حق المؤلف .
ويكون إصدار الترخيص بقرار مسبب يحدد فيه النطاق الزمانى والمكانى له ولأغراض الوفاء باحتياجات التعليم بكافة أنواعه ومستوياته .
وتحدد اللائحة التنفيذية لهذا القانون حالات وشروط منح الترخيص وفئات الرسم المستحق بما لا يجاوز ألف جنيه عن كل مصنف .$m239$,'0f5e5474ab8c9ab42751f1272c90e27b'),
(171,0,$m239$المادة 171$m239$,$m239$مع عدم الإخلال بحقوق المؤلف الأدبية طبقا لأحكام هذا القانون ، ليس للمؤلف بعد نشر مصنفه أن يمنع الغير من القيام بأى عمل من الأعمال الآتية :
أولا - أداء المصنف فى اجتماعات داخل إطار عائلى أو بطلاب داخل المنشأة التعليمية مادام ذلك يتم بدون تحصيل مقابل مالى مباشر أو غير مباشر .
ثانيا - عمل نسخة وحيدة من المصنف لاستعمال الناسخ الشخصى المحض وبشرط ألا يخل هذا النسخ بالاستغلال العادى للمصنف أو يلحق ضررا غير مبرر بالمصالح المشروعة للمؤلف أو لأصحاب حق المؤلف . ومع ذلك يكون للمؤلف أو خلفه بعد نشر مصنفه أن يمنع الغير من القيام بدون إذنه بأى من الأعمال الآتية :
- نسخ أو تصوير مصنفات الفنون الجميلة أو التطبيقية أو التشكيلية مالم تكن فى مكان عام أو المصنفات المعمارية .
- نسخ أو تصوير كل أو جزء جوهرى لنوتة مصنف موسيقى .
- نسخ أو تصوير كل أو جزء جوهرى لقاعدة بيانات أو برامج حاسب آلى .
ثالثا - عمل نسخة وحيدة من برنامج الحاسب الآلى بمعرفة الحائز الشرعى له بغرض الحفظ أو الإحلال عند فقد النسخة الأصلية أو تلفها أو عدم صلاحيتها للاستخدام ، أو الاقتباس من البرنامج وإن جاوز هذا الاقتباس القدر الضرورى لاستخدام هذا البرنامج ما دام فى حدود الغرض المرخص به ويجب إتلاف النسخة الأصلية أو المقتبسة بمجرد زوال سند الحائز ، وتحدد اللائحة التنفيذية لهذا القانون حالات وشروط الاقتباس من البرنامج .
رابعا - عمل دراسات تحليلية للمصنف أو مقتطفات أو مقتبسات منه بقصد النقد أو المناقشة أو الإعلام .
خامسا - النسخ من مصنفات محمية وذلك للاستعمال فى إجراءات قضائية أو إدارية فى حدود ما تقتضيه هذه الإجراءات مع ذكر المصدر واسم المؤلف .
سادسا - نسخ أجزاء قصيرة من مصنف فى صورة مكتوبة أو مسجلة تسجيلا سمعيا أو بصريا أو سمعيا بصريا ، وذلك لأغراض التدريس بهدف الإيضاح أو الشرح ، بشرط أن يكون النسخ فى الحدود المعقولة وألا يتجاوز الغرض منه ، وأن يذكر اسم المؤلف وعنوان المصنف على كل النسخ كلما كان ذلك ممكنا عملا .
سابعا - نسخ مقال أو مصنف قصير أو مستخرج من مصنف إذا كان ذلك ضروريا لأغراض التدريس فى منشآت تعليمية ، وذلك بالشرطين الآتيين :
- أن يكون النسخ لمرة وحيدة أو فى أوقات منفصلة غير متصلة .
- أن يشار إلى اسم المؤلف وعنوان المصنف على كل نسخة .
ثامنا - تصوير نسخة وحيدة من المصنف بواسطة دار للوثائق أو المحفوظات أو بواسطة المكتبات التى لا تستهدف الربح - بصورة مباشرة أو غير مباشرة - وذلك فى أى من الحالتين الآتيتين :
- أن يكون النسخ لمقالة منشورة أو مصنف قصير أو مستخرج من مصنف متى كان الغرض من النسخ تلبية طلب شخص طبيعى لاستخدامها فى دراسة أو بحث على أن يتم ذلك لمرة واحدة أو على فترات متفاوتة .
- أن يكون النسخ بهدف المحافظة على النسخة الأصلية أو لتحل النسخة محل نسخة فقدت أو تلفت أو أصبحت غير صالحة للاستخدام ويستحيل الحصول على بديل لها بشروط معقولة .
تاسعا - النسخ المؤقت للمصنف الذى يتم تبعا أو أثناء البث الرقمى له أو أثناء القيام بعمل يستهدف استقبال مصنف مخزن رقميا ، وفى إطار التشغيل العادى للأداة المستخدمة ممن له الحق فى ذلك .$m239$,'20607fa9484996cea235acda5aaf9cfb'),
(172,0,$m239$المادة 172$m239$,$m239$مع عدم الإخلال بحقوق المؤلف الأدبية طبقا لأحكام هذا القانون فليس للمؤلف أو خلفه أن يمنع الصحف أو الدوريات أو هيئات الإذاعة ، فى الحدود التى تبررها أغراضها مما يلى :
أولا - نشر مقتطفات من مصنفاته التى أتيحت للجمهور بصورة مشروعة ، ومقالاته المنشورة المتعلقة بالموضوعات التى تشغل الرأى العام فى وقت معين ، ما لم يكن المؤلف قد حظر ذلك عند النشر ، وبشرط الإشارة إلى المصدر الذى نقلت عنه وإلى اسم المؤلف وعنوان المصنف .
ثانيا - نشر الخطب والمحاضرات والندوات والأحاديث التى تلقى فى الجلسات العلنية للمجالس النيابية والهيئات التشريعية والإدارية والاجتماعات العلنية العلمية والأدبية والفنية والسياسية والاجتماعية والدينية ويشمل ذلك المرافعات القضائية فى الجلسات العلنية . ومع ذلك يظل للمؤلف وحده أو خلفه الحق فى جمع هذه المصنفات فى مجموعات تنسب إليه .
ثالثا - نشر مقتطفات من مصنف سمعى أو بصرى أو سمعى بصرى متاح للجمهور وذلك فى سياق التغطية الإخبارية للأحداث الجارية .$m239$,'125dc89dce61d16e0d7f51e60ee9fb56'),
(173,0,$m239$المادة 173$m239$,$m239$تنطبق القيود الواردة على الحقوق المالية للمؤلف طبقا لأحكام هذا القانون على أصحاب الحقوق المجاورة .$m239$,'07ddcb81b25adc577b7d0de22f2bc80a'),
(174,0,$m239$المادة 174$m239$,$m239$إذا اشترك أكثر من شخص فى تأليف مصنف بحيث لا يمكن فصل نصيب كل منهم فى العمل المشترك اعتبر جميع الشركاء مؤلفين للمصنف بالتساوى فيما بينهم ما لم يتفق كتابة على غير ذلك .
وفى هذه الحالة لا يجوز لأحدهم الانفراد بمباشرة حقوق المؤلف إلا باتفاق مكتوب بينهم .
فإذا كان اشتراك كل من المؤلفين يندرج تحت نوع مختلف من الفن ، كان لكل منهم الحق فى استغلال الجزء الذى ساهم به على حدة ، بشرط ألا يضر ذلك باستغلال المصنف المشترك ما لم يتفق كتابة على غير ذلك .
ولكل منهم الحق فى رفع الدعاوى عند وقوع اعتداء على أى حق من حقوق المؤلف .
وإذا مات أحد المؤلفين الشركاء دون خلف عام أو خاص ، يؤول نصيبه إلى باقى الشركاء أو خلفهم ، ما لم يتفق كتابة على غير ذلك .$m239$,'89f8a231c9c58f4d779eef0355a56b49'),
(175,0,$m239$المادة 175$m239$,$m239$يكون للشخص الطبيعى أو الاعتبارى الذى وجه إلى ابتكار المصنف الجماعى التمتع وحده بالحق فى مباشرة حقوق المؤلف عليه .$m239$,'404c718b0233cdff7653f7f83e819642'),
(176,0,$m239$المادة 176$m239$,$m239$يعتبر مؤلف المصنفات التى لا تحمل اسم المؤلف أو التى تحمل اسما مستعارا مفوضا للنشر لها فى مباشرة الحقوق المنصوص عليها فى هذا القانون ، ما لم يعين المؤلف وكيلا آخر أو يعلن عن شخصه ويثبت صفته .$m239$,'b4feb5c5b6dd3bbe39cbb729e8a690c0'),
(177,0,$m239$المادة 177$m239$,$m239$أولا - يعتبر شريكا فى تأليف المصنف السمعى البصرى أو السمعى أو البصرى :
1 - مؤلف السيناريو أو صاحب الفكرة المكتوبة للبرنامج .
2 - من يقوم بتحوير مصنف أدبى موجود بشكل يجعله ملائما للأسلوب السمعى البصرى .
3 - مؤلف الحوار .
4 - واضع الموسيقى إذا قام بوضعها خصيصا للمصنف .
5 - المخرج الذى قام بعمل إيجابى من الناحية الفكرية لتحقيق المصنف .
وإذا كان المصنف مبسطا أو مستخرجا من مصنف آخر سابق عليه يعتبر مؤلف هذا المصنف السابق شريكا فى المصنف الجديد .
ثانيا - لمؤلف السيناريو ومحور المصنف الأدبى ومؤلف الحوار والمخرج مجتمعين الحق فى عرض المصنف السمعى أو البصرى أو السمعى البصرى رغم معارضة مؤلف المصنف الأدبى الأصلى أو واضع الموسيقى ، وذلك دون إخلال بحقوق المعارض المترتبة على الاشتراك فى التأليف .
ثالثا - لمؤلف الشطر الأدبى أو الشطر الموسيقى الحق فى نشر مصنفه بطريقة أخرى غير الطريقة المنشور بها هذا المصنف المشترك ما لم يتفق كتابة على غير ذلك .
رابعا - إذا امتنع أحد الشركاء فى تأليف مصنف سمعى بصرى أو سمعى أو بصرى عن إتمام الشق الخاص به ، فلا يترتب على ذلك منع باقى المشتركين من استعمال الجزء الذى أنجزه كل منهم ، وذلك دون إخلال بما للممتنع من حقوق مترتبة على اشتراكه فى التأليف .
خامسا - يكون المنتج طوال استغلال المصنف السمعى البصرى أو السمعى أو البصرى المتفق عليه نائبا عن مؤلفى هذا المصنف وعن خلفهم فى الاتفاق على استغلاله دون الإخلال بحقوق مؤلفى المصنفات الأدبية أو الموسيقية المقتبسة أو المحورة ، كل ذلك ما لم يتفق كتابة على خلافه . ويعتبر المنتج ناشرا لهذا المصنف ، وتكون له حقوق الناشر عليه وعلى نسخه فى حدود أغراض الاستغلال التجارى له .$m239$,'61845f132b60b6d9ee5bcb320f743a9f'),
(178,0,$m239$المادة 178$m239$,$m239$لا يحق لمن قام بعمل صورة لآخر أن ينشر أو يعرض أو يوزع أصلها أو نسخا منها دون إذنه أو إذن من فى الصورة جميعا ما لم يتفق على خلافه . ومع ذلك يجوز نشر الصورة بمناسبة حوادث وقعت علنا أو إذا كانت الصورة تتعلق بأشخاص ذوى صفة رسمية أو عامة أو يتمتعون بشهرة محلية أو عالمية أو سمحت بهذا النشر السلطات العامة المختصة خدمة للصالح العام ، وبشرط ألا يترتب على عرض الصورة أو تداولها فى هذه الحالة مساس بشرف الشخص أو بسمعته أو اعتباره .
ويجوز للشخص الذى تمثله الصورة أن يأذن بنشرها فى الصحف وغيرها من وسائل النشر حتى ولو لم يسمح بذلك المصور ما لم يتفق على غير ذلك .
وتسرى هذه الأحكام على الصور أيا كانت الطريقة التى عملت بها من رسم أو حفر أو أية وسيلة أخرى .$m239$,'1986663f1efcc79c01a288a5f6a06518'),
(179,0,$m239$المادة 179$m239$,$m239$لرئيس المحكمة المختصة بأصل النزاع ، بناء على طلب ذى الشأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التالية أو غيرها من الإجراءات التحفظية المناسبة ، وذلك عند الاعتداء على أى من الحقوق المنصوص عليها فى هذا الكتاب :
1 - إجراء وصف تفصيلى للمصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى .
2 - وقف نشر المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى أو عرضه أو نسخه أو صناعته .
3 - توقيع الحجز على المصنف أو التسجيل الصوتى أو البرنامج الإذاعى الأصلى أو على نسخه وكذلك على المواد التى تستعمل فى إعادة نشر هذا المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى أو استخراج نسخ منه بشرط أن تكون تلك المواد غير صالحة إلا لإعادة نشر المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى .
4 - إثبات واقعة الاعتداء على الحق محل الحماية .
5 - حصر الإيراد الناتج عن استغلال المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى وتوقيع الحجز على هذا الإيراد فى جميع الأحوال .
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'da5c3255202c84ee31d990d0f56be069'),
(180,0,$m239$المادة 180$m239$,$m239$لذوى الشأن الحق فى التظلم إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدور الأمر أو إعلانه على حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا أو تعيين حارس مهمته إعادة نشر المصنف أو التسجيل الصوتى أو البرنامج الإذاعى أو استغلاله أو عرضه أو صناعته أو استخراج نسخ منه ، ويودع الإيراد الناتج خزانة المحكمة إلى أن يفصل فى أصل النزاع .$m239$,'78a7bb32066ed4e1aaac2f6aae45c6bc'),
(181,0,$m239$المادة 181$m239$,$m239$مع عدم الإخلال بأية عقوبة أشد فى قانون آخر ، يعاقب بالحبس مدة لا تقل عن شهر وبغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرة آلاف جنيه أو بإحدى هاتين العقوبتين ، كل من ارتكب أحد الأفعال الآتية :
أولا - بيع أو تأجير مصنف أو تسجيل صوتى أو برنامج إذاعى محمى طبقا لأحكام هذا القانون ، أو طرحه للتداول بأية صورة من الصور بدون إذن كتابى مسبق من المؤلف أو صاحب الحق المجاور .
ثانيا - تقليد مصنف أو تسجيل صوتى أو برنامج إذاعى أو بيعه أو عرضه للبيع أو للتداول أو للإيجار مع العلم بتقليده .
ثالثا - التقليد فى الداخل لمصنف أو تسجيل صوتى أو برنامج إذاعى منشور فى الخارج أو بيعه أو عرضه للبيع أو التداول أو للإيجار أو تصديره إلى الخارج مع العلم بتقليده .
رابعا - نشر مصنف أو تسجيل صوتى أو برنامج إذاعى أو أداء محمى طبقا لأحكام هذا القانون عبر أجهزة الحاسب الآلى أو شبكات الإنترنت أو شبكات المعلومات أو شبكات الاتصالات أو غيرها من الوسائل بدون إذن كتابى مسبق من المؤلف أو صاحب الحق المجاور .
خامسا - التصنيع أو التجميع أو الاستيراد بغرض البيع أو التأجير لأى جهاز أو وسيلة أو أداة مصممة أو معدة للتحايل على حماية تقنية يستخدمها المؤلف أو صاحب الحق المجاور كالتشفير أو غيره .
سادسا - الإزالة أو التعطيل أو التعييب بسوء نية لأية حماية تقنية يستخدمها المؤلف أو صاحب الحق المجاور كالتشفير أو غيره .
سابعا - الاعتداء على أى حق أدبى أو مالى من حقوق المؤلف أو من الحقوق المجاورة المنصوص عليها فى هذا القانون .
وتتعدد العقوبة بتعدد المصنفات أو التسجيلات الصوتية أو البرامج الإذاعية أو الأداءات محل الجريمة .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن ثلاثة أشهر والغرامة التى لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة النسخ محل الجريمة أو المتحصلة منها وكذلك المعدات والأدوات المستخدمة فى ارتكابها .
ويجوز للمحكمة عند الحكم بالإدانة أن تقضى بغلق المنشأة التى استغلها المحكوم عليه فى ارتكاب الجريمة مدة لا تزيد على ستة أشهر ، ويكون الغلق وجوبيا فى حالة العود فى الجرائم المنصوص عليها فى البندين ( ثانيا ، وثالثا ) من هذه المادة .
وتقضى المحكمة بنشر ملخص الحكم الصادر بالإدانة فى جريدة يومية أو أكثر على نفقة المحكوم عليه .$m239$,'35a085cd203c9a206dd299099d900d75'),
(182,0,$m239$المادة 182$m239$,$m239$فى حالة اتفاق طرفى النزاع على التحكيم تسرى أحكام قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994 ما لم يتفقا على غير ذلك .$m239$,'2b585caf755b97b63f06170cc1a54545'),
(183,0,$m239$المادة 183$m239$,$m239$تصدر الوزارة المختصة الترخيص بالاستغلال التجارى أو المهنى للمصنف أو التسجيل الصوتى أو الأداء أو البرنامج الإذاعى الذى يسقط فى الملك العام مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه .$m239$,'294ebe39261e2bbe19a7c498cdb8d0e9'),
(184,0,$m239$المادة 184$m239$,$m239$يلتزم ناشرو وطابعو ومنتجو المصنفات والتسجيلات الصوتية والأداءات المسجلة والبرامج الإذاعية بالتضامن فيما بينهم بإيداع نسخة منها أو أكثر بما لا يجاوز عشرة ، ويصدر الوزير المختص قرارا بتحديد عدد النسخ أو نظائرها البديلة مراعيا طبيعة كل مصنف ، وكذلك الجهة التى يتم فيها الإيداع .
ولا يترتب على عدم الإيداع المساس بحقوق المؤلف أو الحقوق المجاورة المنصوص عليها فى هذا القانون .
ويعاقب الناشر والطابع والمنتج عند مخالفة أحكام الفقرة الأولى من هذه المادة بغرامة لا تقل عن ألف جنيه ولا تجاوز ثلاثة آلاف جنيه عن كل مصنف أو تسجيل صوتى أو برنامج إذاعى وذلك دون الإخلال بالالتزام بالإيداع .
وتعفى من الإيداع المصنفات المنشورة فى الصحف والمجلات والدوريات إلا إذا نشر المصنف منفردا .$m239$,'1449388ec21e96bf1785a1b0912fe33e'),
(185,0,$m239$المادة 185$m239$,$m239$تنشىء الوزارة المختصة سجلا لقيد التصرفات الواردة على المصنفات والأداءات والتسجيلات الصوتية والبرامج الإذاعية الخاضعة لأحكام هذا القانون ، وتحدد اللائحة التنفيذية نظام القيد فى هذا السجل مقابل رسم بما لا يجاوز ألف جنيه للقيد الواحد .
ولا يكون التصرف نافذا فى حق الغير إلا بعد إتمام القيد .$m239$,'e4349e1039d625051e2a86f7ac1f0817'),
(186,0,$m239$المادة 186$m239$,$m239$يجوز لأى شخص الحصول من الوزارة المختصة على شهادة إيداع لمصنف أو أداء مسجل أو تسجيل صوتى أو برنامج إذاعى مودع ، وذلك مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه عن كل شهادة .$m239$,'eeae8b7ecad4ebf02468d4cde6571f87'),
(187,0,$m239$المادة 187$m239$,$m239$تلتزم جميع المحال التى تطرح للتداول بالبيع أو بالإيجار أو بالإعارة أو بالترخيص بالاستخدام مصنفات أو أداءات مسجلة أو تسجيلات صوتية أو برامج إذاعية بالآتى :
1 - الحصول على ترخيص بذلك من الوزير المختص مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه .
2 - إمساك دفاتر منتظمة تثبت فيها بيانات كل مصنف أو تسجيل صوتى أو برنامج إذاعى وسنة تداوله .
ومع عدم الإخلال بأية عقوبة أشد فى أى قانون آخر يعاقب على مخالفة أحكام هذه المادة بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرة آلاف جنيه .
وفى حالة العود تكون العقوبة الغرامة التى لا تقل عن عشرة آلاف جنيه ولا تجاوز عشرين ألف جنيه .$m239$,'bad4fc03465125d8ed74f05a3401e86a'),
(188,0,$m239$المادة 188$m239$,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا القانون .$m239$,'3e0cb9f006050c6369ec6572a50acfe3'),
(189,0,$m239$المادة 189$m239$,$m239$تتمتع بالحماية طبقا لأحكام هذا القانون الأصناف النباتية المستنبطة فى جمهورية مصر العربية أو فى الخارج سواء تم التوصل إليها بطريقة بيولوجية أو غير بيولوجية وذلك متى قيدت فى السجل الخاص بالأصناف النباتية التى تمنح حق الحماية .$m239$,'182046cf4e51c7b9d8f5c4dc9a05c3cc'),
(190,0,$m239$المادة 190$m239$,$m239$ينشأ بقرار من رئيس مجلس الوزراء مكتب يسمى مكتب حماية الأصناف النباتية ويختص هذا المكتب بتلقى الطلبات المقدمة للحصول على حماية الأصناف النباتية وفحصها والبت فيها ومنح شهادة الحماية ، وذلك طبقا للقواعد والإجراءات التى يحددها قرار الإنشاء .$m239$,'336c62aa1bd6ed1b39aeb453cb4249a2'),
(191,0,$m239$المادة 191$m239$,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية ، يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يقيمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، أن يتمتع بالحماية المقررة فى هذا الكتاب للأصناف النباتية .$m239$,'96d68f9a76a0bed8887cc08604006f96'),
(192,0,$m239$المادة 192$m239$,$m239$يشترط للتمتع بالحماية أن يكون الصنف متصفا بالجدة والتميز والتجانس والثبات وأن يحمل تسمية خاصة به .
ويكون الصنف جديدا إذا لم يقم مربى الصنف النباتى حتى تاريخ تقديم الطلب ببيع مواد الإكثار النباتى للصنف أو تداولها بنفسه أو بموافقته لأغراض الاستغلال ، ولا يفقد الصنف شرط الجدة إذا تم الطرح أو التداول فى جمهورية مصر العربية لمدة لا تزيد على سنة سابقة على تقديم الطلب . فإذا كان الطرح أو التداول قد تم فى الخارج فيجب ألا تزيد المدة على ست سنوات بالنسبة للأشجار والأعناب وألا تزيد على أربع سنوات بالنسبة لغيرها من الحاصلات الزراعية ، كما لا يفقد الصنف شرط الجدة إذا تم بيعه أو منح حق استغلاله بموافقة المربى للغير قبل منحه حق الحماية .
ويكون الصنف متميزا إذا أمكن تمييزه عن غيره من الأصناف المعروفة بصفة واحدة ظاهرة على الأقل مع احتفاظه بهذه الصفة عند إكثاره .
ويكون الصنف متجانسا إذا كان الاختلاف بين أفراده يقع فى نطاق الحدود المسموح بها .
ويكون الصنف ثابتا - عند تكرار زراعته - إذا لم تتغير خصائصه الأساسية بتكرار إكثاره لفترة تحددها اللائحة التنفيذية لهذا القانون .
وتمنح شهادة حق المربى لمستنبط الصنف النباتى الذى تتوافر فيه شروط الحماية سواء أكان المستنبط شخصا طبيعيا أو اعتباريا .$m239$,'33c396699ef362f16acd01d62551ed65'),
(193,0,$m239$المادة 193$m239$,$m239$تكون مدة حماية الأصناف النباتية خمس وعشرين سنة بالنسبة للأشجار والأعناب وعشرين سنة بالنسبة لغيرها من الحاصلات الزراعية .
وتبدأ مدة الحماية اعتبارا من تاريخ منحها .
ومع ذلك يمنح الصنف المقدم عنه الطلب حماية مؤقتة تبدأ من تاريخ إيداع الطلب وتنتهى بنشر الإعلان عن قبول منح الحماية على أن يقتصر حق المربى - المنصوص عليه بالمادة ( 194 ) من هذا القانون - خلال هذه الفترة على الحق فى التعويض العادل بمجرد منحه هذه الحماية ، بشرط أن يكون المربى قد وجه إخطارا بإيداعه الطلب إلى من قام باستغلال الصنف النباتى قبل منحه الحماية .$m239$,'da4e47b21738167380c71b2a4b616196'),
(194,0,$m239$المادة 194$m239$,$m239$يتمتع من يحصل على شهادة حق المربى بحق استئثارى يخول له الاستغلال التجارى للصنف النباتى المحمى بأى صورة من الصور ولا يجوز للغير إنتاج أو إكثار أو تداول أو بيع أو تسويق أو استيراد أو تصدير مواد الإكثار إلا بموافقة كتابية من المربى .$m239$,'f7bbdb82ebf37383b246f655df73c32c'),
(195,0,$m239$المادة 195$m239$,$m239$لا تمنع الحماية الغير من القيام بالأعمال الآتية :
1 - الأنشطة غير التجارية والاستخدام بغرض الإكثار الشخصى لناتج مادة الإكثار بواسطة المزارع على أرض فى حيازته الخاصة .
2 - الأنشطة المتصلة بالتجارب وبأغراض البحث العلمى .
3 - أنشطة التربية والتهجين والانتخاب وغيرها التى تستهدف استنباط أصناف جديدة .
4 - الأنشطة التى تتعلق بأغراض التعليم والتدريب .
5 - أنشطة الاستخدام والاستغلال التجارى والاستهلاك لمادة المحصول والمواد الأولية الوسيطة والمنتجات النهائية التى تصنع أو تستخرج من مادة المحصول بشكل مباشر أو غير مباشر سواء تمثلت مادة المحصول فى هيئة نبات كامل أو كانت جزءا منه .$m239$,'1c7912a38daf9cb2b2daca49db045806'),
(196,0,$m239$المادة 196$m239$,$m239$يمنح مكتب حماية الأصناف النباتية ، بناء على عرض وزير الزراعة وبعد موافقة لجنة وزارية تشكل بقرار من رئيس مجلس الوزراء ، تراخيص إجبارية باستخدام واستغلال الصنف المحمى دون موافقة المربى وذلك فى الحالات التى تقتضيها المصلحة العامة ، وكذلك فى حالات امتناع المربى عن إنتاج الصنف بمعرفته أو توفير مواد الإكثار للصنف المحمى أو رفضه منح حق استغلال الصنف للغير رغم مناسبة الشروط المعروضة عليه أو قيامه بالممارسات المضادة للتنافس .
ويستحق المربى تعويضا عادلا مقابل منح الغير حق استخدام واستغلال الصنف خلال مدة الترخيص الإجبارى وتراعى فى تقدير التعويض القيمة الاقتصادية لهذا الصنف .$m239$,'cb29d7a160921cf579aa6fdc922baed8'),
(197,0,$m239$المادة 197$m239$,$m239$يجب على المرخص له تطبيقا لأحكام المادة ( 196 ) من هذا القانون أن يلتزم بشروط الترخيص الإجبارى ، ولا يجوز له التنازل عنه للغير أو المساس بالحقوق الأخرى للمربى أثناء مدة الترخيص .
وينتهى هذا الترخيص بانتهاء المدة المحددة له ويلغى إذا خالف المرخص له لأى شرط من شروط الترخيص .$m239$,'d380569cdaea68efe2d53fbd825219c6'),
(198,0,$m239$المادة 198$m239$,$m239$تستنفد حقوق المربى على مواد الصنف المحمى إذا طرحت للتداول بمعرفته أو بموافقته خارج جمهورية مصر العربية ، ويحق للغير فى هذه الحالة تداول أو بيع أو تسويق أو توزيع أو استيراد الصنف المحمى سواء فى هيئة مواد إكثار أو مواد محصول من نبات كامل أو أى جزء منه أو المنتجات المستخرجة أو المصنعة من المحصول أو غير ذلك من مكونات النبات .
ويحق للمربى أن يمنع الغير من تصدير الصنف المحمى إذا كان التصدير يؤدى إلى إكثار الصنف فى بلد لا يتمتع الصنف فيه بالحماية . ومع ذلك لا يحق للمربى منع الغير من تصدير الصنف المحمى إلى أى دولة إذا كان الغرض منه هو الاستهلاك .$m239$,'df88f62282aa3775c1ac1285faa5fbcd'),
(199,0,$m239$المادة 199$m239$,$m239$لوزير الزراعة - بناء على توصية اللجنة الوزارية المشار إليها فى المادة ( 196 ) من هذا القانون - أن يقيد مباشرة المربى لكل أو بعض حقوقه المنصوص عليها فى هذا القانون بأى صورة من الصور بهدف تحقيق المصلحة العامة خاصة فى الأحوال الآتية :
1 - إذا ظهر للصنف النباتى المحمى تأثير ضار على البيئة الطبيعية أو على سلامة التنوع البيولوجى فى جمهورية مصر العربية ، أو على القطاع الزراعى فيها ، أو على حياة أو صحة الإنسان أو الحيوان أو النبات .
2 - إذا ظهر للصنف النباتى المحمى تأثير اقتصادى أو اجتماعى ضار أو معوق للأنشطة الزراعية المحلية ، أو إذا ظهر له استخدام يتناقض مع قيم ومعتقدات المجتمع .$m239$,'461cac5c1bdaaaa5b0c6287a32b888ba'),
(200,0,$m239$المادة 200$m239$,$m239$يلتزم المربى بالكشف عن المصدر الوراثى الذى اعتمد عليه لاستنباط الصنف النباتى الجديد ، ويشترط لتمتع الصنف النباتى الجديد بالحماية أن يكون المربى قد حصل على ذلك المصدر بطريق مشروع وفقا للقانون المصرى .
ويمتد هذا الالتزام إلى المعلومات التراثية والخبرات التى تراكمت لدى الجماعات المحلية التى يكون المربى قد اعتمد عليها فى جهوده لاستنباط هذا الصنف النباتى الجديد .
وبالمثل يلتزم المربى الذى يتعامل مع الموارد الوراثية المصرية بهدف استنباط أصناف جديدة مشتقة منها بالحصول على موافقة الجهة الإدارية المختصة على هذا التعامل ، كما يتعهد باحترام المعارف التراثية المصرية كمصادر لما يكون قد توصل إليه من إنجازات استخدمت فيها تلك المعارف والخبرات ، ويكون ذلك بالإعلان عن المصدر المصرى الذى استفاد منه ذلك المربى وباقتسام العوائد التى يحققها مع صاحب المصلحة ، وذلك على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
وينشأ بوزارة الزراعة سجل لقيد الموارد الوراثية المصرية النباتية ، البرية والبلدية منها .$m239$,'4ce163a87a8524dd3d7151488b8556a9'),
(201,0,$m239$المادة 201$m239$,$m239$يصدر مكتب حماية الأصناف النباتية شهادة حق المربى وفقا للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون وبعد أداء رسم تحدده هذه اللائحة بما لا يجاوز خمسة آلاف جنيه .
ويتم النشر عن ذلك على نفقة صاحب الحق فى جريدة شهرية يصدرها المكتب ، ويخطر من رفض طلبه بقرار الرفض وأسبابه ، ويكون لكل ذى شأن حق التظلم من قرار منح شهادة حق المربى أو رفض طلب حماية الصنف النباتى ، وذلك خلال خمسة عشر يوما من تاريخ النشر أو من تاريخ الإخطار على حسب الأحوال .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات الإخطار ونظر التظلم والبت فيه .$m239$,'6e474a034218197dbb248964bed15c58'),
(202,0,$m239$المادة 202$m239$,$m239$تلغى شهادة حق المربى وذلك فى أحوال فقد الصنف لأحد الشروط الخاصة بمنحها أو فى حالة منحها بالمخالفة لأحكام هذا القانون ، وذلك وفقا للقواعد والإجراءات التى يصدر بها قرار من وزير الزراعة .
ويكون إخطار ذى الشأن بهذا القرار بموجب كتاب موصى عليه مصحوبا بعلم الوصول ، وله أن يتظلم منه خلال خمسة عشر يوما من تاريخ الإخطار .
ويصدر وزير الزراعة قرارا بقواعد وإجراءات نظر التظلم والبت فيه .$m239$,'f7cf4b4cbb3b7d8a25be9e19d3ab8f6b'),
(203,0,$m239$المادة 203$m239$,$m239$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر يعاقب كل من يخالف عمدا أحكام هذا الكتاب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن ثلاثة أشهر ولا تجاوز سنة ، وبغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه .
وفى جميع الأحوال يحكم بمصادرة التقاوى ومواد الإكثار المضبوطة .$m239$,'f7bdf93578effce81577315d97a3e4e9'),
(204,0,$m239$المادة 204$m239$,$m239$لرئيس المحكمة المختصة بأصل النزاع وبناء على طلب كل ذى شأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة ، وعلى وجه الخصوص :
1 - إثبات واقعة الاعتداء على الحق محل الحماية .
2 - إجراء حصر ووصف تفصيلى للمنتجات المخالفة والأدوات التى استخدمت أو تستخدم فى ارتكاب الجريمة .
3 - توقيع الحجز على الأشياء المذكورة فى البند ( 2 ) .
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة المختصة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'02d3191eea741666671f347e01b9fcb0'),
(205,0,$m239$المادة 205$m239$,$m239$لذوى الشأن التظلم من الأمر إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدوره أو إعلانه على حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا ، وفقا للقواعد والإجراءات المنصوص عليها فى قانون المرافعات المدنية والتجارية .$m239$,'aa27aaf2f5f021e8e38d1423b6a3e800'),
(206,0,$m239$المادة 206$m239$,$m239$يصدر وزير العدل بالاتفاق مع وزير الزراعة قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الكتاب .$m239$,'a24225b480385d77024136fd374b8faa');

INSERT INTO m239_ver VALUES
(0,0,1,$m239$قانون رقم 82 لسنة 2002 بإصدار قانون حماية حقوق الملكية الفكرية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m239$,'51374f949d35d0e6b5ff348308a1cfa0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m239$يعمل بأحكام القانون المرافق فى شأن حماية حقوق الملكية الفكرية .$m239$,'48bd1cb387939748ff867963beaa1620',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m239$تلغى القوانين الآتية :
( أ ) القانون رقم 57 لسنة 1939 بشأن العلامات والبيانات التجارية .
( ب ) القانون رقم 132 لسنة 1949 بشأن براءات الاختراع والرسوم والنماذج الصناعية ، عدا أحكام براءات الاختراع الخاصة بالمنتجات الكيميائية المتعلقة بالأغذية والمنتجات الكيميائية الصيدلية فتلغى اعتبارا من أول يناير سنة 2005
( ج ) القانون رقم 354 لسنة 1954 بشأن حماية حق المؤلف .
كما يلغى كل حكم يخالف أحكام القانون المرافق .$m239$,'9e8b7e0cb04e8f81359d8d9d47dc9345',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(3,-1,1,$m239$يصدر مجلس الوزراء بناء على عرض الوزراء المختصين اللائحة التنفيذية فى مدة لا تزيد على شهر من تاريخ العمل بهذا القانون . ويصدر الوزراء المختصون كل فى حدود اختصاصه القرارات اللازمة لتنفيذ أحكام القانون المرافق .
وعلى الوزراء كل فيما يخصه اتخاذ التدابير اللازمة لحماية الصحة العامة والتغذية ، أو تنمية القطاعات الحيوية فى المجال الاجتماعى والاقتصادى والتكنولوجى ، وذلك فى حدود أحكام القانون المرافق .
وللوزراء كل فيما يخصه اتخاذ الإجراءات اللازمة فى إطار هذا القانون لمنع حائزى الملكية الفكرية من إساءة استخدامها أو منع اللجوء إلى الممارسات التى تسفر عن تقييد غير مناسب للتجارة ، أو تؤثر سلبا على النقل الدولى للتكنولوجيا ، وذلك كله على النحو المبين فى القانون المرافق .$m239$,'42aeb7a7faa3ea9940b2467b9cff6499',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(4,-1,1,$m239$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتبارا من اليوم التالى لتاريخ نشره ، عدا أحكام براءات الاختراع الخاصة بالمنتجات الكيميائية المتعلقة بالأغذية ، والمنتجات الكيميائية الصيدلية والكائنات الدقيقة والمنتجات التى لم تكن محل حماية قبل صدور هذا القانون فيعمل بها اعتبارا من أول يناير سنة 2005 ، وذلك دون الإخلال بأحكام المادتين ( 44 ، 45 ) من القانون المرافق .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 21 ربيع الأول سنة 1423 هـ . ( الموافق 2 يونية سنة 2002 م ) .
حسنى مبارك$m239$,'711d5a3cc0f7629cf0c4520655785cce',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m239$تمنح براءة اختراع طبقا لأحكام هذا القانون عن كل اختراع قابل للتطبيق الصناعى ، يكون جديدا ، ويمثل خطوة إبداعية ، سواء كان الاختراع متعلقا بمنتجات صناعية جديدة أو بطرق صناعية مستحدثة ، أو بتطبيق جديد لطرق صناعية معروفة .
كما تمنح البراءة استقلالا ، عن كل تعديل أو تحسين أو إضافة ترد على اختراع سبق أن منحت عنه براءة ، إذا توافرت فيه شروط الجدة والإبداع والقابلية للتطبيق الصناعى على النحو المبين فى الفقرة السابقة ، ويكون منح البراءة لصاحب التعديل أو التحسين أو الإضافة وفقا لأحكام هذا القانون .$m239$,'a5ca9490ba8e429338a765d1cd6d7825',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(2,0,1,$m239$لا تمنح براءة اختراع لما يلى :
1 - الاختراعات التى يكون من شأن استغلالها المساس بالأمن القومى أو الإخلال بالنظام العام أو الآداب العامة أو الإضرار الجسيم بالبيئة أو الإضرار بحياة أو صحة الإنسان أو الحيوان أو النبات .
2 - الاكتشافات والنظريات العلمية والطرق الرياضية والبرامج والمخططات .
3 - طرق تشخيص وعلاج وجراحة الإنسان أو الحيوان .
4 - النباتات والحيوانات أيا كانت درجة ندرتها أو غرابتها وكذلك الطرق التى تكون فى أساسها بيولوجية لإنتاج النباتات أو الحيوانات ، عدا الكائنات الدقيقة والطرق غير البيولوجية والبيولوجية الدقيقة لإنتاج النباتات أو الحيوانات .
5 - الأعضاء والأنسجة والخلايا الحية والمواد البيولوجية الطبيعية والحمض النووى والجينوم .$m239$,'e83c453531baf2d00b5c870dbe433baa',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(3,0,1,$m239$لا يعتبر الاختراع جديدا كله أو جزء منه فى الحالتين الآتيتين :
1 - إذا كان قد سبق طلب إصدار براءة اختراع أو صدرت براءة عنه أو عن جزء منه فى جمهورية مصر العربية أو فى الخارج قبل تاريخ تقديم طلب البراءة .
2 - إذا كان قد سبق استعمال الاختراع أو استغلاله فى جمهورية مصر العربية أو فى الخارج بصفة علنية أو كان قد أفصح عن وصفه على نحو يمكن ذوى الخبرة من استغلاله قبل تقديم طلب البراءة .
ولا يعد إفصاحا فى حكم البند السابق الكشف عن الاختراع فى المعارض الوطنية أو الدولية خلال الستة الأشهر السابقة على تاريخ التقدم بطلب البراءة .
وتحدد اللائحة التنفيذية لهذا القانون أوضاع وإجراءات الكشف عن الاختراع .$m239$,'ed5889fcde3507297950be72cd8f694c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، الحق فى التقدم بطلب براءة اختراع لمكتب براءات الاختراع فى جمهورية مصر العربية وما يترتب على ذلك من حقوق طبقا لأحكام هذا القانون .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بالحقوق المنصوص عليها فى هذا الباب ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'65ea23dfb802291488d0db081b991866',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m239$يعد بمكتب براءات الاختراع سجل خاص معتمد تقيد فيه طلبات براءات الاختراع ونماذج المنفعة وجميع البيانات المتعلقة بكل منها وباستغلالها والتصرفات التى ترد عليها وفقا لأحكام هذا القانون وذلك على النحو المبين فى لائحته التنفيذية .$m239$,'0056f3d629122cb07e90304e55d8e4a4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m239$يثبت الحق فى البراءة للمخترع أو لمن آلت إليه حقوقه .
وإذا كان الاختراع نتيجة عمل مشترك بين عدة أشخاص ، ثبت حقهم فى البراءة بالتساوى فيما بينهم ما لم يتفقوا على غير ذلك .
أما إذا كان قد توصل إلى ذات الاختراع أكثر من شخص يستقل كل منهم عن الآخر ، يثبت الحق للأسبق فى تقديم طلب البراءة .$m239$,'a98ebab9e2e2deae793f8d200f7ae0cb',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m239$إذا كلف شخص آخر الكشف عن اختراع معين فجميع الحقوق المترتبة على هذا الاختراع تكون للأول ، وكذلك لصاحب العمل جميع الحقوق المترتبة على الاختراعات التى يستحدثها العامل أو المستخدم أثناء قيام رابطة العمل أو الاستخدام ، متى كان الاختراع فى نطاق العقد أو رابطة العمل أو الاستخدام .
ويذكر اسم المخترع فى البراءة ، وله أجره على اختراعه فى جميع الحالات فإذا لم يتفق على هذا الأجر كان له الحق فى تعويض عادل ممن كلفه الكشف عن الاختراع ، أو من صاحب العمل .
وفى غير الأحوال السابقة ، وعندما يكون الاختراع ضمن نشاط المنشأة العامة أو الخاصة الملحق بها المخترع ، يكون لصاحب العمل الخيار بين استغلال الاختراع ، أو شراء البراءة مقابل تعويض عادل يدفعه للمخترع ، على أن يتم الاختيار فى خلال ثلاثة أشهر من تاريخ الإخطار بمنح البراءة .
وفى جميع الأحوال يبقى الاختراع منسوبا إلى المخترع .$m239$,'bcde7f3099361bdfabf81340a266a582',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m239$الطلب المقدم من المخترع للحصول على براءة اختراع فى خلال سنة من تاريخ تركه المنشأة الخاصة أو العامة ، يعتبر كأنه قدم فى خلال تنفيذ العقد أو قيام رابطة العمل أو الاستخدام ، ويكون لكل من المخترع وصاحب العمل جميع الحقوق المنصوص عليها فى المادة السابقة تبعا للأحوال .
وتزداد المدة إلى ثلاث سنوات إذا أنشأ العامل أو التحق بمنشأة منافسة ، وكان الاختراع نتيجة مباشرة لنشاطه وخبرته السابقة بالمنشأة التى كان يعمل بها .$m239$,'66b1cf126fd7f428ebcaa88f4b858755',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m239$مدة حماية براءة الاختراع عشرون سنة تبدأ من تاريخ تقديم طلب البراءة فى جمهورية مصر العربية .$m239$,'e6741480e24b25d43491729dde6be293',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(10,0,1,$m239$تخول البراءة مالكها الحق فى منع الغير من استغلال الاختراع بأية طريقة .
ويستنفد حق مالك البراءة فى منع الغير من استيراد أو استخدام أو بيع أو توزيع السلعة ، إذا قام بتسويقها فى أية دولة أو رخص للغير بذلك .
ولا يعتبر اعتداء على هذا الحق ما يقوم به الغير من الأعمال الآتية :
1 - الأعمال المتصلة بأغراض البحث العلمى .
2 - قيام الغير فى جمهورية مصر العربية ، بصنع منتج ، أو باستعمال طريقة صنع منتج معين أو باتخاذ ترتيبات جدية لذلك ما لم يكن سىء النية ، وذلك قبل تاريخ تقديم طلب البراءة من شخص آخر عن المنتج ذاته ، أو عن طريقة صنعه ، ولهذا الغير رغم صدور البراءة حق الاستمرار لصالح منشأته فقط فى القيام بالأعمال المذكورة ذاتها دون التوسع فيها ، ولا يجوز التنازل عن حق القيام بهذه الأعمال ، أو نقل هذا الحق إلا مع باقى عناصر المنشأة .
3 - الاستخدامات غير المباشرة لطريقة الإنتاج ، التى يتكون منها موضوع الاختراع وذلك للحصول على منتجات أخرى .
4 - استخدام الاختراع فى وسائل النقل البرى أو البحرى أو الجوى التابعة لإحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، وذلك فى حالة وجود أى من هذه الوسائل فى جمهورية مصر العربية بصفة وقتية أو عارضة .
5 - قيام الغير بصنع أو تركيب أو استخدام أو بيع المنتج أثناء فترة حمايته بهدف استخراج ترخيص لتسويقه ، على ألا يتم التسويق إلا بعد انتهاء تلك الفترة .
6 - الأعمال التى يقوم بها الغير خلاف ما تقدم ، شريطة ألا تتعارض بشكل غير معقول مع الاستخدام العادى للبراءة ، وألا تضر بصورة غير معقولة بالمصالح المشروعة لصاحب البراءة ، مع مراعاة المصالح المشروعة للغير .$m239$,'50eb344c31ac8658c43184e53203441a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m239$يستحق رسم عند تقديم طلب براءة الاختراع كما يستحق رسم سنوى يتدرج بالزيادة اعتبارا من بداية السنة الثانية وحتى انتهاء مدة حماية البراءة .
وتحدد اللائحة التنفيذية قيمة هذه الرسوم بما لا يجاوز ألفى جنيه عند تقديم الطلب ، وبما لا يجاوز ألف جنيه بالنسبة للرسم السنوى .
كما تحدد اللائحة قواعد تخفيض هذه الرسوم وأحوال الإعفاء منها .
ويتحمل مقدم طلب الحصول على البراءة أتعاب الخبراء الذين يستعين بهم مكتب البراءات ومصروفات الفحص .$m239$,'07f5cd7e3e54fb3627e6e9b6a3f0aa73',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(12,0,1,$m239$يقدم طلب البراءة من المخترع أو ممن آلت إليه حقوقه إلى مكتب براءات الاختراع وفقا للأوضاع والشروط التى تحددها اللائحة التنفيذية لهذا القانون ، ولا يجوز أن يتضمن طلب البراءة أكثر من اختراع واحد ، ويعتبر فى حكم الاختراع الواحد مجموعة الاختراعات التى تشكل فكرة إبداعية متكاملة .$m239$,'ff3f778ecd489e7a1aaaea963b809b18',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(13,0,1,$m239$يرفق بطلب البراءة وصف تفصيلى للاختراع يتضمن بيانا كاملا عن موضوعه ، وعن أفضل أسلوب يمكن ذوى الخبرة من تنفيذه ، وذلك بالنسبة لكل واحد من المنتجات والطرق محل الطلب .
ويجب أن يشتمل الوصف بطريقة واضحة على العناصر الجديدة التى يطلب صاحب الشأن حمايتها ، وأن يرفق بالطلب رسم هندسى للاختراع عند الاقتضاء .
وإذا كان الطلب متعلقا باختراع يتضمن مواد بيولوجية نباتية أو حيوانية ، أو معارف تقليدية طبية أو زراعية أو صناعية أو حرفية ، أو تراثا حضاريا أو بيئيا ، فيجب أن يكون المخترع حاصلا على مصدرها بطريقة مشروعة .
فإذا كان الطلب متعلقا بكائنات دقيقة وجب على الطالب أن يفصح عن هذه الكائنات ، وأن يودع مزرعة حية منها لدى الجهة التى تحددها اللائحة التنفيذية لهذا القانون .
ومع مراعاة أحكام المادة ( 38 ) من هذا القانون يلتزم الطالب فى جميع الأحوال بتقديم بيانات ومعلومات كاملة عن الطلبات التى سبق أن قدمها فى الخارج عن نفس الاختراع أو ما يتصل بموضوعه وكذلك نتائج البت فى هذه الطلبات .
وتحدد اللائحة التنفيذية لهذا القانون مرفقات طلب براءة الاختراع والمواعيد الواجب تقديمها خلالها والأحوال التى تستوجب رفضه .$m239$,'3c915485ce42da8077c40ff9806771a1',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(14,0,1,$m239$لمكتب براءات الاختراع أن يكلف طالب البراءة بإجراء التعديلات أو الاستيفاءات التى يراها على الطلب إعمالا لأحكام المادة ( 13 ) من هذا القانون ، وذلك على النحو الذى تبينه اللائحة التنفيذية ، فإذا لم يقم الطالب بهذا الإجراء خلال ثلاثة أشهر من تاريخ إخطاره اعتبر متنازلا عن طلبه .
وللطالب أن يتظلم من قرار مكتب براءات الاختراع بشأن هذا التكليف أمام اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ، وذلك خلال ثلاثين يوما ووفقا للإجراءات التى تبينها اللائحة التنفيذية .$m239$,'fd24284125398ef9507fac208336b6bb',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(15,0,1,$m239$يجوز لطالب براءة الاختراع أن يقدم فى أى وقت قبل الإعلان عن قبول طلب البراءة طلبا بتعديل مواصفات الاختراع أو رسمه الهندسى مع بيان ماهية التعديل وأسبابه ويشرط ألا يؤدى التعديل إلى المساس بذاتية الاختراع ، وتتبع فى هذا الشأن ذات الإجراءات الخاصة بطلب البراءة .$m239$,'0fd5b7353b710e6d3e3bd888b657bf57',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(16,0,1,$m239$يفحص مكتب براءات الاختراع طلب البراءة ومرفقاته للتحقق من أن الاختراع جديد ويمثل خطوة إبداعية وقابل للتطبيق الصناعى طبقا لأحكام المواد ( 1 ) ، ( 2 ) ، ( 3 ) من هذا القانون .
فإذا توافرت فى الاختراع الشروط المشار إليها ، وروعيت فى طلب البراءة الأحكام المنصوص عليها فى المادتين ( 12 ) ، ( 13 ) من هذا القانون قام مكتب براءات الاختراع بالإعلان عن قبول الطلب فى جريدة براءات الاختراع بالطريقة التى تحددها اللائحة التنفيذية .
ويجوز لكل ذى شأن أن يعترض كتابة على السير فى إجراءات إصدار البراءة بإخطار يوجه إلى مكتب براءات الاختراع متضمنا أسباب الاعتراض وذلك خلال ستين يوما من تاريخ الإعلان عن قبول الطلب فى جريدة براءات الاختراع ، ووفقا للأوضاع التى تحددها اللائحة التنفيذية لهذا القانون .
ويؤدى مقدم الإخطار بالاعتراض رسما تحدده اللائحة التنفيذية لهذا القانون بما لا يقل عن مائة جنيه ولا يجاوز ألف جنيه ويسترد الرسم فى حالة قبول الاعتراض .
وتختص بنظر الاعتراضات اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية .$m239$,'cd94cd21a1157c09d122211881084392',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(17,0,1,$m239$يرسل مكتب براءات الاختراع إلى وزارة الدفاع أو وزارة الإنتاج الحربى أو وزارة الداخلية أو وزارة الصحة على حسب الأحوال صورا من طلبات براءات الاختراع التى تتصل بشئون الدفاع أو الإنتاج الحربى أو الأمن العام أو التى لها قيمة عسكرية أو أمنية أو صحية ، مع مرفقات هذه الطلبات ، وذلك خلال عشرة أيام من تاريخ الانتهاء من الفحص مع إخطار الطالب بذلك خلال سبعة أيام من تاريخ الإرسال ، ولوزير الدفاع أو وزير الإنتاج الحربى أو وزير الداخلية أو وزير الصحة على حسب الأحوال أن يعترض على الإعلان عن قبول طلب البراءة ، خلال تسعين يوما من تاريخ الإرسال .
وللوزير المختص - على حسب الأحوال - بعد الإعلان عن قبول طلب البراءة الاعتراض على السير فى إجراءات إصدارها وذلك إذا يتبين له أن الطلب يتعلق بشئون الدفاع أو الإنتاج الحربى أو الأمن العام أو أن له قيمة عسكرية أو أمنية أو صحية ، ويكون الاعتراض خلال تسعين يوما من تاريخ الإعلان عن قبول طلب البراءة فى جريدة براءات الاختراع .
ويترتب على الاعتراض فى الحالات المشار إليها وقف السير فى إجراءات إصدار البراءة .$m239$,'8d8a550dc722bc771e5f0cbd2afcdd23',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(18,0,1,$m239$ينشأ صندوق لموازنة أسعار الدواء - غير المعد للتصدير - وتكون له الشخصية الاعتبارية ، ويتبع وزير الصحة والسكان ، وذلك لتحقيق التنمية الصحية وضمان عدم تأثر تلك الأسعار بما يطرأ من متغيرات ، ويصدر بتنظيم الصندوق وتحديد موارده قرار من رئيس الجمهورية على أن يكون من بين هذه الموارد ما تقبله الدولة من مساهمات من الدول المانحة والمنظمات الدولية الحكومية وغير الحكومية .$m239$,'3f657dcf0b66418e45da069729e6de79',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(19,0,1,$m239$لا يتم الإعلان عن قبول طلب البراءة إلا بعد انقضاء سنة تبدأ من تاريخ تقديمه ويظل الطلب سريا خلال تلك الفترة .
ويكون منح البراءة بقرار من الوزير المختص أو من يفوضه فى ذلك وينشر هذا القرار فى جريدة براءات الاختراع بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'ed0d3e2d20c83f6787999d299d88061a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(20,0,1,$m239$للكافة بعد الإعلان عن قبول الطلب الاطلاع عليه وعلى مستنداته وما دون عنه فى سجل براءات الاختراع ، كما يجوز لأى منهم الحصول على صورة مما تقدم وذلك مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه ، ووفقا للأوضاع والإجراءات التى تقررها هذه اللائحة .$m239$,'61b08ac3ece7ec712a905a5daebc1a40',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(21,0,1,$m239$يجوز نقل ملكية البراءة كلها أو بعضها بعوض أو بغير عوض ، كما يجوز رهنها أو تقرير حق الانتفاع عليها .
ومع عدم الإخلال بالأحكام الخاصة ببيع المحال التجارية ورهنها لا تنتقل ملكية البراءة ولا يكون رهنها أو تقرير حق انتفاع عليها حجة على الغير إلا من تاريخ التأشير بذلك فى سجل البراءات .
ويكون النشر عن انتقال ملكية البراءة أو رهنها أو تقرير حق الانتفاع عليها وفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية .$m239$,'a6b9461811a813970303f802764b36f3',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(22,0,1,$m239$يجوز للدائن أن يوقع الحجز على براءة الاختراع الخاصة بمدينه وفقا لقواعد الحجز على المنقول تحت يد المدين ولدى الغير ، ولا يلتزم مكتب البراءات بالأحكام المتعلقة بإقرار المحجوز لديه بما فى الذمة قبل المحجوز عليه .
ويجب على الدائن أن يعلن الحجز ومحضر مرسى المزاد لمكتب البراءات التأشير بهما فى السجل ولا يكون أيهما حجة على الغير إلا من تاريخ ذلك التأشير .
وينشر عن الحجز بالطريقة التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'1deb828e2e2ef7015fe7f5ab00acf051',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(23,0,1,$m239$يمنح مكتب براءات الاختراع - وبعد موافقة لجنة وزارية تشكل بقرار من رئيس مجلس الوزراء - تراخيص إجبارية باستغلال الاختراع ، وتحدد اللجنة الحقوق المالية لصاحب البراءة عند إصدار هذه التراخيص . وذلك فى الحالات الآتية :
أولا - إذا رأى الوزير المختص - بحسب الأحوال - أن استغلال الاختراع يحقق ما يلى :
1 - أغراض المنفعة العامة غير التجارية :
ويعتبر من هذا القبيل أغراض المحافظة على الأمن القومى ، والصحة ، وسلامة البيئة والغذاء .
2 - مواجهة حالات الطوارىء أو ظروف الضرورة القصوى .
ويصدر الترخيص الإجبارى لمواجهة الحالات الواردة فى البندين ( 1 ) ، ( 2 ) دون الحاجة لتفاوض مسبق مع صاحب البراءة ، أو لانقضاء فترة من الزمن على التفاوض معه ، أو لعرض شروط معقولة للحصول على موافقته بالاستغلال .
3 - دعم الجهود الوطنية فى القطاعات ذات الأهمية للتنمية الاقتصادية والاجتماعية والتكنولوجية ، وذلك دون إخلال غير معقول بحقوق مالك البراءة ، ومع مراعاة المصالح المشروعة للغير .
ويلزم إخطار صاحب البراءة بقرار الترخيص الإجبارى بصورة فورية فى الحالات الواردة فى البندين ( 1 ) ، ( 3 ) وفى أقرب فرصة معقولة تتيحها الحالات الواردة فى البند ( 2 ) .
ثانيا - إذا طلب وزير الصحة فى أية حالة من حالات عجز كمية الأدوية المحمية بالبراءة عن سد احتياجات البلاد ، أو انخفاض جودتها ، أو الارتفاع غير العادى فى أسعارها ، أو إذا تعلق الاختراع بأدوية الحالات الحرجة أو الأمراض المزمنة أو المستعصية أو المتوطنة أو بالمنتجات التى تستخدم فى الوقاية من هذه الأمراض ، وسواء تعلق الاختراع بالأدوية ، أو بطريقة إنتاجها ، أو بالمواد الخام الأساسية التى تدخل فى إنتاجها ، أو بطريقة تحضير المواد الخام اللازمة لإنتاجها .
ويجب فى جميع هذه الحالات إخطار صاحب البراءة بقرار الترخيص الإجبارى بصورة فورية .
ثالثا - إذا رفض صاحب البراءة الترخيص للغير باستغلال الاختراع - أيا كان الغرض من الاستغلال - رغم عرض شروط مناسبة عليه ، وانقضاء فترة تفاوض معقولة .
ويتعين على طالب الترخيص الإجبارى فى هذه الحالة أن يثبت أنه قد بذل محاولات جدية للحصول على الترخيص الاختيارى من صاحب البراءة .
رابعا - إذا لم يقم صاحب البراءة باستغلالها فى جمهورية مصر العربية ، بمعرفته أو أو بموافقته أو كان استغلالها استغلالا غير كاف ، رغم مضى أربع سنوات من تاريخ تقديم طلب البراءة أو ثلاث سنوات من تاريخ منحها أيهما أطول ، وكذلك إذا أوقف صاحب البراءة استغلال الاختراع بدون عذر مقبول لمدة تزيد على سنة .
ويكون الاستغلال بإنتاج المنتج موضوع الحماية فى جمهورية مصر العربية ، أو باستخدام طريقة الصنع المحمية ببراءة الاختراع فيها .
ومع ذلك ، إذا رأى مكتب براءات الاختراع ، رغم فوات أى من المدتين المشار إليهما ، أن عدم استغلال الاختراع يرجع إلى أسباب قانونية أو فنية أو اقتصادية خارجة عن إرادة صاحب البراءة ، جاز أن يمنحه مهلة أخرى كافية لاستغلال الاختراع .
خامسا - إذا ثبت تعسف صاحب البراءة أو قيامه بممارسة حقوقه التى يستمدها من البراءة على نحو مضاد للتنافس ويعتبر من قبيل ذلك ما يلى :
1 - المبالغة فى أسعار بيع المنتجات المشمولة بالحماية ، أو التمييز بين العملاء فيما يتعلق بأسعار وشروط بيعها .
2 - عدم توفير المنتج المشمول بالحماية فى السوق ، أو طرحه بشروط مجحفة .
3 - وقف إنتاج السلعة المشمولة بالحماية أو إنتاجها بكمية لا تحقق التناسب بين الطاقة الإنتاجية وبين احتياجات السوق .
4 - القيام بأعمال أو تصرفات تؤثر سلبا على حرية المنافسة ، وفقا للضوابط القانونية المقررة .
5 - استعمال الحقوق التى يخولها القانون على نحو يؤثر سلبا على نقل التكنولوجيا .
وفى جميع الأحوال السابقة يصدر الترخيص الإجبارى دون حاجة للتفاوض ، أو انقضاء مهلة على حصوله ، ولو كان الترخيص الإجبارى لا يستهدف الوفاء باحتياجات السوق المحلى .
ويكون لمكتب براءات الاختراع أن يرفض إنهاء الترخيص الإجبارى إذا كانت الظروف التى دعت لإصداره تدل على استمرارها أو تنبئ بتكرار حدوثها .
ويراعى عند تقدير التعويض المستحق لصاحب البراءة الأضرار التى سببتها ممارساته التعسفية أو المضادة للتنافس .
ويجوز لمكتب براءات الاختراع إسقاط البراءة إذا تبين بعد مضى سنتين من منح الترخيص الإجبارى أن ذلك الترخيص لم يكن كافيا لتدارك الآثار السلبية التى لحقت بالاقتصاد القومى بسبب تعسف صاحب البراءة فى استعمال حقوقه أو لممارساته المضادة للتنافس .
ويجوز لكل ذى مصلحة الطعن فى قرار إسقاط البراءة أمام اللجنة المنصوص عليها فى المادة ( 36 ) ، ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
سادسا - إذا كان استغلال صاحب الحق فى براءة اختراع لا يتم إلا باستغلال اختراع آخر لازم له وكان منطويا على تقدم تقنى ملموس وأهمية فنية واقتصادية مقارنة بهذا الآخر ، فإنه يحق له الحصول على ترخيص إجبارى فى مواجهة الآخر ويكون لهذا الآخر ذات الحق فى هذه الحالة .
ولا يجوز التنازل عن الاستخدام المرخص به لإحدى البراءتين إلا بالتنازل عن استخدام البراءة الأخرى .
سابعا - فى حالات الاختراعات المتعلقة بتكنولوجيا أشباه الموصلات ، لا يمنح الترخيص الإجبارى إلا لأغراض المنفعة العامة غير التجارية ، أو لمعالجة الآثار التى يثبت أنها مضادة للتنافس .
ويكون منح التراخيص الإجبارية فى الحالات المنصوص عليها فى هذه المادة وفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'813e1e4a084ced6f8f30a77f03c024f7',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(24,0,1,$m239$يراعى عند إصدار الترخيص الإجبارى ما يلى :
1 - أن يبت فى طلب إصدار الترخيص الإجبارى ، وفقا لظروف كل حالة على حدة ، وأن يستهدف الترخيص أساسا توفير احتياجات السوق المحلية .
2 - أن يثبت طالب الترخيص الإجبارى أنه بذل خلال مدة معقولة محاولات جدية للحصول على ترخيص اختيارى من صاحب البراءة نظير مقابل عادل ، وأنه أخفق فى ذلك .
3 - أن يكون لصاحب البراءة حق التظلم من القرار الصادر بمنح الترخيص الإجبارى للغير أمام اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون وذلك خلال ثلاثين يوما من تاريخ إخطاره بصدور هذا الترخيص ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية .
4 - أن يكون طالب الحصول على الترخيص الإجبارى ، أو من يصدر ، لصالحه قادرا على استغلال الاختراع بصفة جدية فى جمهورية مصر العربية .
5 - أن يلتزم المرخص له ترخيصا إجباريا باستخدام الاختراع فى النطاق وبالشروط وخلال المدة التى يحددها قرار منح هذا الترخيص الإجبارى .
فإذا انتهت مدة الترخيص الإجبارى دون تحقيق الغرض من هذا الاستخدام جاز لمكتب براءات الاختراع تجديد المدة .
6 - يقتصر استخدام الترخيص الإجبارى على طالبه ، ومع ذلك يجوز لمكتب براءات الاختراع منحه لغيره .
7 - عدم أحقية المرخص له ترخيصا إجباريا فى التنازل عنه للغير إلا مع المشروع أو مع الجزء المتعلق باستخدام الاختراع .
8 - أن يكون لصاحب البراءة الحق فى الحصول على تعويض عادل مقابل استغلال اختراعه ، وتراعى فى تقدير هذا التعويض القيمة الاقتصادية للاختراع .
ويكون لصاحب البراءة الحق فى التظلم من قرار تقدير التعويض أمام اللجنة المنصوص عليها فى المادة ( 36 ) ، وذلك خلال ثلاثين يوما من تاريخ إخطاره بالقرار ووفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
9 - أن ينقضى الترخيص الإجبارى بانتهاء مدته . ومع ذلك لمكتب براءات الاختراع أن يقرر إلغاء الترخيص الإجبارى قبل نهاية مدته إذا زالت الأسباب التى أدت إلى منحه ولم يكن مرجحا قيام هذه الأسباب مرة أخرى ، وتتبع فى ذلك الإجراءات التى تنص عليها اللائحة التنفيذية .
10 - أن يكون لصاحب الاختراع أن يطلب إنهاء الترخيص الإجبارى ، قبل نهاية المدة المحددة له ، وذلك إذا زالت الأسباب التى أدت إلى الحصول عليه ولم يعد مرجحا قيامها مرة أخرى .
11 - أن تراعى المصالح المشروعة للمرخص له عند إنهاء الترخيص الإجبارى قبل نهاية مدته .
12 - أن يكون لمكتب براءات الاختراع تعديل شروط الترخيص الإجبارى أو إلغاؤه سواء من تلقاء نفسه أو بناء على طلب كل ذى شأن ، وذلك إذا لم يقم المرخص له باستخدام الترخيص خلال سنتين من تاريخ منحه ، أو إذا أخل بالتزاماته المنصوص عليها فى الترخيص .$m239$,'3ae6a151ac58f7ec6a7c82527f6d7205',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(25,0,1,$m239$يجوز بقرار من الوزير المختص - بعد موافقة اللجنة الوزارية المشار إليها فى المادة ( 23 ) من هذا القانون - نزع ملكية براءة الاختراع لأسباب تتعلق بالأمن القومى ، وفى حالات الضرورة القصوى التى لا يكون فيها الترخيص الإجبارى كافيا لمواجهتها .
ويجوز أن يكون نزع الملكية مقصورا على نزع حق استغلال الاختراع لحاجات الدولة .
وفى جميع الأحوال يكون نزع الملكية مقابل تعويض عادل ، ويكون تقدير التعويض بواسطة اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ، ووفقا للقيمة الاقتصادية السائدة وقت إصدار قرار نزع الملكية .
وينشر قرار نزع الملكية فى جريدة براءات الاختراع ، ويكون الطعن فى قرار نزع الملكية وفى قرار اللجنة بتقدير التعويض أمام محكمة القضاء الإدارى ، وذلك خلال ستين يوما من تاريخ إخطار صاحب الشأن بالقرار بموجب خطاب مسجل موصى عليه مصحوبا بعلم الوصول وتفصل المحكمة فى هذا الطعن على وجه الاستعجال .$m239$,'189f0c6a6ca15245996d45ab2bb8e30e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(26,0,1,$m239$تنقضى الحقوق المترتبة على براءة الاختراع بما يسقطها فى الملك العام فى الأحوال الآتية :
1 - انقضاء مدة الحماية وفقا لنص المادة ( 9 ) من هذا القانون .
2 - تنازل صاحب براءة الاختراع عن حقوقه عليها دون الإخلال بحقوق الغير .
3 - صدور حكم بات ببطلان براءة الاختراع .
4 - الامتناع لمدة سنة من تاريخ الاستحقاق عن دفع الرسوم السنوية أو الغرامة التأخيرية ومقدارها ( 7 ٪ ) من هذه الرسوم ، بعد إخطاره بالدفع وفقا للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
5 - عدم استغلال الاختراع فى مصر فى السنتين التاليتين لمنح الترخيص الإجبارى وذلك بناء على طلب يتقدم به كل ذى شأن إلى مكتب براءات الاختراع .
6 - تعسف صاحب براءة الاختراع فى استعمال حقوقه فى الحالات التى لا يكون الترخيص الإجبارى فيها كافيا لتدارك ذلك التعسف .
ويعلن عن البراءة التى انقضت حقوق أصحابها عليها وفقا للأحكام السابقة ، بالنشر فى جريدة براءات الاختراع بالطريقة التى تحددها اللائحة التنفيذية .$m239$,'227fec0f383e4c2bd712bc9ef8621084',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(27,0,1,$m239$تختص محكمة القضاء الإدارى بنظر الدعاوى المتعلقة بالقرارات الصادرة بشأن براءات الاختراع .$m239$,'0553c83cbdcd22784b62e44a53176038',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(28,0,1,$m239$يجوز لمحكمة القضاء الإدارى أن تحكم بناء على طلب مكتب براءات الاختراع أو بناء على طلب ذى الشأن بإضافة أى بيان للسجل قد أغفل تدوينه أو بتعديل أى بيان وارد فيه غير مطابق للحقيقة أو بحذف أى بيان دون به بغير وجه حق .
كما يجوز لمكتب براءات الاختراع ولكل ذى شأن أن يطلب إلى المحكمة الحكم بإبطال البراءات التى تمنح مخالفة لأحكام المادتين ( 2 ) ، ( 3 ) من هذا القانون ، وتقوم الإدارة المذكورة بإلغاء هذه البراءات متى تقدم لها حكم بذلك حائز لقوة الشىء المقضى به .$m239$,'4b51f59e1d6f180a8b008d9d65c0720f',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(29,0,1,$m239$تمنح براءة نموذج المنفعة طبقا لأحكام هذا القانون عن كل إضافة تقنية جديدة فى بناء أو تكوين وسائل أو أدوات أو عدد أو أجزائها أو منتجات أو مستحضرات أو طرق إنتاج كل ما تقدم ، وغير ذلك مما يستخدم فى الاستعمال الجارى .
ولمقدم الطلب تحويله إلى طلب براءة اختراع ، كما يحق لطالب براءة الاختراع تحويل طلبه إلى طلب براءة لنموذج منفعة .
ويرتد القيد فى الحالتين إلى تاريخ تقديم الطلب الأصلى .
ولمكتب براءات الاختراع - من تلقاء نفسه - تحويل طلب براءة نموذج المنفعة إلى طلب براءة اختراع متى توافرت شروطه .$m239$,'337b19863e418e32713a21666188a16f',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(30,0,1,$m239$مدة حماية نموذج المنفعة سبع سنوات غير قابلة للتجديد تبدأ من تاريخ تقديم طلب براءة نموذج المنفعة إلى مكتب براءات الاختراع فى جمهورية مصر العربية .$m239$,'cae0af0824f8060f92202e7d46d45cb1',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(31,0,1,$m239$يستحق رسم عند تقديم طلب براءة نموذج المنفعة كما يستحق رسم سنوى يتدرج بالزيادة اعتبارا من بداية السنة الثانية وحتى انتهاء مدة البراءة .
وتحدد اللائحة التنفيذية لهذا القانون قيمة هذه الرسوم بما لا يجاوز ألف جنيه لكل طلب ، وكذلك قواعد تخفيضها وحالات الإعفاء منها .$m239$,'96bfcced727252099787c857ad86c3c5',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(32,0,1,$m239$مع عدم الإخلال بأحكام المادة ( 10 ) من هذا القانون ، يعاقب بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه :
1 - كل من قلد بهدف التداول التجارى موضوع اختراع أو نموذج منفعة منحت براءة عنه وفقا لأحكام هذا القانون .
2 - كل من باع أو عرض للبيع أو للتداول أو استورد أو حاز بقصد الاتجار منتجات مقلدة مع علمه بذلك ، متى كانت براءة الاختراع أو براءة نموذج المنفعة صادرة عنها أو عن طرق إنتاجها ونافذة فى جمهورية مصر العربية ،
3 - كل من وضع بغير حق على المنتجات أو الإعلانات أو العلامات التجارية أو أدوات التعبئة أو غير ذلك ، بيانات تؤدى إلى الاعتقاد بحصوله على براءة اختراع أو براءة نموذج منفعة .
وفى حالة العود تكون العقوبة الحبس مدة لا تزيد على سنتين والغرامة التى لا تقل عن أربعين ألف جنيه ولا تجاوز مائتى ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة الأشياء المقلدة محل الجريمة والأدوات التى استخدمت فى التقليد وينشر الحكم الصادر بالإدانة فى جريدة يومية واحدة أو أكثر على نفقة المحكوم عليه .$m239$,'0ffc7380d1424a9141e3d700cdd64c73',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(33,0,1,$m239$يجوز لصاحب براءة الاختراع أو نموذج المنفعة أن يطلب من رئيس المحكمة المختصة بحسب الأحوال إصدار أمر بإجراء تحفظى بشأن المنتجات أو البضائع المدعى بتقليدها للمنتج الصادر عنه البراءة وفقا للوصف التفصيلى الذى تم الإفصاح عنه فى وثيقة براءة الاختراع أو نموذج المنفعة ، ويصدر الأمر بالإجراءات التحفظية اللازمة لحفظ هذه المنتجات والبضائع على النحو الذى يضمن بقاءها بحالتها .
ويجوز أن يصدر الأمر المشار إليه قبل رفع الدعوى ويسقط بعدم رفعها خلال ثمانية أيام من تاريخ الصدور .$m239$,'5f976c54083439debba0112548967a17',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(34,0,1,$m239$يعتبر المنتج المطابق قد تم الحصول عليه وفقا للطريقة المشمولة بالبراءة إذا أثبت المدعى فى دعواه المدنية :
1 - أن المنتج المطابق قد تم الحصول عليه بالاستخدام المباشر للطريقة المشمولة بالبراءة .
2 - أو أنه قد بذل الجهد المعقول للكشف عن الطريقة التى استخدمت فى الإنتاج .
وفى هذه الحالة يجوز للمحكمة أن تأمر المدعى عليه بأن يثبت أن الطريقة التى استخدمها فى الحصول على المنتج المطابق تختلف عن الطريقة المشمولة بالبراءة والمملوكة للمدعى .
وعلى المحكمة أن تراعى فى اتخاذ إجراءات الإثبات حق المدعى عليه فى حماية أسراره الصناعية والتجارية .$m239$,'329445a78793896d18a0be32014a299e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(35,0,1,$m239$لرئيس المحكمة المختصة بأصل النزاع بناء على طلب كل ذى شأن وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة وفاء لما يقضى به من الغرامات أو التعويضات ، كما له أن يأمر بإتلاف الأشياء المتحفظ عليها عند الاقتضاء .$m239$,'fadeda3be254e3ba1dbb7487a93168ee',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(36,0,1,$m239$تشكل بقرار من الوزير المختص لجنة تختص بنظر التظلمات من القرارات التى يصدرها مكتب براءات الاختراع تطبيقا لأحكام هذا القانون برئاسة مستشار بمحاكم الاستئناف أو من فى درجته من أعضاء الهيئات القضائية وعضوية مستشار مساعد من مجلس الدولة وثلاثة من ذوى الخبرة .
ويكون التظلم أمام اللجنة مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز خمسمائة جنيه .
ويجب على اللجنة البت فى التظلم فى موعد غايته ستون يوما من تاريخ تقديم التظلم ، ويكون قرارها فى هذا الشأن نهائيا .
وفيما عدا طلبات الإلغاء المقترنة بطلب وقف التنفيذ لا يجوز قبول الدعوى أمام القضاء بشأن قرارات مكتب براءات الاختراع إلا بعد الفصل فى التظلم أو فوات ستين يوما من تاريخ تقديمه دون البت فيه .
وتنظم اللائحة التنفيذية لهذا القانون إجراءات عمل هذه اللجنة .$m239$,'6d0dc8c23d7eb5e20a86163bd84e00ef',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(37,0,1,$m239$يكون لمكتب براءات الاختراع ولذوى الشأن الطعن فى القرار الصادر من اللجنة المنصوص عليها فى المادة ( 36 ) من هذا القانون ، وذلك أمام محكمة القضاء الإدارى خلال ستين يوما من تاريخ إخطار المكتب به أو ذوى الشأن بموجب كتاب مسجل موصى عليه مصحوبا بعلم الوصول وتفصل المحكمة فى الطعن على وجه الاستعجال .$m239$,'bf0539155a2aae45f68456ba60764bca',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(38,0,1,$m239$إذا قدم طلب للحصول على براءة اختراع فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، جاز لمقدم الطلب أو لمن آلت إليه حقوقه خلال السنة التالية لتاريخ تقديم الطلب ، أن يتقدم إلى مكتب براءات الاختراع فى جمهورية مصر العربية بطلب مماثل عن ذات الموضوع وذلك وفقا للشروط والأوضاع المنصوص عليها فى هذا القانون ولائحته التنفيذية ، وفى هذه الحالة يعتد فى تحديد الأولوية بتاريخ تقديم الطلب الأول فى البلد الأجنبى .$m239$,'a37f19c51b132a4e4736ac2e4a8337c2',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(39,0,1,$m239$لا يجوز للعاملين بمكتب براءات الاختراع أن يقدموا بالذات أو بالواسطة طلبات للحصول على براءات إلا بعد مضى ثلاث سنوات على الأقل من تاريخ تركهم الخدمة بالمكتب .$m239$,'4a8185cdb5b0c54f644d9bbb1e02523c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(40,0,1,$m239$تسرى الأحكام الخاصة ببراءات الاختراع على كل ما لم يرد به نص خاص فى شأن براءات نماذج المنفعة .$m239$,'4d214f5ced7eab8d94f16f515a0bad6c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(41,0,1,$m239$تسرى أحكام هذا القانون على كل طلب تم تقديمه لمكتب براءات الاختراع ولم تصدر بشأنه براءة اختراع قبل تاريخ العمل بهذا القانون وللطالب أن يعدل طلبه بما يتفق وأحكام هذا القانون ،
وتسرى مدة الحماية المقررة بهذا القانون على براءات الاختراع التى لم تنته مدتها فى تاريخ العمل به بما يكمل مدة حمايتها إلى المدة الواردة بالمادة ( 9 ) من هذا القانون .$m239$,'51c8cc9bae7002fff1f43195604eb241',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(42,0,1,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الكتاب .$m239$,'dfb4027cbc42947a57f7bfe418a18ca0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(43,0,1,$m239$يتلقى مكتب براءات الاختراع طلبات براءات الاختراع الخاصة بالمنتجات الكيميائية الزراعية المتعلقة بالأغذية ، والمنتجات الكيميائية الصيدلية لحفظها هى والطلبات الخاصة بذات النوعية من المنتجات والتى قدمت اعتبارا من أول يناير 1995 وذلك لحين البدء فى فحصها اعتبارا من أول يناير سنة 2005 ميلادية .
وفى حالة منح البراءة المقررة للاختراعات المتعلقة بالمنتجات المنصوص عليها فى الفقرة السابقة ، تبدأ حمايتها اعتبارا من تاريخ المنح وذلك حتى نهاية المدة المنصوص عليها فى المادة ( 9 ) من هذا القانون وذلك اعتبارا من تاريخ تقديم الطلب .$m239$,'fc71ded74a74738a4b47b280228db2e3',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(44,0,1,$m239$مع مراعاة الميعاد المقرر لبدء الفحص فى طلبات براءات الاختراع المتعلقة بالمنتجات المنصوص عليها فى المادة ( 43 ) من هذا القانون يحق لطالب البراءة أن يطلب من السلطة الحكومية المختصة منحه حقوقا تسويقية استثنائية لمنتجه فى جمهورية مصر العربية ، وذلك بالشروط الآتية :
1 - أن يكون الطالب قد أودع طلبا لهذا المنتج بمكتب البراءات المصرى اعتبارا من أول يناير سنة 1995
2 - أن يكون المنتج ذاته قد نال براءة اختراع لحمايته فى دولة عضو فى منظمة التجارة العالمية بناء على طلب قدم فى تلك الدولة اعتبارا من أول يناير سنة 1995
3 - أن يكون الطالب قد حصل على موافقة بتداول هذا المنتج فى ذات الدولة التى نال فيها البراءة اعتبارا من أول يناير سنة 1995
4 - أن يكون الطالب قد حصل على موافقة من الوزارة المختصة بتداول هذا المنتج داخل جمهورية مصر العربية .
ويمنح مكتب براءات الاختراع المصرى شهادة حق التسويق الاستئثارى بعد موافقة لجنة وزارية تشكل لهذا الغرض بقرار من رئيس الوزراء .
ولا يمنح حق التسويق الاستئثارى إذا كان واضحا من ظاهر الأوراق التى تقدم إلى مكتب براءات الاختراع للحصول على شهادة حق التسويق الاستئثارى ، أن الطلب المودع بالمكتب للحصول على البراءة قد نشر عنه قبل سنة من تاريخ إيداع الطلب .
ويتمتع الطالب بالحقوق التسويقية الاستئثارية لمنتجه والتى توافق السلطة الحكومية المختصة على منحها له ، وذلك إلى أن يبت مكتب براءات الاختراع المصرى فى طلب الحصول على البراءة ، أو لمدة خمس سنوات تحسب من تاريخ الموافقة على منحه تلك الحقوق أى المدتين أقل .
ويلغى حق التسويق الاستئثارى السابق منحه بإلغاء القرار الصادر بالتداول من الوزارة المختصة أو إذا تعسف صاحب الحق فى استعمال حقه .$m239$,'9c7f97ba337055d292e395fa3b46b8ca',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(45,0,1,$m239$يقصد بالدائرة المتكاملة فى تطبيق أحكام هذا القانون كل منتج فى هيئته النهائية أو فى هيئته الوسيطة يتضمن مكونات - أحدها على الأقل يكون عنصرا نشطا - مثبتة على قطعة من مادة عازلة ، وتشكل مع بعض الوصلات أو كلها كيانا متكاملا يستهدف تحقيق وظيفة الكترونية محددة .
كما يقصد بالتصميم التخطيطى كل ترتيب ثلاثى الأبعاد معد لدائرة متكاملة بغرض التصنيع .$m239$,'8661a014d6bb4ec8ed3d5f60ecce7c60',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(46,0,1,$m239$يتمتع بالحماية طبقا لأحكام هذا القانون التصميم التخطيطى الجديد للدوائر المتكاملة .
ويعد التصميم التخطيطى جديدا متى كان نتاج جهد فكرى بذله صاحبه ، ولم يكن من بين المعارف العامة الشائعة لدى أرباب الفن الصناعى المعنى .
ومع ذلك يعتبر التصميم التخطيطى جديدا إذا كان اقتران مكوناته واتصالها ببعضها جديدا فى ذاته على الرغم من أن المكونات التى يتكون منها قد تقع ضمن المعارف العامة الشائعة لدى أرباب الفن الصناعى المعنى .$m239$,'5338afd73457572366f0a0802c7067a6',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(47,0,1,$m239$لا يتمتع بالحماية أى مفهوم أو طريقة أو نظام فنى أو معلومات مشفرة يمكن أن يشتمل عليها التصميم التخطيطى للدوائر المتكاملة .$m239$,'61dbd3c6bfb83607650d97334041a129',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(48,0,1,$m239$تكون مدة حماية التصميمات التخطيطية للدوائر المتكاملة عشر سنوات تبدأ من تاريخ تقديم طلب تسجيلها فى جمهورية مصر العربية ، أو من تاريخ أول استغلال تجارى له فى جمهورية مصر العربية أو فى الخارج أى التاريخين أسبق .
وتنقضى مدة حماية التصميمات التخطيطية فى جميع الأحوال بمرور خمس عشرة سنة من تاريخ إعداد التصميم .$m239$,'7e175f70f766361f3edc1f3eb831bd5b',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(49,0,1,$m239$يقدم طلب تسجيل التصميم التخطيطى من صاحب الحق فيه إلى مكتب براءات الاختراع ، ويجب أن يرفق بالطلب صورة أو رسم لهذا التصميم وعينة من كل دائرة متكاملة كانت موضع استغلال تجارى والمعلومات التى توضح الوظيفة الالكترونية للتصميم .
ويجوز للطالب أن يستبعد جزءا أو أكثر من التصميم إذا كانت الأجزاء المقدمة منه كافية لتحديد هذا التصميم وبيان وظيفته .
ويعد فى المكتب سجل لقيد طلبات التسجيل وفقا للشروط والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون ، ويستحق عن كل طلب رسم تحدده اللائحة بما لا يجاوز ألف جنيه .
ولا يقبل الطلب إذا قدم بعد انقضاء سنتين من تاريخ أول استغلال تجارى للتصميم من صاحب الحق فيه سواء فى مصر أو فى الخارج .$m239$,'45e47857955e1697c420e8f54dd989dc',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(50,0,1,$m239$لا يجوز بغير تصريح كتابى مسبق من صاحب الحق فى التصميم التخطيطى المحمى قيام أى شخص طبيعى أو اعتبارى بأى عمل من الأعمال التالية :
1 - نسخ التصميم التخطيطى بكامله أو أى جزء جديد منه سواء تم النسخ بإدماجه فى دائرة متكاملة أو بأى طريق آخر .
2 - استيراد التصميم التخطيطى أو بيعه أو توزيعه لأغراض التجارة سواء تم ذلك على وجه الانفراد أو كان مندمجا فى دائرة متكاملة أو كان أحد المكونات لسلعة .$m239$,'1470fa4f4fa16cdcc45f1b94a80e2d33',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(51,0,1,$m239$مع عدم الإخلال بأحكام الحماية المقررة فى هذا الباب ، يجوز لأى شخص طبيعى أو اعتبارى القيام بغير ترخيص من صاحب الحق بعمل أو أكثر مما يلى :
1 - النسخ أو الاستغلال التجارى الذى يشمل الاستيراد أو البيع أو التوزيع لدائرة متكاملة تحتوى على تصميم تخطيطى محمى أو لسلعة تدخل فى صنعها تلك الدائرة المتكاملة ، إذا وقع الفعل من شخص لا يعلم أو لم يكن متاحا له أن يعلم وقت الفعل أن تلك الدائرة المتكاملة أو السلعة تتضمن تصميما تخطيطيا محميا .
وفى هذه الحالة يجوز للحائز ، مقابل أداء تعويض عادل لصاحب الحق ، أن يتصرف فيما لديه من مخزون سلعى أو سلع أمر بشرائها ، وذلك بعد إخطاره من صاحب الحق بكتاب مسجل مصحوبا بعلم الوصول بأن الدائرة المتكاملة أو السلعة التى فى حوزته تتضمن تصميما تخطيطيا محميا .
2 - الاستخدام الشخصى أو لأغراض الاختبار أو الفحص أو التحليل أو التعليم أو التدريب أو البحث العلمى لتصميم تخطيطى محمى ، فإذا أسفر ذلك الاستخدام عن ابتكار تصميم تخطيطى جديد ، يكون للمبتكر الحق فى حمايته .
3 - ابتكار تصميم تخطيطى مطابق لتصميم تخطيطى آخر محمى وذلك نتيجة جهود مستقلة .
4 - استيراد تصميم تخطيطى محمى أو الدائرة المتكاملة التى تم إنتاجها باستخدام تصميم تخطيطى محمى سواء كانت هذه الدائرة منفردة أو مندمجة فى سلعة ، أو السلعة التى تحوى دائرة متكاملة تتضمن تصميما تخطيطيا محميا ، وذلك متى تم تداول أيها فى جمهورية مصر العربية أو فى الخارج .$m239$,'e8bf4c31b6c65c4dedf65047cc50c240',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(52,0,1,$m239$يجوز لمكتب براءات الاختراع أن يمنح للغير ترخيصا إجباريا باستخدام تصميم تخطيطى محمى وفقا لأحكام الترخيص الإجبارى لبراءات الاختراع والمنصوص عليها فى المادتين ( 23 ) ، ( 24 ) من هذا القانون .$m239$,'1bf3177ba3f8b6a8b02c13e01421877a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(53,0,1,$m239$يعاقب على مخالفة أحكام المادة ( 50 ) من هذا القانون بغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مائة ألف جنيه .
وفى حالة العود تكون العقوبة الحبس الذى لا تزيد مدته على سنتين والغرامة التى لا تقل عن أربعين ألف جنيه ولا تزيد على مائتى ألف جنيه .$m239$,'aaab8eb1d9421e9867b7455b411bd2e9',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(54,0,1,$m239$تسرى أحكام المواد ( 4 ) ، ( 33 ) ، ( 35 ) ، ( 42 ) على هذا الباب .$m239$,'75daa090a259859a545a279cf35de0f4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(55,0,1,$m239$تتمتع بالحماية طبقا لأحكام هذا القانون المعلومات غير المفصح عنها ، بشرط أن يتوافر فيها ما يأتى :
1 - أن تتصف بالسرية ، وذلك بأن تكون المعلومات فى مجموعها أو فى التكوين الذى يضم مفرداتها ليست معروفة أو غير متداولة بشكل عام لدى المشتغلين بالفن الصناعى الذى تقع المعلومات فى نطاقه .
2 - أن تستمد قيمتها التجارية من كونها سرية .
3 - أن تعتمد فى سريتها على ما يتخذه حائزها القانونى من إجراءات فعالة للحفاظ عليها .$m239$,'67949955329f0c9bbf588f443d21d4c8',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(56,0,1,$m239$تمتد الحماية التى تقررها أحكام هذا القانون إلى المعلومات غير المفصح عنها التى كانت ثمرة جهود كبيرة والتى تقدم إلى الجهات المختصة بناء على طلبها للسماح بتسويق المنتجات الكيميائية الصيدلية أو الزراعية ، التى تستخدم كيانات كيميائية جديدة ، لازمة للاختبارات الواجب إجراؤها للسماح بالتسويق .
وتلتزم الجهات المختصة التى تتلقى هذه المعلومات بحمايتها من الإفشاء والاستخدام التجارى غير المنصف وذلك من تاريخ تقديم المعلومات إليها وحتى زوال صفة السرية عنها ، أو لمدة لا تزيد عن خمس سنوات أى الفترتين أقل .
ولا يعتبر تعديا على حقوق صاحب هذه المعلومات ما تقوم به الجهات المختصة من الكشف عنها لضرورة تقتضيها حماية الجمهور .$m239$,'6c0173240fc2cb756eff2fbca682118d',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(57,0,1,$m239$يلتزم الحائز القانونى للمعلومات غير المفصح عنها باتخاذ الإجراءات الكفيلة بالمحافظة على هذه المعلومات لمنع تعرضها للتداول بمعرفة غير المختصين .
كما يلتزم بتنظيم تداول هذه المعلومات داخل المنشأة ، وقصره على الملتزمين قانونا ، بالحفاظ عليها ومنع تسريبها للغير .
ولا تنتفى مسئولية الحائز القانونى بتعدى الغير على هذه المعلومات إلا إذا أثبت أنه بذل فى الحفاظ عليها جهدا كافيا ومعقولا .
وتستمر صفة السرية للمعلومات وما يترتب عليها من حقوق فى منع الغير من التعدى عليها ، إذا ظلت معلومات غير مفصح عنها طبقا لحكم المادة ( 55 ) من هذا القانون .
وتقتصر حقوق الحائز القانونى للمعلومات غير المفصح عنها على منع الغير من التعدى عليها بأى من الأفعال التى تتعارض مع الممارسات التجارية الشريفة ، والمشار إليها فى المادة ( 58 ) من هذا القانون ، ويكون للحائز القانونى اللجوء إلى القضاء فى حالة ثبوت ارتكاب الغير لأى من هذه الأفعال .$m239$,'15aca207126b3c64f0a6a396f01b7b4b',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(58,0,1,$m239$تعد الأفعال الآتية ، على الأخص ، متعارضة مع الممارسات التجارية الشريفة ، وينطوى ارتكابها على منافسة غير مشروعة :
1 - رشوة العاملين فى الجهة التى تحوز المعلومات بغرض الحصول عليها .
2 - التحريض على إفشاء المعلومات من جانب العاملين إذا كانت تلك المعلومات قد وصلت إلى علمهم بحكم وظيفتهم .
3 - قيام أحد المتعاقدين فى « عقود سرية المعلومات » بإفشاء ما وصل إلى علمه منها .
4 - الحصول على المعلومات من أماكن حفظها بأية طريقة من الطرق غير المشروعة كالسرقة أو التجسس أو غيرها .
5 - الحصول على المعلومات باستعمال الطرق الاحتيالية .
6 - استخدام الغير للمعلومات التى وردت إليه نتيجة الحصول عليها بأى من الأفعال السابقة مع علمه بسريتها وبأنها متحصلة عن أى من هذه الأفعال .
ويعتبر تعديا على المعلومات غير المفصح عنها ما يترتب على الأفعال المشار إليها من كشف للمعلومات ، أو حيازتها ، أو استخدامها بمعرفة الغير الذى لم يرخص له الحائز القانونى بذلك .$m239$,'3ab2d0172bb91d460309a5912fbf43bd',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(59,0,1,$m239$لا تعد من قبيل الأفعال المتعارضة مع الممارسات التجارية الشريفة الأفعال الآتية :
1 - الحصول على المعلومات من المصادر العامة المتاحة كالمكتبات ومنها مكتبات براءات الاختراع والسجلات الحكومية المفتوحة والبحوث والدراسات والتقارير المنشورة .
2 - الحصول على المعلومات نتيجة بذل الجهود الذاتية والمستقلة التى تستهدف استخراج المعلومات من خلال الفحص والاختبار والتحليل للسلعة المتداولة فى السوق والتى تتجسد فيها المعلومات غير المفصح عنها .
3 - الحصول على المعلومات نتيجة جهود البحث العلمى والابتكار والاختراع والتطوير والتعديل والتحسين التى يبذلها المجتهدون مستقلين عن صاحب المعلومات غير المفصح عنها .
4 - حيازة واستعمال المعلومات المعروفة والمتاحة والتى يجرى تداولها فيما بين المشتغلين بالفن الصناعى الذى تقع المعلومات فى نطاقه .$m239$,'72d6c53fe7fa606559715adc95ce88d7',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(60,0,1,$m239$يحق لصاحب المعلومات غير المفصح عنها أو لخلفه أن يتنازل عنها للغير بعوض أو بغير عوض .$m239$,'19f401083c0fca8c87781b61a28418c6',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(61,0,1,$m239$مع عدم الإخلال بأية عقوبة أشد ينص عليها أى قانون آخر ، يعاقب كل من يقوم بوسيلة غير مشروعة بالكشف عن المعلومات المحمية طبقا لأحكام هذا القانون أو بحيازتها أو باستخدامها مع علمه بسريتها وبأنها متحصلة عن تلك الوسيلة ، بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على خمسين ألف جنيه .
وفى حالة العود تكون العقوبة الحبس مدة لا تزيد على سنتين والغرامة التى لا تقل عن خمسين ألف جنيه ولا تزيد على مائة ألف جنيه .$m239$,'93c484f0e892a49d4842b930869fcd26',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(62,0,1,$m239$تسرى أحكام المواد ( 4 ) ، ( 33 ) ، ( 35 ) ، ( 42 ) على هذا الباب .$m239$,'75daa090a259859a545a279cf35de0f4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(63,0,1,$m239$العلامة التجارية هى كل ما يميز منتجا سلعة كان أو خدمة عن غيره ، وتشمل على وجه الخصوص الأسماء المتخذة شكلا مميزا ، والإمضاءات ، والكلمات ، والحروف ، والأرقام ، والرسوم ، والرموز ، وعناوين المحال ، والدمغات ، والأختام ، والتصاوير ، والنقوش البارزة ، ومجموعة الألوان التى تتخذ شكلا خاصا ومميزا ، وكذلك أى خليط من هذه العناصر إذا كانت تستخدم أو يراد أن تستخدم إما فى تمييز منتجات عمل صناعى ، أو استغلال زراعى ، أو استغلال للغابات ، أو لمستخرجات الأرض ، أو أية بضاعة ، وإما للدلالة على مصدر المنتجات ، أو البضائع ، أو نوعها ، أو مرتبتها ، أو ضمانها ، أو طريقة تحضيرها وإما للدلالة على تأدية خدمة من الخدمات .
وفى جميع الأحوال يتعين أن تكون العلامة التجارية مما يدرك بالبصر .$m239$,'a8414db3a607ca370ea8b23c9be3687a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(64,0,1,$m239$تختص مصلحة التسجيل التجارى بتسجيل العلامات التجارية فى السجل الخاص بهذه العلامات وفقا لأحكام هذا القانون ولائحته التنفيذية وذلك مع مراعاة حكم المادتين ( 3 ، 4 ) من القرار بقانون رقم 115 لسنة 1958 فى المكاتبات واللافتات بوجوب استعمال اللغة العربية .$m239$,'0352727502ad6e4b5369996b78e5f019',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(65,0,1,$m239$يعتبر من قام بتسجيل العلامة مالكا لها متى اقترن ذلك باستعمالها خلال الخمس السنوات التالية للتسجيل ، ما لم يثبت أن أولوية الاستعمال كانت لغيره .
ويحق لمن كان أسبق إلى استعمال العلامة ممن سجلت باسمه الطعن ببطلان التسجيل خلال الخمس السنوات المذكورة .
ومع ذلك يجوز الطعن ببطلان تسجيل العلامة دون التقيد بأى مدة متى اقترن التسجيل بسوء نية .$m239$,'1ff5491a43ce1d46b28f4c5918878a1e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(66,0,1,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل الحق فى التقدم إلى مصلحة التسجيل فى جمهورية مصر العربية وما يترتب على ذلك من حقوق طبقا لأحكام هذا القانون بطلب تسجيل علامة تجارية .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بالحقوق المنصوص عليها فى هذا الباب ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'2cccd85e6b22df0caca6033225b7e4cd',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(67,0,1,$m239$لا يسجل كعلامة تجارية أو كعنصر منها ما يأتى :
1 - العلامات الخالية من أية صفة مميزة أو المكونة من عبارات أو بيانات ليست إلا التسمية التى يطلقها العرف على المنتجات أو الرسم أو الصور العادية لها .
2 - العلامات المخلة بالنظام العام أو الآداب العامة .
3 - الشعارات العامة والأعلام وغيرها من الرموز الخاصة بالدولة أو الدول الأخرى أو المنظمات الإقليمية أو الدولية ، وكذلك أى تقليد لها .
4 - العلامات المطابقة أو المشابهة للرموز ذات الصبغة الدينية .
5 - رموز الصليب الأحمر أو الهلال الأحمر أو غيرها من الرموز المشابهة وكذلك العلامات التى تكون تقليدا لها .
6 - صور الغير أو شعاراته ما لم يوافق على استعمالها .
7 - البيانات الخاصة بدرجات الشرف التى لا يثبت طالب التسجيل حصوله عليها .
8 - العلامات والمؤشرات الجغرافية التى من شأنها أو تضلل الجمهور أو تحدث لبسا لديه أو التى تتضمن بيانات كاذبة عن مصدر المنتجات من السلع أو الخدمات أو عن صفاتها الأخرى ، وكذلك العلامات التى تحتوى على بيان اسم تجارى وهمى مقلد أو مزور .$m239$,'afb1ac9f596aa2f29a35a6f00529701f',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(68,0,1,$m239$يكون لصاحب العلامة التجارية المشهورة عالميا وفى جمهورية مصر العربية حق التمتع بالحماية المقررة فى هذا القانون ولو لم تسجل فى جمهورية مصر العربية .
ويجب على المصلحة أن ترفض من تلقاء نفسها أى طلب لتسجيل علامة مطابقة لعلامة مشهورة يتضمن استخدام العلامة لتمييز منتجات تماثل المنتجات التى تستخدم العلامة المشهورة فى تمييزها ، ما لم يكن الطلب مقدما من صاحب العلامة المشهورة .
ويسرى الحكم المتقدم على طلبات التسجيل التى تنصب على منتجات لا تماثل المنتجات التى تستخدم العلامة المشهورة فى تمييزها إذا كانت العلامة المشهورة مسجلة فى إحدى الدول الأعضاء فى منظمة التجارة العالمية وفى جمهورية مصر العربية وكان استخدام العلامة على المنتجات غير المماثلة من شأنها أن يحمل الغير على الاعتقاد بوجود صلة بين صاحب العلامة المشهورة وتلك المنتجات ، وأن يؤدى هذا الاستخدام إلى إلحاق ضرر بصاحب العلامة المشهورة .$m239$,'cebb5af1e1222d9e4bdb3e0b2def99e1',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(69,0,1,$m239$تستخدم العلامة التجارية الجماعية لتمييز منتج ينتجه مجموعة من الأشخاص ينتمون إلى كيان معين ولو كان لا يملك بذاته منشأة صناعية أو تجارية .
ويقدم طلب تسجيل العلامة بواسطة ممثل هذا الكيان .$m239$,'ffa13bbb6e041018e32f2f5f6572f992',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(70,0,1,$m239$للوزير المختص - تحقيقا للمصلحة العامة - أن يرخص للأشخاص الطبيعيين أو الاعتباريين الذين يزاولون أعمال مراقبة المنتجات أو فحصها بتسجيل علامة تخصص للدلالة على إجراء المراقبة أو الفحص لتلك المنتجات وذلك فيما يتعلق بمصدرها أو عناصر تركيبها أو طريقة إنتاجها أو صفتها أو حقيقتها أو أية خاصية أخرى تميزها .
ولا يجوز التصرف فى تلك العلامة إلا بموجب ترخيص خاص من الوزير المختص .$m239$,'6d745efe16c0d1605b1f9f1d11dcfd23',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(71,0,1,$m239$يستنفد حق مالك العلامة فى منع الغير من استيراد أو استخدام أو بيع أو توزيع المنتجات التى تميزها هذه العلامة إذا قام بتسويق تلك المنتجات فى أية دولة أو رخص للغير بذلك .$m239$,'b866dfe817d28bcbe88ed9efc79de6ec',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(72,0,1,$m239$تمنح العلامة الموضوعة على منتجات معروضة فى المعارض الوطنية أو الدولية حماية مؤقتة ، ولا يترتب على تلك الحماية امتداد المدة المنصوص عليها فى المادة ( 75 ) من هذا القانون .
ويعين الوزير المختص هذه المعارض بموجب قرار يصدره وتحدد اللائحة التنفيذية لهذا القانون شروط وأوضاع وإجراءات منح تلك الحماية .$m239$,'0a4e8e853787ee60237a1a50a812a11e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(73,0,1,$m239$يقدم طلب تسجيل العلامة إلى مصلحة التسجيل التجارى وفقا للأوضاع وبالشروط التى تقررها اللائحة التنفيذية لهذا القانون ، وتحدد هذه اللائحة فئات الرسوم المستحقة على الطلب وسائر الإجراءات المتعلقة بالعلامة بما لا يجاوز فى مجموعه خمسة آلاف جنيه .$m239$,'993dd52baf748b746de27ee83efcf503',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(74,0,1,$m239$تسجل العلامة عن فئة أو نوعية واحدة أو أكثر من المنتجات التى ينتجها طالب التسجيل ، أو يعتزم إنتاجها وذلك وفقا للأوضاع والشروط التى تحددها اللائحة التنفيذية لهذا القانون .
ويقتصر استخدامها على الفئة أو الفئات أو نوعية المنتجات المسجلة عنها .
وتسرى أحكام المادة ( 91 ) من هذا القانون على الفئات التى لم تستخدم فى شأنها العلامة بصفة جدية .$m239$,'bebaeb9e3c746708054a718070c12250',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(75,0,1,$m239$إذا أودع طلب تسجيل علامة فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، جاز لمقدم الطلب أو لمن آلت إليه حقوقه - خلال الستة الأشهر التالية لتاريخ تقديم الطلب - أن يتقدم إلى المصلحة فى جمهورية مصر العربية بطلب مماثل يتعلق بذات العلامة ، وينصب على ذات المنتجات التى يشملها الطلب السابق ، وذلك كله وفقا للشروط والأوضاع المنصوص عليها فى هذا القانون ولائحته التنفيذية .
وفى هذه الحالة يعتد فى تحديد الأولوية بتاريخ تقديم الطلب الأول فى البلد الأجنبى .$m239$,'0ea1ae5bc4bc85d90b036e49c8984355',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(76,0,1,$m239$إذا طلب شخصان أو أكثر فى وقت واحد تسجيل ذات العلامة أو تسجيل علامات متشابهة عن فئة واحدة من المنتجات ، توقف إجراءات التسجيل إلى أن يقدم أحدهم تنازلا من منازعيه أو حكما واجب النفاذ صادرا لصالحه .$m239$,'b4bb65af23a3940de3134755d8c077d4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(77,0,1,$m239$يجوز لمصلحة التسجيل التجارى بقرار مسبب أن تكلف طالب التسجيل بإجراء التعديلات اللازمة على العلامة المطلوب تسجيلها لتحديدها وتوضيحها لتفادى التباسها بعلامة أخرى سبق تسجيلها أو تقديم طلب بذلك .
ويخطر الطالب بهذا القرار بموجب كتاب موصى عليه مصحوبا بعلم الوصول وذلك خلال ثلاثين يوما من تاريخ صدوره .
ويجوز للمصلحة أن ترفض الطلب إذا لم ينفذ الطالب ما كلفته به المصلحة من تعديلات خلال ستة أشهر من تاريخ الإخطار .$m239$,'5d58331ba6026acef29d1d1592c0afa1',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(78,0,1,$m239$يجوز للطالب أن يتظلم من قرار المصلحة المشار إليها فى المادة ( 77 ) من هذا القانون وذلك خلال ثلاثين يوما من تاريخ إخطاره به ، وتنظر التظلمات لجنة أو أكثر تشكل بقرار من الوزير المختص من ثلاثة أعضاء أحدهم من أعضاء مجلس الدولة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد تشكيل اللجنة وإجراءات تقديم التظلمات ونظرها والبت فيها .$m239$,'109ac2b7afd5f29e94709978fe47c4c5',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(79,0,1,$m239$دون إخلال بحق صاحب الشأن فى الطعن طبقا للقانون إذا أيدت اللجنة المشار إليها فى المادة السابقة القرار الصادر برفض طلب تسجيل العلامة لتشابهها مع علامة أخرى سبق تسجيلها عن منتجات واحدة أو عن فئة واحدة منها فلا يجوز تسجيل هذه العلامة للطالب إلا بناء على حكم قضائى واجب النفاذ .$m239$,'0fc6cf240866b6fbaa46fa402787cfee',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(80,0,1,$m239$يجب على المصلحة نشر قرار قبول طلب تسجيل العلامة فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية ، وذلك بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .
ويجوز لكل ذى شأن أن يعترض كتابة على تسجيل العلامة بإخطار يوجه إلى المصلحة متضمنا أسباب الاعتراض وذلك خلال ستين يوما من تاريخ النشر وفقا للأوضاع التى تحددها اللائحة التنفيذية لهذا القانون .
وعلى المصلحة أن ترسل صورة من إخطار الاعتراض إلى طالب التسجيل وذلك خلال ثلاثين يوما من تاريخ ورود الإخطار إليها .
وعلى طالب التسجيل أن يقدم للمصلحة ردا كتابيا مسببا على الاعتراض ، خلال ثلاثين يوما من تاريخ تسلمه الإخطار ، وإلا اعتبر متنازلا عن طلب التسجيل .
وتحدد اللائحة التنفيذية لهذا القانون القواعد والإجراءات المنظمة لذلك .$m239$,'1bbef4e0a7222038e4539abbc093a109',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(81,0,1,$m239$تصدر المصلحة قرارها فى الاعتراض مسببا إما بقبول التسجيل أو رفضه ، وذلك بعد سماع طرفى النزاع ، ويجوز لها أن تضمن قرارها بالقبول إلزام الطالب بتنفيذ ما تراه ضروريا من الاشتراطات لتسجيل العلامة .$m239$,'9e3e47473326efa853fd5a012463dc2a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(82,0,1,$m239$يجوز الطعن فى قرار المصلحة المشار إليه فى المادة ( 81 ) من هذا القانون أمام محكمة القضاء الإدارى المختصة وفقا للإجراءات والمواعيد التى ينص عليها قانون مجلس الدولة .$m239$,'792bd68e4fe6da7bb4cbcde7b60f3c89',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(83,0,1,$m239$يكون تسجيل العلامة بقرار من المصلحة ، وينشر هذا القرار فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .
ويبدأ أثر التسجيل من تاريخ تقديم الطلب .$m239$,'2deb4cb542e5b05fbe7d316f74dac77e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(84,0,1,$m239$تمنح المصلحة مالك العلامة المسجلة شهادة بالبيانات التى نشرت عنها فى الجريدة المشار إليها .$m239$,'611146b867ac7fac48a8760296159655',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(85,0,1,$m239$لمالك العلامة المسجلة أن يطلب من المصلحة كتابة إدخال أى تعديل على العلامة لا يمس بذاتيتها مساسا جوهريا ، وله كذلك طلب إدخال أى تعديل بالحذف دون الإضافة على بيان المنتجات الخاصة بالعلامة .
ويصدر القرار بقبول طلب التعديل أو رفضه وفقا للشروط المقررة لقرارات قبول طلبات التسجيل الأصلية .
وتسرى فى هذا الشأن الأحكام المقررة للاعتراض والتظلم والطعن والنشر بالنسبة لهذه القرارات .$m239$,'cadc786a3aaea5cfbf2e45a2410f4d61',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(86,0,1,$m239$لكل شخص أن يطلب الاطلاع على العلامات المسجلة أو الحصول على مستخرجات أو صور من السجل الخاص بتسجيلها وذلك وفقا للقواعد والإجراءات التى تقررها اللائحة التنفيذية لهذا القانون ومقابل رسم تحدده هذه اللائحة بما لا يجاوز مائة جنيه .$m239$,'a3734bb41e93ba864c19201b36c434a6',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(87,0,1,$m239$يجوز نقل ملكية العلامة أو تقرير أى حق عينى عليها أو الحجز عليها استقلالا عن المحل التجارى أو مشروع الاستغلال ، وذلك وفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'5611a10618d28d97968f449eea91e9df',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(88,0,1,$m239$يشمل نقل ملكية المحل التجارى أو مشروع الاستغلال العلامات المسجلة باسم المالك إذا كانت ذات ارتباط وثيق بالمحل التجارى أو بمشروع الاستغلال ما لم يتفق على غير ذلك .
وإذا لم يشمل نقل ملكية المحل التجارى أو مشروع الاستغلال العلامة التجارية كان لمالك العلامة استخدامها على ذات نوعية المنتجات أو الفئة أو الفئات المسجلة عنها ، ما لم يتفق على غير ذلك .$m239$,'bcfe176c4c6adb04d154a30cc898186d',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(89,0,1,$m239$لا يكون نقل ملكية العلامة أو تقرير حق الانتفاع عليها أو رهنها حجة على الغير إلا بعد التأشير بذلك فى السجل ونشره بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'b248e15df66be2346d7b501c9efd0144',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(90,0,1,$m239$مدة الحماية المترتبة على تسجيل العلامة عشر سنوات ، وتمتد لمدة أو لمدد مماثلة بناء على طلب صاحبها فى كل مرة خلال السنة الأخيرة من مدة الحماية ومقابل سداد الرسم المستحق على طلب التسجيل لأول مرة .
ويجوز بعد فوات تلك المدة بما لا يجاوز ستة شهور أن يتقدم صاحبها بطلب تجديد مدة الحماية ، وذلك مقابل أداء الرسم المقرر ورسم إضافى تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز خمسمائة جنيه وإلا قامت المصلحة بشطب العلامة .$m239$,'c0245f2cb3ed171106a55e0f7a8ef46f',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(91,0,1,$m239$يجوز للمحكمة المختصة بناء على طلب كل ذى شأن أن تقضى بشطب تسجيل العلامة بحكم قضائى واجب النفاذ ، إذا ثبت لديها أنها لم تستعمل بصفة جدية - دون مبرر تقدره - لمدة خمس سنوات متتالية .$m239$,'8aa172f3b683696ed7ddac8f38a4e753',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(92,0,1,$m239$يجوز إعادة تسجيل العلامة بعد شطبها - لصاحبها دون غيره - وذلك خلال ثلاث سنوات من تاريخ الشطب طبقا للأوضاع وبذات الإجراءات المقررة للتسجيل ومقابل سداد رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه .
ويجوز بعد فوات المدة المذكورة تسجيل العلامة لصاحبها ولغيره عن ذات المنتجات وذلك طبقا للأوضاع وبذات الإجراءات والرسوم المقررة للتسجيل أول مرة .
ومع ذلك إذا كان الشطب تنفيذا لحكم قضائى واجب النفاذ بعدم الأحقية فى تسجيل العلامة جاز تسجيلها لصالح الغير فور الشطب .$m239$,'1ae585a9c7f9dcd425bff2e1eec1a893',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(93,0,1,$m239$ينشر قرار مد التسجيل أو تجديده أو شطبه أو إعادته بعد الشطب فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'1277879f4c6609c49e22d1f27f2ea162',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(94,0,1,$m239$يكون للمصلحة ولكل ذى شأن فى غير الأحوال المنصوص عليها فى المادة ( 85 ) من هذا القانون اللجوء إلى المحكمة المختصة بطلب إضافة أى بيان للسجل أغفل تدوينه أو بحذف أو تعديل أى بيان دون فيه دون وجه حق أو كان غير مطابق للحقيقة .$m239$,'5bb6a3259f0047957a9c39bbde9576b3',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(95,0,1,$m239$لمالك العلامة أن يرخص لشخص أو أكثر طبيعى أو اعتبارى باستعمال العلامة على كل أو بعض المنتجات المسجلة عنها العلامة ، ولا يحول الترخيص للغير دون استعمال مالك العلامة لها ما لم يتفق على غير ذلك .
ولا يجوز لمالك العلامة إنهاء عقد الترخيص أو عدم تجديده إلا لسبب مشروع .$m239$,'c456f4c57b96b24d36c6fc4b4f106a30',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(96,0,1,$m239$يشترط لقيد عقد الترخيص فى سجل العلامات التجارية أن يكون موثقا أو مصدقا على صحة التوقيعات عليه . ولا يكون الترخيص نافذا فى حق الغير إلا بعد إجراء هذا القيد والنشر عنه بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'dc6bde6f964d8628f0929e9b9142d2ff',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(97,0,1,$m239$لا يجوز للمرخص له التنازل عن عقد الترخيص للغير إلا مع التنازل عن المحل التجارى أو مشروع الاستغلال الذى تستخدم العلامة فى تمييز منتجاته وذلك ما لم يتفق على خلافه .
ولا يكون رهنه أو تقرير حق الانتفاع عليه حجة قبل الغير إلا بعد قيده فى السجل والنشر عنه بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'6f7324b2dc77b7bf3fda76c742dd79b9',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(98,0,1,$m239$لا يجوز أن يتضمن عقد الترخيص أية شروط تقيد المرخص له بقيود غير ضرورية للحفاظ على الحقوق المترتبة على تسجيل العلامة .
ومع ذلك يجوز أن يتضمن عقد الترخيص الشروط التالية :
1 - تحديد مدة الترخيص باستعمال العلامة .
2 - الشروط المعقولة التى تكفل لمالك العلامة مراقبة جودة المنتجات التى تميزها العلامة موضوع الترخيص وبما لا يتعارض مع حرية المرخص له فى الإدارة والتشغيل .
3 - إلزام المرخص له بالامتناع عن أى عمل من شأنه أن يؤدى إلى الإقلال من شأن المنتجات التى تميزها العلامة .$m239$,'ae765cdb743ad93a90e324ebb9c442b7',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(99,0,1,$m239$لمالك العلامة أو المرخص له أن يطلب شطب قيد عقد الترخيص ، وتخطر المصلحة الطرف الآخر بهذا الطلب .
ويكون الشطب فى الحالات وبالإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'bf5834ac928b1a2b84bdda9a5bca1b15',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(100,0,1,$m239$يعتبر بيانا تجاريا فى نطاق تطبيق أحكام هذا القانون ، أى إيضاح يتعلق بصفة مباشرة أو غير مباشرة بما يأتى :
1 - عدد المنتجات أو مقدارها ، أو مقاسها ، أو كيلها ، أو طاقتها ، أو وزنها .
2 - الجهة أو البلد الذى صنعت أو أنتجت فيه المنتجات .
3 - طريقة صنع أو إنتاج المنتجات .
4 - العناصر والمكونات الداخلة فى تركيب المنتجات .
5 - اسم أو صفة الصانع أو المنتج .
6 - وجود براءات اختراع أو غيرها من حقوق الملكية الصناعية أو أية امتيازات أو جوائز أو مميزات تجارية أو صناعية .
7 - الاسم أو الشكل الذى تعرف به بعض المنتجات .$m239$,'2aa4735ee50bd88239270cbfaf2b6a72',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(101,0,1,$m239$يجب أن يكون البيان التجارى مطابقا للحقيقة من جميع الوجوه سواء أكان موضوعا على ذات المنتجات أو على الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلان أو غير ذلك مما يستعمل فى عرض المنتجات على الجمهور ، أو كان موضوعا على المحال أو المخازن أو بها أو على عناوينها .$m239$,'adc5c298024eb5841fe4c1f6d6c4475c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(102,0,1,$m239$لا يجوز ذكر ميداليات أو دبلومات أو جوائز أو درجات فخرية من أى نوع إلا بالنسبة للمنتجات التى تنطبق عليها هذه المميزات ، وبالنسبة للأشخاص والأسماء التجارية الذين اكتسبوها أو لمن آلت إليهم حقوقهم ، ويجب أن يشتمل ذلك على بيان صحيح بتاريخها ونوعها وجهة منحها والمناسبة التى منحت فيها .
ولا يجوز لمن اشترك مع آخرين فى عرض منتجات أن يستعمل لمنتجاته الخاصة المميزات التى منحت للمعروضات المشتركة ما لم يبين بطريقة واضحة مصدر تلك المميزات ونوعها .$m239$,'25b7967605e93ac01eae65cfb463bbbd',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(103,0,1,$m239$إذا كان مقدار المنتجات أو مقاسها أو كيلها أو طاقتها أو وزنها أو مصدرها أو العناصر الداخلة فى تركيبها من العوامل التى لها دخل فى تقدير قيمتها ، جاز بقرار من الوزير المختص منع بيع تلك المنتجات أو عرضها للبيع أو استيرادها ما لم تحمل هذه البيانات .
ويصدر قرار من الوزير المختص بتحديد الكيفية التى توضع بها هذه البيانات على المنتجات باللغة العربية ، وبالإجراءات التى يستعاض عنها بها عند الاقتضاء .$m239$,'5ddeaad4c0d5ef173f823f37f2fd660a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(104,0,1,$m239$المؤشرات الجغرافية هى التى تحدد منشأ سلعة ما فى منطقة أو جهة فى دولة عضو فى منظمة التجارة العالمية أو تعامل جمهورية مصر العربية معاملة المثل متى كانت النوعية أو السمعة أو السمات الأخرى لهذه السلعة والمؤثرة فى ترويجها راجعة بصورة أساسية إلى منشأها الجغرافى .
ويشترط لحماية هذه المؤشرات أن تكون قد اكتسبت الحماية فى بلد المنشأ .$m239$,'158144b65f6adfee41c76c75634c29ad',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(105,0,1,$m239$لا يجوز لأى شخص فى جهة ذات شهرة خاصة فى إنتاج سلعة ما أن يضع على المنتجات التى يتجر فيها مؤشرات جغرافية بطريقة تضلل الجمهور بأنها نشأت فى الجهة ذات الشهرة الخاصة .$m239$,'9d1b04df140b611cf8ad7b4eec4ede41',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(106,0,1,$m239$لا يجوز استخدام أية وسيلة فى تسمية أو عرض سلعة ما توحى بطريقة تضلل الجمهور بأنها نشأت فى منطقة جغرافية على خلاف المنشأ الحقيقى لها .$m239$,'f9dda70e08ea2105602d80d07edaa911',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(107,0,1,$m239$لا يجوز لمنتج سلعة فى جهة ذات شهرة خاصة فى إنتاجها أن يضع مؤشرا جغرافيا على ما ينتجه من سلع شبيهة فى مناطق أخرى يكون من شأنها أن توحى بأنها منتجة فى الجهة المشار إليها .$m239$,'c6fbd3d5093fbb632e92966b4637819c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(108,0,1,$m239$يجوز أن تطلق على بعض المنتجات أسماء جغرافية أصبحت تدل فى الاصطلاح التجارى بصورة أساسية على جنس المنتج دون المنشأ الجغرافى له .$m239$,'34b5a6a86ba48d7505c08cdceddf870a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(109,0,1,$m239$يشترط لتسجيل علامة تجارية تشتمل على مؤشر جغرافى أن يكون إنتاج السلعة بصفة مستمرة بمعرفة طالب التسجيل فى المنطقة الجغرافية ذات الشهرة الخاصة .$m239$,'e686803167f144168ded3a164853265f',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(110,0,1,$m239$لا يجوز تسجيل العلامة التجارية التى تشتمل على مؤشر جغرافى إذا كان استعمالها من شأنه أن يضلل الجمهور فيما يتعلق بالمنشأ الحقيقى للسلعة .$m239$,'0556504ca117a4ffee0bbbd59a2aadb1',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(111,0,1,$m239$يجوز تسجيل العلامة التجارية التى تشتمل على مؤشر جغرافى إذا كان الحق فى هذه العلامة قد اكتسب من خلال استعمالها بحسن نية قبل تاريخ العمل بهذا القانون أو قبل منح المؤشر الجغرافى الحماية فى بلد المنشأ .$m239$,'084ad0e869d795b07437b2d655ffefe7',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(112,0,1,$m239$يجوز لكل ذى مصلحة رفع الدعوى أمام المحكمة الابتدائية المختصة بالطرق المعتادة بطلب منع استخدام أى مؤشر جغرافى لم تتضمنه علامة تجارية مسجلة إذا كان من شأن هذا الاستخدام تضليل الجمهور بشأن المنشأ الحقيقى للسلعة .
وتكون المحكمة الابتدائية المختصة هى المحكمة التى يقع فى دائرتها مكان استخدام المؤشر الجغرافى .$m239$,'5fa522cded8a5ee0a76c3b239b35225a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(113,0,1,$m239$مع عدم الإخلال بأية عقوبة أشد فى أى قانون آخر ، يعاقب بالحبس مدة لا تقل عن شهرين وبغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه أو بإحدى هاتين العقوبتين :
1 - كل من زور علامة تجارية تم تسجيلها طبقا للقانون أو قلدها بطريقة تدعو إلى تضليل الجمهور .
2 - كل من استعمل بسوء قصد علامة تجارية مزورة أو مقلدة .
3 - كل من وضع بسوء قصد على منتجاته علامة تجارية مملوكة لغيره .
4 - كل من باع أو عرض للبيع أو التداول أو حاز بقصد البيع أو التداول منتجات عليها علامة تجارية مزورة أو مقلدة أو موضوعة بغير حق مع علمه بذلك .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن شهرين والغرامة التى لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة المنتجات محل الجريمة أو المبالغ أو الأشياء المتحصلة منها ، وكذلك الأدوات التى استخدمت فى ارتكابها .
ويجوز للمحكمة عند الحكم بالإدانة أن تقضى بغلق المنشأة التى استغلها المحكوم عليه فى ارتكاب الجريمة مدة لا تزيد على ستة أشهر ، ويكون الغلق وجوبيا فى حالة العود .$m239$,'5459a301c06370488fda8a4e6b62eef4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(114,0,1,$m239$مع عدم الإخلال بأية عقوبة أشد فى أى قانون آخر ، يعاقب بالحبس مدة لا تزيد على ستة أشهر وبغرامة لا تقل عن ألفى جنيه ولا تجاوز عشرة آلاف جنيه أو بإحدى هاتين العقوبتين :
1 - كل من وضع بيانا تجاريا غير مطابق للحقيقة على منتجاته أو محاله أو مخازنه أو بها أو على عناوينها أو على الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلام أو على غير ذلك مما يستعمل فى عرض المنتجات على الجمهور .
2 - كل من ذكر بغير حق على علاماته أو أوراقه التجارية بيانا يؤدى إلى الاعتقاد بحصول تسجيلها .
3 - كل من استعمل علامة غير مسجلة فى الأحوال المنصوص عليها فى الفقرات ( 2 ، 3 ، 5 ، 7 ، 8 ) من المادة ( 67 ) من هذا القانون .
4 - كل من ذكر ميداليات أو دبلومات أو جوائز أو درجات فخرية من أى نوع كان على منتجات لا تتعلق بها أو على أشخاص أو أسماء تجارية لم يكتسبوها .
5 - كل من اشترك مع آخرين فى عرض منتجات واستعمل لمنتجاته الخاصة المميزات التى منحت للمعروضات المشتركة ما لم يبين بطريقة واضحة مصدر تلك المميزات ونوعها .
6 - كل من وضع على السلع التى يتجر بها - فى جهة ذات شهرة خاصة فى إنتاج سلعة معينة - مؤشرات جغرافية بطريقة تضلل الجمهور بأنها نشأت فى هذه الجهة .
7 - كل من استخدم أية وسيلة فى تسمية أو عرض سلعة ما توحى بطريقة تضلل الجمهور بأنها نشأت فى منطقة جغرافية ذات شهرة خاصة على خلاف المنشأ الحقيقى لها .
8 - كل منتج سلعة فى جهة ذات شهرة خاصة فى إنتاجها وضع مؤشرا جغرافيا على ما ينتجه من سلع شبيهة فى مناطق أخرى يكون من شأنها أن توحى بأنها منتجة فى الجهة المشار إليها .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن شهر والغرامة التى لا تقل عن أربعة آلاف جنيه ولا تجاوز عشرين ألف جنيه .$m239$,'3f1cc4b7f38991d8ae5f28bebc1bc56e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(115,0,1,$m239$لرئيس المحكمة المختصة بأصل النزاع بناء على طلب كل ذى شأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة وعلى وجه الخصوص :
1 - إثبات واقعة الاعتداء على الحق محل الحماية .
2 - إجراء حصر ووصف تفصيلى للآلات والأدوات التى تستخدم أو تكون قد استخدمت فى ارتكاب الجريمة والمنتجات أو البضائع أو عناوين المحال أو الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلان أو غير ذلك مما تكون قد وضعت عليه العلامة أو البيان أو المؤشر الجغرافى موضوع الجريمة ، وكذلك البضائع المستوردة من الخارج إثر ورودها .
3 - توقيع الحجز على الأشياء المذكورة فى البند ( 2 ) .
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة المختصة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'7430444a44417a44a015496e863ce09a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(116,0,1,$m239$يجوز لمن صدر ضده الأمر أن يتظلم منه إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدوره أو إعلانه له حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا .$m239$,'59d66e3b82313a84eeef3db9017fdfde',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(117,0,1,$m239$يجوز للمحكمة فى أية دعوى مدنية أو جنائية أن تحكم ببيع الأشياء المحجوزة أو التى تحجز فيما بعد واستنزال ثمنها من التعويضات أو الغرامات أو الأمر بالتصرف فيها بأية طريقة أخرى تراها المحكمة مناسبة .
وتأمر المحكمة بإتلاف العلامات المخالفة ، ويجوز لها - عند الاقتضاء - الأمر بإتلاف المنتجات أو البضائع أو عناوين المحال أو الأغلفة أو الفواتير أو المكاتبات أو وسائل الإعلان أو غير ذلك مما يحمل تلك العلامة أو يحمل بيانات أو مؤشرات جغرافية بالمخالفة لأحكام هذا الكتاب ، وكذلك إتلاف الآلات والأدوات التى استعملت بصفة خاصة فى ارتكاب الجريمة .
ويجوز للمحكمة أيضا أن تأمر بنشر الحكم فى جريدة واحدة أو أكثر على نفقة المحكوم عليه .
وللمحكمة أن تأمر بكل أو ببعض ما سبق حتى فى حالة الحكم بالبراءة .$m239$,'05aaa322f7f70f2f10fdac45427c30ee',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(118,0,1,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الباب .$m239$,'7b313a3096de9ba76b500f5910c2c6b0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(119,0,1,$m239$يعتبر تصميما أو نموذجا صناعيا كل ترتيب للخطوط وكل شكل مجسم ، بألوان أو بغير ألوان إذا اتخذ مظهرا مميزا يتسم بالجدة وكان قابلا للاستخدام الصناعى .$m239$,'68dcead76fdd5498ea79305b114c9cc9',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(120,0,1,$m239$يفقد التصميم أو النموذج الصناعى وصف الجدة إذا :
1 - تم عرضه على الجمهور أو وصفه أو عرض استخداماته قبل تاريخ إيداع طلب تسجيله .
ومع ذلك لا يفقد التصميم أو النموذج الصناعى وصف الجدة إذا كان هذا العرض أو الوصف قد تم بعد تقديم طلب تسجيله فى دولة عضو فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل أو كان العرض فى أحد المعارض الوطنية أو الدولية أو نشر عن التصميم أو النموذج الصناعى فى أحد المؤتمرات أو إحدى الدوريات العلمية ، وذلك كله خلال فترة لا تجاوز ستة أشهر سابقة على تاريخ إيداع طلب التسجيل فى جمهورية مصر العربية .
2 - اشتمل على اختلافات غير جوهرية بالنسبة لتصميم أو نموذج صناعى سابق أو خصص لنوع آخر من المنتجات غير ما خصص له التصميم أو النموذج السابق تسجيله .$m239$,'f7d674f9c495a93635608ee797743d42',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(121,0,1,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل الحق فى التقدم بطلب تسجيل تصميم أو نموذج صناعى لمصلحة التسجيل التجارى ، وما يترتب على ذلك من حقوق طبقا لأحكام هذا القانون .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بالحقوق المنصوص عليها فى هذا الباب ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'75d6ef19940f8481aff4588df6123493',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(122,0,1,$m239$تختص مصلحة التسجيل التجارى بتسجيل التصميمات والنماذج الصناعية فى السجل المعد لذلك .
ويجوز أن يشتمل الطلب على عدد من التصميمات والنماذج لا يجاوز الخمسين بشرط أن تكون فى مجموعها وحدة متجانسة .
وتحدد اللائحة التنفيذية لهذا القانون إجراءات طلب التسجيل وعدد التصميمات والنماذج التى يمكن أن يشتمل عليها الطلب الواحد وإجراءات الفحص والإشهار عن قرار المصلحة بقبول الطلب وإجراءات المعارضة فيه وغيرها من الإجراءات اللازمة ، وكذلك الرسوم المقررة على هذه الطلبات وتجديدها وعلى كافة الإجراءات المتعلقة بها على ألا تجاوز هذه الرسوم فى مجموعها ثلاثة آلاف جنيه .$m239$,'6505861c16b4e834c00b3182c27cd7eb',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(123,0,1,$m239$لا يجوز للقائمين بالعمل فى مصلحة التسجيل التجارى أن يقدموا بالذات أو بالواسطة طلبات تسجيل لتصميمات أو نماذج صناعية إلا بعد مضى ثلاث سنوات على الأقل من تاريخ تركهم الخدمة .$m239$,'d87b3c6970e22bfbe6c0b7bd84c2026e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(124,0,1,$m239$لا يجوز تسجيل أى تصميم أو نموذج صناعى من التصميمات والنماذج الصناعية الآتية :
1 - التصميم أو النموذج الذى تستلزمه عادة الاعتبارات الفنية أو الوظيفية للمنتج .
2 - التصميم أو النموذج الذى يتضمن شعارات أو رموزا دينية أو أختاما أو أعلاما خاصة بجمهورية مصر العربية أو بالدول الأجنبية أو الذى ينشأ عن استخدامه إخلال بالنظام العام أو الآداب العامة .
3 - التصميم أو النموذج الذى يتطابق أو يتماثل أو يتشابه مع علامة تجارية مسجلة أو علامة مشهورة .
وعلى المصلحة فى جميع أحوال رفض طلب التسجيل إخطار الطالب بقرار الرفض مسببا ، وذلك خلال ثلاثين يوما من تاريخ صدوره بموجب كتاب موصى عليه مصحوبا بعلم الوصول .
ويجوز التظلم من هذا القرار فى ميعاد لا يجاوز ثلاثين يوما من تاريخ الإخطار به .
وتنظر التظلم لجنة تشكل بقرار من الوزير المختص من ثلاثة أحدهم من أعضاء مجلس الدولة ، وللجنة أن تستعين بمن تراه من ذوى الخبرة .
وتنظم اللائحة التنفيذية لهذا القانون إجراءات عمل هذه اللجنة وتحدد الرسم المقرر للتظلم بما لا يجاوز خمسمائة جنيه .
وتصدر اللجنة قرارها مسببا خلال تسعين يوما من تاريخ تقديم التظلم .
ويكون الطعن على قرار اللجنة أمام محكمة القضاء الإدارى خلال ثلاثين يوما من تاريخ الإعلان به .$m239$,'dccda1d2fcc1abbfe708de23b69b2301',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(125,0,1,$m239$للمصلحة أن تكلف طالب التسجيل بإجراء التعديلات أو الاستيفاءات التى تراها إعمالا لأحكام المادة ( 124 ) على النحو الذى تبينه اللائحة التنفيذية لهذا القانون ، فإذا لم يقم الطالب بهذا الإجراء عد متنازلا عن طلبه .
وللطالب أن يتظلم من قرار المصلحة بشأن هذا التكليف أمام اللجنة المنصوص عليها فى المادة ( 124 ) وذلك خلال ثلاثين يوما من تاريخ إخطاره بالقرار ووفقا للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
ويجوز للطالب من تلقاء نفسه أن يتقدم للمصلحة بطلب بإجراء التعديلات أو الاستيفاءات المشار إليها وذلك بالكيفية التى تحددها اللائحة التنفيذية لهذا القانون .$m239$,'d283fe4ba8f0c5452de4fd1d57405121',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(126,0,1,$m239$مدة الحماية المترتبة على تسجيل التصميم أو النموذج الصناعى عشر سنوات تبدأ من تاريخ تقديم طلب التسجيل فى جمهورية مصر العربية .
وتجدد الحماية لمدة خمس سنوات أخرى إذا قدم مالك التصميم أو النموذج طلبا بالتجديد فى خلال السنة الأخيرة من المدة ، وذلك وفقا للأوضاع المنصوص عليها فى اللائحة التنفيذية لهذا القانون .
ومع ذلك يحق للمالك أن يقدم طلبا بالتجديد خلال الثلاثة الأشهر التالية لتاريخ انتهاء مدة الحماية وإلا قامت المصلحة بشطب التسجيل من تلقاء نفسها .$m239$,'83982670e93162523f49f625da4c025c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(127,0,1,$m239$يترتب على تسجيل التصميم أو النموذج الصناعى حق صاحبه فى منع الغير من صنع أو بيع أو استيراد المنتجات المتخذة شكل هذا التصميم أو النموذج أو تتضمنه .
ويستنفد الحق فى منع الغير من استيراد أو بيع أو توزيع المنتجات المشار إليها إذا قام صاحبه بتسويق تلك المنتجات فى أية دولة أو رخص للغير بذلك .
ولا يعتبر اعتداء على هذا الحق ما يقوم به الغير من استخدام للتصميم أو النموذج الصناعى المحمى من الأعمال الآتية :
1 - الأعمال المتصلة بأغراض البحث العلمى .
2 - أغراض التعليم أو التدريب .
3 - الأنشطة غير التجارية .
4 - تصنيع أو بيع أجزاء من المنتجات المشار إليها ، وذلك بقصد إصلاحها مقابل أداء تعويض عادل .
5 - الاستخدامات الأخرى التى لا تتعارض بشكل غير معقول مع الاستغلال العادى للتصميم أو النموذج الصناعى المحمى ولا تضر بصورة غير معقولة بالمصالح المشروعة لصاحبه مع مراعاة المصالح المشروعة للغير .$m239$,'2f2265314ebecb1dbeb742472fa514a6',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(128,0,1,$m239$يجوز نقل ملكية التصميم أو النموذج الصناعى كله أو بعضه بعوض أو بغير عوض ، كما يجوز رهنه أو تقرير حق الانتفاع عليه .
ومع عدم الإخلال بالأحكام الخاصة ببيع المحال التجارية ورهنها لا تنتقل ملكية التصميم أو النموذج الصناعى ولا يكون رهنه أو تقرير حق الانتفاع عليه حجة على الغير إلا من تاريخ التأشير بذلك فى سجل التصميمات والنماذج الصناعية .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات اللازمة لتنفيذ ذلك .$m239$,'f3e44d3a84086007c7a4b7693fcfa519',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(129,0,1,$m239$يجوز لمصلحة التسجيل التجارى لدواعى المصلحة العامة وبعد موافقة لجنة وزارية تشكل بقرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص أن تصدر قرارا مسببا بمنح الغير ترخيصا إجباريا غير استئثارى باستخدام التصميم أو النموذج الصناعى المحمى وذلك مقابل تعويض عادل . وتحدد اللائحة التنفيذية لهذا القانون شروط وأوضاع وإجراءات منح هذا الترخيص .$m239$,'61a69305c1ff88759cc89fc6a5948961',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(130,0,1,$m239$تنشر المصلحة قرارات التسجيل والتجديد والشطب فى جريدة العلامات التجارية والتصميمات والنماذج الصناعية مشفوعة بصورة من التصميم أو النموذج الصناعى بحسب الأحوال ، وذلك وفقا للأوضاع المنصوص عليها فى اللائحة التنفيذية لهذا القانون .
وتسرى أحكام المواد 80 ، 81 ، 82 ، 83 على هذا الباب .$m239$,'ee93699de0cac53232123df799b9f88b',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(131,0,1,$m239$لكل شخص أن يطلب الاطلاع على التصميم أو النموذج الصناعى المسجل أو الحصول على مستخرجات أو صور من السجل الخاص بتسجيله وذلك وفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون ومقابل رسم تحدده هذه اللائحة بما لا يجاوز مائة جنيه .$m239$,'6a40e3d57d64da74673679d799cf7f98',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(132,0,1,$m239$تتمتع بحماية مؤقتة التصميمات أو النماذج الصناعية التى تتوافر فيها شروط التسجيل والتى تعرض فى المعارض الوطنية أو الدولية التى يصدر بتحديدها قرار من الوزير المختص .
وتحدد اللائحة التنفيذية لهذا القانون شروط وأوضاع وإجراءات منح تلك الحماية .$m239$,'faf52cd8b427f1fdf11b52108dccb525',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(133,0,1,$m239$للمصلحة ولكل ذى شأن أن يرفع الدعوى إلى محكمة القضاء الإدارى بطلب شطب تسجيل التصميم أو النموذج الصناعى الذى تم بدون وجه حق ، وتقوم المصلحة بشطب التسجيل متى قدم لها حكم واجب النفاذ بذلك .$m239$,'c29581a2df98bb58715e31046620b6de',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(134,0,1,$m239$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر يعاقب بغرامة لا تقل عن أربعة آلاف جنيه ولا تجاوز عشرة آلاف جنيه :
1 - كل من قلد تصميما أو نموذجا صناعيا محميا تم تسجيله وفقا لأحكام هذا القانون .
2 - كل من صنع أو باع أو عرض للبيع أو حاز بقصد الاتجار أو التداول منتجات تتخذ تصميما أو نموذجا صناعيا مقلدا مع علمه بذلك .
3 - كل من وضع بغير حق على منتجات أو إعلانات أو علامات تجارية أو أدوات معينة أو غيرها بيانات تؤدى إلى الاعتقاد بتسجيله تصميما أو نموذجا صناعيا .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن شهر والغرامة التى لا تقل عن ثمانية آلاف جنيه ولا تجاوز عشرين ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة التصميم أو النموذج الصناعى المضبوط والمنتجات محل الجريمة والأدوات التى استخدمت فى ارتكابها وبنشر الحكم الصادر بالإدانة فى جريدة واحدة أو أكثر على نفقة المحكوم عليه .$m239$,'18662fea65aabcbebe72a337f290ee77',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(135,0,1,$m239$لرئيس المحكمة المختصة بأصل النزاع وبناء على طلب كل ذى شأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة ، وعلى وجه الخصوص :
1 - إثبات واقعة الاعتداء على الحق محل الحماية .
2 - إجراء حصر ووصف تفصيلى للمنتجات المخالفة والأدوات التى استخدمت أو تستخدم فى ارتكاب الجريمة .
3 - توقيع الحجز على الأشياء المذكورة فى البند ( 2 )
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة المختصة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'3c4f44814d0844fb36b071f94a648246',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(136,0,1,$m239$يجوز لمن صدر ضده الأمر أن يتظلم منه إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدوره أو إعلانه له على حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا .$m239$,'ba1b9de69f9fc36e8d35d248b5ab2702',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(137,0,1,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الباب .$m239$,'7b313a3096de9ba76b500f5910c2c6b0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(138,0,1,$m239$فى تطبيق أحكام هذا القانون ، يكون للمصطلحات التالية المعنى الوارد قرين كل منها :
1 - المصنف : كل عمل مبتكر أدبى أو فنى أو علمى أيا كان نوعه أو طريقة التعبير عنه أو أهميته أو الغرض من تصنيفه .
2 - الابتكار : الطابع الإبداعى الذى يسبغ الأصالة على المصنف .
3 - المؤلف : الشخص الذى يبتكر المصنف ، ويعد مؤلفا للمصنف من يذكر اسمه عليه أو ينسب إليه عند نشره باعتباره مؤلفا له ما لم يقم الدليل على غير ذلك .
ويعتبر مؤلفا للمصنف من ينشره بغير اسمه أو باسم مستعار بشرط ألا يقوم شك فى معرفة حقيقة شخصه ، فإذا قام الشك اعتبر ناشر أو منتج المصنف سواء أكان شخصا طبيعيا أم اعتباريا ممثلا للمؤلف فى مباشرة حقوقه إلى أن يتم التعرف على حقيقة شخص المؤلف .
4 - المصنف الجماعى : المصنف الذى يضعه أكثر من مؤلف بتوجيه شخص طبيعى أو اعتبارى يتكفل بنشره باسمه وتحت إدارته ، ويندمج عمل المؤلفين فيه فى الهدف العام الذى قصد إليه هذا الشخص بحيث يستحيل فصل عمل كل مؤلف وتمييزه على حدة .
5 - المصنف المشترك : المصنف الذى لا يندرج ضمن المصنفات الجماعية ، ويشترك فى وضعه أكثر من شخص سواء أمكن فصل نصيب كل منهم فيه أو لم يمكن .
6 - المصنف المشتق : المصنف الذى يستمد أصله من مصنف سابق الوجود كالترجمات والتوزيعات الموسيقية وتجميعات المصنفات بما فى ذلك قواعد البيانات المقروءة سواء من الحاسب أو من غيره ، ومجموعات التعبير الفلكلورى ما دامت مبتكرة من حيث ترتيب أو اختيار محتوياتها .
7 - الفلكلور الوطنى : كل تعبير يتمثل فى عناصر متميزة تعكس التراث الشعبى التقليدى الذى نشأ أو استمر فى جمهورية مصر العربية ، وبوجه خاص التعبيرات الآتية :
( أ ) التعبيرات الشفوية مثل : الحكايات والأحاجى والألغاز والأشعار الشعبية وغيرها من المأثورات .
( ب ) التعبيرات الموسيقية مثل : الأغانى الشعبية المصحوبة بموسيقى .
( جـ ) التعبيرات الحركية مثل : الرقصات الشعبية والمسرحيات والأشكال الفنية والطقوس .
( د ) التعبيرات الملموسة مثل : منتجات الفن الشعبى التشكيلى وبوجه خاص الرسومات بالخطوط والألوان ، والحفر ، والنحت ، والخزف ، والطين والمنتجات المصنوعة من الخشب أو ما يرد عليه من تطعيمات تشكيلية مختلفة أو الموزاييك أو المعدن أو الجواهر ، والحقائب المنسوجة يدويا وأشغال الإبرة والمنسوجات والسجاد والملبوسات .
الآلات الموسيقية .
الأشكال المعمارية .
8 - الملك العام : الملك الذى تؤول إليه جميع المصنفات المستبعدة من الحماية بداية أو التى تنقضى مدة حماية الحقوق المالية عليها طبقا لأحكام هذا الكتاب .
9 - النسخ : استحداث صورة أو أكثر مطابقة للأصل من مصنف أو تسجيل صوتى بأية طريقة أو فى أى شكل بما فى ذلك التخزين الالكترونى الدائم أو الوقتى للمصنف أو للتسجيل الصوتى .
10 - النشر : أى عمل من شأنه إتاحة المصنف أو التسجيل الصوتى أو البرنامج الإذاعى أو فنانى الأداء للجمهور أو بأى طريقة من الطرق .
وتكون إتاحة المصنف للجمهور بموافقة المؤلف أو مالك حقوقه ، أما التسجيلات الصوتية أو البرامج الإذاعية أو الأداءات فتكون إتاحتها للجمهور بموافقة منتجها أو خلفه .
11 - منتج المصنف السمعى أو السمعى البصرى : الشخص الطبيعى أو الاعتبارى الذى يبادر إلى إنجاز المصنف السمعى أو المصنف السمعى البصرى ويضطلع بمسئولية هذا الإنجاز .
12 - فنانو الأداء : الأشخاص الذين يمثلون أو يغنون أو يلقون أو ينشدون أو يعزفون أو يرقصون فى مصنفات أدبية أو فنية محمية طبقا لأحكام هذا القانون أو آلت إلى الملك العام ، أو يؤدون فيها بصورة أو بأخرى ، بما فى ذلك التعبيرات الفلكلورية .
13 - منتج التسجيلات الصوتية : الشخص الطبيعى أو الاعتبارى الذى يسجل لأول مرة مصنفا تسجيلا صوتيا أو أداء لأحد فنانى الأداء ، وذلك دون تثبيت الأصوات على الصورة فى إطار إعداد مصنف سمعى بصرى .
14 - الإذاعة : البث السمعى أو السمعى البصرى للمصنف أو للأداء أو للتسجيل الصوتى أو لتسجيل المصنف أو الأداء وذلك إلى الجمهور بطريقة لاسلكية ، ويعد كذلك البث عبر التوابع الصناعية .
15 - الأداء العلنى : أى عمل من شأنه إتاحة المصنف بأى صورة من الصور للجمهور مثل التمثيل أو الإلقاء أو العزف أو البث بحيث يتصل الجمهور بالمصنف عن طريق الأداء أو التسجيل الصوتى أو المرئى أو المسموع اتصالا مباشرا .
16 - التوصيل العلنى : البث السلكى أو اللاسلكى لصور أو أصوات أو لصور وأصوات لمصنف ، أو أداء أو تسجيل صوتى ، أو بث إذاعى بحيث يمكن التلقى عن طريق البث وحده لغير أفراد العائلة والأصدقاء المقربين ، فى أى مكان مختلف عن المكان الذى يبدأ منه البث . وبغض النظر عن الزمان أو المكان الذى يتم فيه التلقى ، بما فى ذلك أى زمان أو مكان يختاره المتلقى منفردا عبر جهاز الحاسب أو أى وسيلة أخرى .
17 - هيئة الإذاعة : كل شخص أو جهة منوط بها أو مسئولة عن البث الإذاعى اللاسلكى السمعى أو السمعى البصرى .
18 - الوزير المختص : وزير الثقافة ، ويكون وزير الإعلام هو المختص بالنسبة لهيئات الإذاعة ، ويكون وزير الاتصالات والمعلومات هو المختص بالنسبة إلى برامج الحاسب وقواعد البيانات .
19 - الوزارة المختصة : وزارة الثقافة ، وتكون وزارة الإعلام هى المختصة بالنسبة لهيئات الإذاعة ، وتكون وزارة الاتصالات والمعلومات هى المختصة بالنسبة إلى برامج الحاسب وقواعد البيانات .$m239$,'a1082ab09f8f26ebbdf4a8ab5a0dba7d',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(139,0,1,$m239$تشمل الحماية المقررة لحقوق المؤلف والحقوق المجاورة لها المصريين والأجانب من الأشخاص الطبيعيين والاعتباريين الذين ينتمون إلى إحدى الدول الأعضاء فى منظمة التجارة العالمية ومن فى حكمهم .
ويعتبر فى حكم رعايا الدول الأعضاء :
( أ ) بالنسبة لحق المؤلف :
1 - المؤلفون الذين تنشر مصنفاتهم لأول مرة إحدى الدول الأعضاء فى المنظمة ، أو تنشر فى إحدى الدول غير الأعضاء وإحدى الدول الأعضاء فى آن واحد . ويعتبر المصنف منشورا فى آن واحد فى عدة دول إذا ظهر فى دولتين أو أكثر خلال ثلاثين يوما من تاريخ نشره لأول مرة .
ولا يعد نشرا تمثيل مصنف مسرحى أو مصنف مسرحى موسيقى أو سينمائى وأداء مصنف موسيقى والقراءة العلنية لمصنف أدبى والنقل السلكى أو إذاعة المصنفات الأدبية والفنية وعرض مصنف فنى وتنفيذ مصنف معمارى .
2 - منتجو ومؤلفو المصنفات السينمائية التى يكون مقر منتجها أو محل إقامته فى إحدى الدول الأعضاء فى تلك المنظمة .
3 - مؤلفو المصنفات المعمارية المقامة فى إحدى الدول الأعضاء أو المصنفات الفنية الأخرى الداخلة فى مبنى أو منشأة أخرى كائنة فى إحدى الدول الأعضاء .
( ب ) بالنسبة للحقوق المجاورة لحق المؤلف :
1 - فنانو الأداء إذا توافر أى شرط من الشروط التالية :
( أ ) إذا تم الأداء فى دولة عضو فى منظمة التجارة العالمية .
( ب ) إذا تم تفريغ الأداء فى تسجيلات صوتية ينتمى منتجها لدولة عضو فى منظمة التجارة العالمية ، أو تم التثبيت الأول للصوت فى إقليم دولة عضو فى المنظمة .
( جـ ) إذا تم بث الأداء عن طريق هيئة إذاعة يقع مقرها فى دولة عضو فى منظمة التجارة العالمية ، وأن يكون البرنامج الإذاعى قد تم بثه من جهاز إرسال يقع أيضا فى دولة عضو .
2 - منتجو التسجيلات الصوتية إذا كان التثبيت الأول للصوت قد تم فى دولة عضو فى المنظمة .
3 - هيئات الإذاعة إذا كان مقر هيئة الإذاعة كائنا فى إقليم دولة عضو فى منظمة التجارة العالمية ، وأن يكون البرنامج الإذاعى قد تم بثه من جهاز إرسال يقع أيضا فى إقليم دولة عضو فى المنظمة .
ويستفيد مواطنو جميع الدول الأعضاء فى منظمة التجارة العالمية من أى ميزة أو أفضلية أو امتياز أو حصانة يمنحها أى قانون آخر لرعايا أى دولة فيما يتعلق بحقوق الملكية الفكرية طبقا لهذا القانون ، ما لم تكن هذه الميزة أو الأفضلية أو الحصانة نابعة من :
( أ ) اتفاقيات المساعدة القضائية أو اتفاقيات إنفاذ القوانين ذات الصبغة العامة .
( ب ) الاتفاقيات المتعلقة بحقوق حماية الملكية الفكرية والتى أصبحت سارية قبل أول يناير سنة 1995$m239$,'25f7f3c031ec24ec01930361b072d0b2',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(140,0,1,$m239$تتمتع بحماية هذا القانون حقوق المؤلفين على مصنفاتهم الأدبية والفنية ، وبوجه خاص المصنفات الآتية :
1 - الكتب ، والكتيبات ، والمقالات والنشرات وغيرها من المصنفات المكتوبة .
2 - برامج الحاسب الآلى .
3 - قواعد البيانات سواء كانت مقروءة من الحاسب الآلى أو من غيره .
4 - المحاضرات ، والخطب ، والمواعظ ، وأية مصنفات شفوية أخرى إذا كانت مسجلة .
5 - المصنفات التمثيلية والتمثيليات الموسيقية والتمثيل الصامت ( البانتوميم ) .
6 - المصنفات الموسيقية المقترنة بالألفاظ أو غير المقترنة بها .
7 - المصنفات السمعية البصرية .
8 - مصنفات العمارة .
9 - مصنفات الرسم بالخطوط أو بالألوان ، والنحت ، والطباعة على الحجر ، وعلى الأقمشة وأية مصنفات مماثلة فى مجال الفنون الجميلة .
10 - المصنفات الفوتوغرافية وما يماثلها .
11 - مصنفات الفن التطبيقى والتشكيلى .
12 - الصور التوضيحية ، والخرائط الجغرافية والرسومات التخطيطية ( الاسكتشات ) والمصنفات الثلاثية الأبعاد المتعلقة بالجغرافيا أو الطبوغرافيا أو التصميمات المعمارية .
13 - المصنفات المشتقة ، وذلك دون الإخلال بالحماية المقررة للمصنفات التى اشتقت منها .
وتشمل الحماية عنوان المصنف إذا كان مبتكرا .$m239$,'8cc2ca29f9e1865d7eef9cae28a49f77',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(141,0,1,$m239$لا تشمل الحماية مجرد الأفكار والإجراءات وأساليب العمل وطرق التشغيل والمفاهيم والمبادىء والاكتشافات والبيانات ، ولو كان معبرا عنها أو موصوفة أو موضحة أو مدرجة فى مصنف .
كذلك لا تشمل ما يلى :
أولا - الوثائق الرسمية ، أيا كانت لغتها الأصلية أو اللغة المنقولة إليها ، مثل نصوص القوانين ، واللوائح ، والقرارات ، والاتفاقيات الدولية ، والأحكام القضائية ، وأحكام المحكمين ، والقرارات الصادرة من اللجان الإدارية ذات الاختصاص القضائى .
ثانيا - أخبار الحوادث والوقائع الجارية التى تكون مجرد أخبار صحفية .
ومع ذلك تتمتع مجموعات ما تقدم بالحماية إذا تميز جمعها بالابتكار فى الترتيب والعرض أو بأى مجهود شخصى جدير بالحماية .$m239$,'acd03b3e50857df0dc2f980bb7c630b5',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(142,0,1,$m239$يعتبر الفلكلور الوطنى ملكا عاما للشعب ، وتباشر الوزارة المختصة عليه حقوق المؤلف الأدبية والمالية وتعمل على حمايته ودعمه .$m239$,'f294e187834f363365250f4e04c4c323',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(143,0,1,$m239$يتمتع المؤلف وخلفه العام - على المصنف - بحقوق أدبية أبدية غير قابلة للتقادم أو للتنازل عنها ، وتشمل هذه الحقوق ما يلى :
أولا - الحق فى إتاحة المصنف للجمهور لأول مرة .
ثانيا - الحق فى نسبة المصنف إلى مؤلفه .
ثالثا - الحق فى منع تعديل المصنف تعديلا يعتبره المؤلف تشويها أو تحريفا له ، ولا يعد التعديل فى مجال الترجمة اعتداء إلا إذا أغفل المترجم الإشارة إلى مواطن الحذف أو التغيير أو أساء بعمله لسمعة المؤلف ومكانته .$m239$,'e019530588f641d9500f280df6faabc4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(144,0,1,$m239$للمؤلف وحده - إذا طرأت أسباب جدية - أن يطلب من المحكمة الابتدائية الحكم بمنع طرح مصنفه للتداول أو بسحبه من التداول أو بإدخال تعديلات جوهرية عليه برغم تصرفه فى حقوق الاستغلال المالى ، ويلزم المؤلف فى هذه الحالة أن يعوض مقدما من آلت إليه حقوق الاستغلال المالى تعويضا عادلا يدفع فى غضون أجل تحدده المحكمة وإلا زال كل أثر للحكم .$m239$,'8609384c57cf7f7893b89cf09afb52ee',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(145,0,1,$m239$يقع باطلا بطلانا مطلقا كل تصرف يرد على أى من الحقوق الأدبية المنصوص عليها فى المادتين ( 143 ) ، ( 144 ) من هذا القانون .$m239$,'6b38d35165c0b3ae7d63d73676ffc224',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(146,0,1,$m239$تباشر الوزارة المختصة ، الحقوق الأدبية المنصوص عليها فى المادتين ( 143 ) و ( 144 ) من هذا الكتاب ، فى حالة عدم وجود وارث أو موصى له ، وذلك بعد انقضاء مدة حماية الحقوق المالية المقررة فيه .$m239$,'f45ea30b7376f5d6866cc43aacda2e1a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(147,0,1,$m239$يتمتع المؤلف وخلفه العام من بعده ، بحق استئثارى فى الترخيص أو المنع لأى استغلال لمصنفه بأى وجه من الوجوه وبخاصة عن طريق النسخ أو البث الإذاعى أو إعادة البث الإذاعى أو الأداء العلنى أو التوصيل العلنى ، أو الترجمة أو التحوير أو التأجير أو الإعارة أو الإتاحة للجمهور ، بما فى ذلك إتاحته عبر أجهزة الحاسب الآلى أو من خلال شبكات الإنترنت أو شبكات المعلومات أو شبكات الاتصالات وغيرها من الوسائل .
ولا ينطبق الحق الاستئثارى فى التأجير على برامج الحاسب الآلى إذا لم تكن هى المحل الأساسى للتأجير ، ولا على تأجير المصنفات السمعية البصرية متى كان لا يؤدى إلى انتشار نسخها على نحو يلحق ضررا ماديا بصاحب الحق الاستئثارى المشار إليه .
كما يتمتع المؤلف وخلفه من بعده بالحق فى تتبع أعمال التصرف فى النسخة الأصلية لمصنفه ، والذى يخوله الحصول على نسبة مئوية معينة لا تجاوز عشرة فى المائة من الزيادة التى تحققت من كل عملية تصرف فى هذه النسخة .
ويستنفد حق المؤلف فى منع الغير من استيراد أو استخدام أو بيع أو توزيع مصنفه المحمى وفقا لأحكام هذا القانون إذا قام باستغلاله وتسويقه فى أية دولة أو رخص للغير بذلك .$m239$,'3e6a63682f61440fa1dde3168ce18cc7',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(148,0,1,$m239$تنتهى حماية حق المؤلف وحق من ترجم مصنفه إلى لغة أجنبية أخرى فى ترجمة ذلك المصنف إلى اللغة العربية إذا لم يباشر المؤلف أو المترجم هذا الحق بنفسه أو بواسطة غيره فى مدى ثلاث سنوات من تاريخ أول نشر للمصنف الأصلى أو المترجم .$m239$,'db31dbbeac9545ae7caa96f6f562a7df',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(149,0,1,$m239$للمؤلف أن ينقل إلى الغير كل أو بعض حقوقه المالية المبينة فى هذا القانون .
ويشترط لانعقاد التصرف أن يكون مكتوبا وأن يحدد فيه صراحة وبالتفصيل كل حق على حدة يكون محلا للتصرف مع بيان مداه والغرض منه ومدة الاستغلال ومكانه .
ويكون المؤلف مالكا لكل ما لم يتنازل عنه صراحة من حقوق مالية ، ولا يعد ترخيصه باستغلال أحد هذه الحقوق ترخيصا منه باستغلال أى حق مالى آخر يتمتع به على المصنف نفسه .
ومع عدم الإخلال بحقوق المؤلف الأدبية المنصوص عليها فى هذا القانون ، يمتنع عليه القيام بأى عمل من شأنه تعطيل استغلال الحق محل التصرف .$m239$,'5feeb0717e51233e27d89b7405355573',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(150,0,1,$m239$للمؤلف أن يتقاضى المقابل النقدى أو العينى الذى يراه عادلا نظير نقل حق أو أكثر من حقوق الاستغلال المالى لمصنفه إلى الغير ، على أساس مشاركة نسبية فى الإيراد الناتج من الاستغلال ، كما يجوز له التعاقد على أساس مبلغ جزافى أو بالجمع بين الأساسين .$m239$,'21c32af80560ef53c394c2e1dd0210c2',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(151,0,1,$m239$إذا تبين أن الاتفاق المشار إليه فى المادة ( 150 ) من هذا القانون مجحف بحقوق المؤلف أو أصبح كذلك ، لظروف طرأت بعد التعاقد ، يكون للمؤلف أو خلفه أن يلجأ إلى المحكمة الابتدائية بطلب إعادة النظر فى قيمة المقابل المتفق عليه مع مراعاة حقوق المتعاقد معه وعدم الإضرار به .$m239$,'5cfe24ae6e7a8dd910f830fc945847ac',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(152,0,1,$m239$لا يترتب على تصرف المؤلف فى النسخة الأصلية من مصنفه ، أيا كان نوع هذا التصرف ، نقل حقوقه المالية .
ومع ذلك لا يجوز إلزام المتصرف إليه بأن يمكن المؤلف من نسخ أو نقل أو عرض النسخة الأصلية ، وذلك كله ما لم يتفق على غير ذلك .$m239$,'d2db9faf0e8449f531fd0d566c5679be',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(153,0,1,$m239$يقع باطلا بطلانا مطلقا كل تصرف للمؤلف فى مجموع إنتاجه الفكرى المستقبلى .$m239$,'20a0e594f19a7ca0244fb9c32541efb4',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(154,0,1,$m239$يجوز الحجز على الحقوق المالية للمؤلفين على المنشور أو المتاح للتداول من مصنفاتهم . ولا يجوز الحجز على المصنفات التى يتوفى صاحبها قبل نشرها ما لم يثبت أن إرادته كانت قد انصرفت إلى نشرها قبل وفاته .$m239$,'d15e498565dc3094ceabbe49ab4a1bcd',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(155,0,1,$m239$يتمتع فنانو الأداء وخلفهم العام بحق أدبى أبدى لا يقبل التنازل عنه أو التقادم يخولهم ما يلى :
1 - الحق فى نسبة الأداء الحى أو المسجل إلى فنانى الأداء ، على النحو الذى أبدعوه عليه .
2 - الحق فى منع أى تغيير أو تحريف أو تشويه فى أدائهم .
وتباشر الوزارة المختصة هذا الحق الأدبى فى حالة عدم وجود وارث أو موصى له وذلك بعد انقضاء مدة حماية الحقوق المالية المنصوص عليها فى هذا القانون .$m239$,'b489b070ee53d1434bdd03cb58403bf7',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(156,0,1,$m239$يتمتع فنانو الأداء بالحقوق المالية الاستئثارية الآتية :
1 - توصيل أدائهم إلى الجمهور والترخيص بالإتاحة العلنية أو التأجير أو الإعارة للتسجيل الأصلى للأداء أو لنسخ منه .
2 - منع أى استغلال لأدائهم ، بأية طريقة من الطرق ، بغير ترخيص كتابى مسبق منهم ، ويعد استغلالا محظورا بوجه خاص تسجيل هذا الأداء الحى على دعامة أو تأجيرها بهدف الحصول على عائد تجارى مباشر أو غير مباشر أو البث الإذاعى لها إلى الجمهور .
3 - تأجير أو إعارة الأداء الأصلى أو نسخ منه لتحقيق غرض تجارى مباشر أو غير مباشر ، بغض النظر عن ملكية الأصل أو النسخ المؤجرة .
4 - الإتاحة العلنية لأداء مسجل عبر الإذاعة أو أجهزة الحاسب الآلى أو غيرها من الوسائل ، وذلك بما يحقق تلقيه على وجه الانفراد فى أى زمان أو مكان .
ولا يسرى حكم هذه المادة على تسجيل فنانى الأداء لأدائهم ضمن تسجيل سمعى بصرى ما لم يتفق على غير ذلك .$m239$,'e87c9110e15f6c293d52c044e7555544',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(157,0,1,$m239$يتمتع منتجو التسجيلات الصوتية بالحقوق المالية الاستئثارية الآتية :
1 - منع أى استغلال لتسجيلاتهم بأية طريقة من الطرق بغير ترخيص كتابى مسبق منهم ، ويعد بوجه خاص استغلالا محظورا فى هذا المعنى نسخها أو تأجيرها أو البث الإذاعى لها أو إتاحتها عبر أجهزة الحاسب الآلى أو غيرها من الوسائل .
2 - الإتاحة العلنية لتسجيل صوتى بوسائل سلكية أو لاسلكية أو عبر أجهزة الحاسب الآلى أو غيرها من الوسائل .$m239$,'bcfe973ff2b0ca6b95de98238f5f7738',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(158,0,1,$m239$تتمتع هيئات الإذاعة بالحقوق المالية الاستئثارية الآتية :
1 - منح الترخيص باستغلال تسجيلاتها .
2 - منع أى توصيل لتسجيلها التليفزيونى لبرامجها إلى الجمهور بغير ترخيص كتابى مسبق منها ، ويعد بوجه خاص استغلالا محظورا تسجيل هذه البرامج أو عمل نسخ منها أو بيعها أو تأجيرها أو إعادة بثها أو توزيعها أو نقلها إلى الجمهور بأية وسيلة كانت بما فى ذلك الإزالة أو الإتلاف لأية حماية تقنية لهذه البرامج كالتشفير أو غيره .$m239$,'fc8b55e08acf84f08fde82b78de14d3d',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(159,0,1,$m239$تنطبق الأحكام الخاصة بتنازل المؤلف عن حقوقه المالية وفقا لهذا القانون على أصحاب الحقوق المجاورة .
ومع عدم الإخلال بما نص عليه فى هذا القانون من حقوق استئثارية لفنانى الأداء وهيئات الإذاعة لا يكون لهؤلاء إلا حق الحصول على مقابل مالى عادل لمرة واحدة نظير الاستخدام المباشر أو غير المباشر للبرامج المنشورة فى الأغراض التجارية للإذاعة أو التوصيل إلى الجمهور ما لم يتفق على غير ذلك .$m239$,'1b055b568eb41a1ffd9bbeacea5ba0dd',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(160,0,1,$m239$تحمى الحقوق المالية للمؤلف المنصوص عليها فى هذا القانون مدة حياته ولمدة خمسين سنة تبدأ من تاريخ وفاة المؤلف .$m239$,'0f944608b7eff6a84dc8924aae54d1ed',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(161,0,1,$m239$تحمى الحقوق المالية لمؤلفى المصنفات المشتركة مدة حياتهم جميعا ولمدة خمسين سنة تبدأ من وفاة آخر من بقى حيا منهم .$m239$,'14de60a948f9bdaa10d2dba837e921ae',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(162,0,1,$m239$تحمى الحقوق المالية لمؤلفى المصنفات الجماعية - باستثناء مؤلفى مصنفات الفن التطبيقى - مدة خمسين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد . وذلك إذا كان مالك حقوق المؤلف شخصا اعتباريا ، أما إذا كان مالك هذه الحقوق شخصا طبيعيا فتكون مدة الحماية طبقا للقاعدة المنصوص عليها فى المادتين ( 160 ) ، ( 161 ) من هذا القانون .
وتنقضى الحقوق المالية على المصنفات التى تنشر لأول مرة بعد وفاة مؤلفها بمضى خمسين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد .$m239$,'9c9930ec8da504572a80aa29406f8223',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(163,0,1,$m239$تحمى الحقوق المالية على المصنفات التى تنشر بدون اسم مؤلفها أو باسم مستعار لمدة خمسين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد ، فإذا كان مؤلفها شخصا معروفا ومحددا أو كشف مؤلفها عن شخصه فتكون مدة الحماية طبقا للقاعدة المنصوص عليها فى المادة ( 160 ) من هذا القانون .$m239$,'2e5cd20114e9afab2df2bc5dc723e932',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(164,0,1,$m239$تنقضى الحقوق المالية لمؤلفى مصنفات الفن التطبيقى بانقضاء خمس وعشرين سنة تبدأ من تاريخ نشرها أو إتاحتها للجمهور لأول مرة أيهما أبعد .$m239$,'71d409a18da9b8fb94d963e7c183bea0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(165,0,1,$m239$فى الأحوال التى تحسب فيها مدة الحماية من تاريخ النشر أو الإتاحة للجمهور لأول مرة ، يتخذ تاريخ أول نشر أو أول إتاحة للجمهور أيهما أبعد مبدأ لحساب المدة ، بغض النظر عن إعادة النشر أو إعادة الإتاحة للجمهور إلا إذا أدخل المؤلف على مصنفه عند الإعادة تعديلات جوهرية بحيث يمكن اعتباره مصنفا جديدا .
فإذا كان المصنف يتكون من عدة أجزاء أو مجلدات نشرت منفصلة وعلى فترات ، فيعتبر كل جزء أو مجلد مصنفا مستقلا عند حساب مدة الحماية .$m239$,'dfc1740a3579792aeb1b4cd15cde782d',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(166,0,1,$m239$يتمتع فنانو الأداء بحق مالى استئثارى فى مجال أدائهم ، على النحو المبين فى المادة ( 156 ) من هذا القانون وذلك لمدة خمسين سنة تبدأ من تاريخ الأداء أو التسجيل على حسب الأحوال .$m239$,'17197d02c977e37a36e14b65d7c169b1',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(167,0,1,$m239$يتمتع منتجو التسجيلات الصوتية بحق مالى استئثارى فى مجال استغلال تسجيلاتهم ، على النحو المبين فى المادة ( 157 ) ، وذلك لمدة خمسين سنة تبدأ من تاريخ التسجيل أو النشر أيهما أبعد ، وذلك فى الحدود المنصوص عليها فى هذا القانون .$m239$,'c4ae9a6071d761ad4870a721d4be1298',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(168,0,1,$m239$تتمتع هيئات البث الإذاعى ، بحق مالى استئثارى يخول لها استغلال برامجها لمدة عشرين سنة تبدأ من التاريخ الذى تم فيها أول بث لهذه البرامج .$m239$,'06832d7cccc8dd4ff1bf56e930d150fb',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(169,0,1,$m239$لهيئات البث الإذاعى ، الحق فى إذاعة المصنفات التى تؤدى فى أى مكان عام . وتلتزم هذه الهيئات بإذاعة اسم المؤلف وعنوان المصنف وبسداد مقابل عادل نقدى أو عينى للمؤلف . كما تلتزم بسداد أى تعويض آخر إذا كان لذلك مقتضى .$m239$,'9d1a7f4b065a82e3bbec999039521a74',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(170,0,1,$m239$يجوز لأى شخص أن يطلب من الوزارة المختصة منحه ترخيصا شخصيا للنسخ أو الترجمة أو بهما معا لأى مصنف محمى طبقا لأحكام هذا القانون ، وذلك دون إذن المؤلف وللأغراض المبينة فى الفقرة التالية نظير سداد تعويض عادل للمؤلف أو خلفه ، وبشرط ألا يتعارض هذا الترخيص مع الاستغلال العادى للمصنف ، أو يلحق ضررا غير مبرر بالمصالح المشروعة للمؤلف أو لأصحاب حق المؤلف .
ويكون إصدار الترخيص بقرار مسبب يحدد فيه النطاق الزمانى والمكانى له ولأغراض الوفاء باحتياجات التعليم بكافة أنواعه ومستوياته .
وتحدد اللائحة التنفيذية لهذا القانون حالات وشروط منح الترخيص وفئات الرسم المستحق بما لا يجاوز ألف جنيه عن كل مصنف .$m239$,'0f5e5474ab8c9ab42751f1272c90e27b',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(171,0,1,$m239$مع عدم الإخلال بحقوق المؤلف الأدبية طبقا لأحكام هذا القانون ، ليس للمؤلف بعد نشر مصنفه أن يمنع الغير من القيام بأى عمل من الأعمال الآتية :
أولا - أداء المصنف فى اجتماعات داخل إطار عائلى أو بطلاب داخل المنشأة التعليمية مادام ذلك يتم بدون تحصيل مقابل مالى مباشر أو غير مباشر .
ثانيا - عمل نسخة وحيدة من المصنف لاستعمال الناسخ الشخصى المحض وبشرط ألا يخل هذا النسخ بالاستغلال العادى للمصنف أو يلحق ضررا غير مبرر بالمصالح المشروعة للمؤلف أو لأصحاب حق المؤلف . ومع ذلك يكون للمؤلف أو خلفه بعد نشر مصنفه أن يمنع الغير من القيام بدون إذنه بأى من الأعمال الآتية :
- نسخ أو تصوير مصنفات الفنون الجميلة أو التطبيقية أو التشكيلية مالم تكن فى مكان عام أو المصنفات المعمارية .
- نسخ أو تصوير كل أو جزء جوهرى لنوتة مصنف موسيقى .
- نسخ أو تصوير كل أو جزء جوهرى لقاعدة بيانات أو برامج حاسب آلى .
ثالثا - عمل نسخة وحيدة من برنامج الحاسب الآلى بمعرفة الحائز الشرعى له بغرض الحفظ أو الإحلال عند فقد النسخة الأصلية أو تلفها أو عدم صلاحيتها للاستخدام ، أو الاقتباس من البرنامج وإن جاوز هذا الاقتباس القدر الضرورى لاستخدام هذا البرنامج ما دام فى حدود الغرض المرخص به ويجب إتلاف النسخة الأصلية أو المقتبسة بمجرد زوال سند الحائز ، وتحدد اللائحة التنفيذية لهذا القانون حالات وشروط الاقتباس من البرنامج .
رابعا - عمل دراسات تحليلية للمصنف أو مقتطفات أو مقتبسات منه بقصد النقد أو المناقشة أو الإعلام .
خامسا - النسخ من مصنفات محمية وذلك للاستعمال فى إجراءات قضائية أو إدارية فى حدود ما تقتضيه هذه الإجراءات مع ذكر المصدر واسم المؤلف .
سادسا - نسخ أجزاء قصيرة من مصنف فى صورة مكتوبة أو مسجلة تسجيلا سمعيا أو بصريا أو سمعيا بصريا ، وذلك لأغراض التدريس بهدف الإيضاح أو الشرح ، بشرط أن يكون النسخ فى الحدود المعقولة وألا يتجاوز الغرض منه ، وأن يذكر اسم المؤلف وعنوان المصنف على كل النسخ كلما كان ذلك ممكنا عملا .
سابعا - نسخ مقال أو مصنف قصير أو مستخرج من مصنف إذا كان ذلك ضروريا لأغراض التدريس فى منشآت تعليمية ، وذلك بالشرطين الآتيين :
- أن يكون النسخ لمرة وحيدة أو فى أوقات منفصلة غير متصلة .
- أن يشار إلى اسم المؤلف وعنوان المصنف على كل نسخة .
ثامنا - تصوير نسخة وحيدة من المصنف بواسطة دار للوثائق أو المحفوظات أو بواسطة المكتبات التى لا تستهدف الربح - بصورة مباشرة أو غير مباشرة - وذلك فى أى من الحالتين الآتيتين :
- أن يكون النسخ لمقالة منشورة أو مصنف قصير أو مستخرج من مصنف متى كان الغرض من النسخ تلبية طلب شخص طبيعى لاستخدامها فى دراسة أو بحث على أن يتم ذلك لمرة واحدة أو على فترات متفاوتة .
- أن يكون النسخ بهدف المحافظة على النسخة الأصلية أو لتحل النسخة محل نسخة فقدت أو تلفت أو أصبحت غير صالحة للاستخدام ويستحيل الحصول على بديل لها بشروط معقولة .
تاسعا - النسخ المؤقت للمصنف الذى يتم تبعا أو أثناء البث الرقمى له أو أثناء القيام بعمل يستهدف استقبال مصنف مخزن رقميا ، وفى إطار التشغيل العادى للأداة المستخدمة ممن له الحق فى ذلك .$m239$,'20607fa9484996cea235acda5aaf9cfb',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(172,0,1,$m239$مع عدم الإخلال بحقوق المؤلف الأدبية طبقا لأحكام هذا القانون فليس للمؤلف أو خلفه أن يمنع الصحف أو الدوريات أو هيئات الإذاعة ، فى الحدود التى تبررها أغراضها مما يلى :
أولا - نشر مقتطفات من مصنفاته التى أتيحت للجمهور بصورة مشروعة ، ومقالاته المنشورة المتعلقة بالموضوعات التى تشغل الرأى العام فى وقت معين ، ما لم يكن المؤلف قد حظر ذلك عند النشر ، وبشرط الإشارة إلى المصدر الذى نقلت عنه وإلى اسم المؤلف وعنوان المصنف .
ثانيا - نشر الخطب والمحاضرات والندوات والأحاديث التى تلقى فى الجلسات العلنية للمجالس النيابية والهيئات التشريعية والإدارية والاجتماعات العلنية العلمية والأدبية والفنية والسياسية والاجتماعية والدينية ويشمل ذلك المرافعات القضائية فى الجلسات العلنية . ومع ذلك يظل للمؤلف وحده أو خلفه الحق فى جمع هذه المصنفات فى مجموعات تنسب إليه .
ثالثا - نشر مقتطفات من مصنف سمعى أو بصرى أو سمعى بصرى متاح للجمهور وذلك فى سياق التغطية الإخبارية للأحداث الجارية .$m239$,'125dc89dce61d16e0d7f51e60ee9fb56',DATE '2002-06-03',NULL,'active',NULL,NULL,$m239$رقم المادة كما طبع فى الجريدة الرسمية «171» مكررا (تكرار طباعى) بين المادة 171 والمادة 173؛ سياق التسلسل يدل أنها المادة 172 وحفظت بهذا الرقم.$m239$),
(173,0,1,$m239$تنطبق القيود الواردة على الحقوق المالية للمؤلف طبقا لأحكام هذا القانون على أصحاب الحقوق المجاورة .$m239$,'07ddcb81b25adc577b7d0de22f2bc80a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(174,0,1,$m239$إذا اشترك أكثر من شخص فى تأليف مصنف بحيث لا يمكن فصل نصيب كل منهم فى العمل المشترك اعتبر جميع الشركاء مؤلفين للمصنف بالتساوى فيما بينهم ما لم يتفق كتابة على غير ذلك .
وفى هذه الحالة لا يجوز لأحدهم الانفراد بمباشرة حقوق المؤلف إلا باتفاق مكتوب بينهم .
فإذا كان اشتراك كل من المؤلفين يندرج تحت نوع مختلف من الفن ، كان لكل منهم الحق فى استغلال الجزء الذى ساهم به على حدة ، بشرط ألا يضر ذلك باستغلال المصنف المشترك ما لم يتفق كتابة على غير ذلك .
ولكل منهم الحق فى رفع الدعاوى عند وقوع اعتداء على أى حق من حقوق المؤلف .
وإذا مات أحد المؤلفين الشركاء دون خلف عام أو خاص ، يؤول نصيبه إلى باقى الشركاء أو خلفهم ، ما لم يتفق كتابة على غير ذلك .$m239$,'89f8a231c9c58f4d779eef0355a56b49',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(175,0,1,$m239$يكون للشخص الطبيعى أو الاعتبارى الذى وجه إلى ابتكار المصنف الجماعى التمتع وحده بالحق فى مباشرة حقوق المؤلف عليه .$m239$,'404c718b0233cdff7653f7f83e819642',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(176,0,1,$m239$يعتبر مؤلف المصنفات التى لا تحمل اسم المؤلف أو التى تحمل اسما مستعارا مفوضا للنشر لها فى مباشرة الحقوق المنصوص عليها فى هذا القانون ، ما لم يعين المؤلف وكيلا آخر أو يعلن عن شخصه ويثبت صفته .$m239$,'b4feb5c5b6dd3bbe39cbb729e8a690c0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(177,0,1,$m239$أولا - يعتبر شريكا فى تأليف المصنف السمعى البصرى أو السمعى أو البصرى :
1 - مؤلف السيناريو أو صاحب الفكرة المكتوبة للبرنامج .
2 - من يقوم بتحوير مصنف أدبى موجود بشكل يجعله ملائما للأسلوب السمعى البصرى .
3 - مؤلف الحوار .
4 - واضع الموسيقى إذا قام بوضعها خصيصا للمصنف .
5 - المخرج الذى قام بعمل إيجابى من الناحية الفكرية لتحقيق المصنف .
وإذا كان المصنف مبسطا أو مستخرجا من مصنف آخر سابق عليه يعتبر مؤلف هذا المصنف السابق شريكا فى المصنف الجديد .
ثانيا - لمؤلف السيناريو ومحور المصنف الأدبى ومؤلف الحوار والمخرج مجتمعين الحق فى عرض المصنف السمعى أو البصرى أو السمعى البصرى رغم معارضة مؤلف المصنف الأدبى الأصلى أو واضع الموسيقى ، وذلك دون إخلال بحقوق المعارض المترتبة على الاشتراك فى التأليف .
ثالثا - لمؤلف الشطر الأدبى أو الشطر الموسيقى الحق فى نشر مصنفه بطريقة أخرى غير الطريقة المنشور بها هذا المصنف المشترك ما لم يتفق كتابة على غير ذلك .
رابعا - إذا امتنع أحد الشركاء فى تأليف مصنف سمعى بصرى أو سمعى أو بصرى عن إتمام الشق الخاص به ، فلا يترتب على ذلك منع باقى المشتركين من استعمال الجزء الذى أنجزه كل منهم ، وذلك دون إخلال بما للممتنع من حقوق مترتبة على اشتراكه فى التأليف .
خامسا - يكون المنتج طوال استغلال المصنف السمعى البصرى أو السمعى أو البصرى المتفق عليه نائبا عن مؤلفى هذا المصنف وعن خلفهم فى الاتفاق على استغلاله دون الإخلال بحقوق مؤلفى المصنفات الأدبية أو الموسيقية المقتبسة أو المحورة ، كل ذلك ما لم يتفق كتابة على خلافه . ويعتبر المنتج ناشرا لهذا المصنف ، وتكون له حقوق الناشر عليه وعلى نسخه فى حدود أغراض الاستغلال التجارى له .$m239$,'61845f132b60b6d9ee5bcb320f743a9f',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(178,0,1,$m239$لا يحق لمن قام بعمل صورة لآخر أن ينشر أو يعرض أو يوزع أصلها أو نسخا منها دون إذنه أو إذن من فى الصورة جميعا ما لم يتفق على خلافه . ومع ذلك يجوز نشر الصورة بمناسبة حوادث وقعت علنا أو إذا كانت الصورة تتعلق بأشخاص ذوى صفة رسمية أو عامة أو يتمتعون بشهرة محلية أو عالمية أو سمحت بهذا النشر السلطات العامة المختصة خدمة للصالح العام ، وبشرط ألا يترتب على عرض الصورة أو تداولها فى هذه الحالة مساس بشرف الشخص أو بسمعته أو اعتباره .
ويجوز للشخص الذى تمثله الصورة أن يأذن بنشرها فى الصحف وغيرها من وسائل النشر حتى ولو لم يسمح بذلك المصور ما لم يتفق على غير ذلك .
وتسرى هذه الأحكام على الصور أيا كانت الطريقة التى عملت بها من رسم أو حفر أو أية وسيلة أخرى .$m239$,'1986663f1efcc79c01a288a5f6a06518',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(179,0,1,$m239$لرئيس المحكمة المختصة بأصل النزاع ، بناء على طلب ذى الشأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التالية أو غيرها من الإجراءات التحفظية المناسبة ، وذلك عند الاعتداء على أى من الحقوق المنصوص عليها فى هذا الكتاب :
1 - إجراء وصف تفصيلى للمصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى .
2 - وقف نشر المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى أو عرضه أو نسخه أو صناعته .
3 - توقيع الحجز على المصنف أو التسجيل الصوتى أو البرنامج الإذاعى الأصلى أو على نسخه وكذلك على المواد التى تستعمل فى إعادة نشر هذا المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى أو استخراج نسخ منه بشرط أن تكون تلك المواد غير صالحة إلا لإعادة نشر المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى .
4 - إثبات واقعة الاعتداء على الحق محل الحماية .
5 - حصر الإيراد الناتج عن استغلال المصنف أو الأداء أو التسجيل الصوتى أو البرنامج الإذاعى وتوقيع الحجز على هذا الإيراد فى جميع الأحوال .
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'da5c3255202c84ee31d990d0f56be069',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(180,0,1,$m239$لذوى الشأن الحق فى التظلم إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدور الأمر أو إعلانه على حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا أو تعيين حارس مهمته إعادة نشر المصنف أو التسجيل الصوتى أو البرنامج الإذاعى أو استغلاله أو عرضه أو صناعته أو استخراج نسخ منه ، ويودع الإيراد الناتج خزانة المحكمة إلى أن يفصل فى أصل النزاع .$m239$,'78a7bb32066ed4e1aaac2f6aae45c6bc',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(181,0,1,$m239$مع عدم الإخلال بأية عقوبة أشد فى قانون آخر ، يعاقب بالحبس مدة لا تقل عن شهر وبغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرة آلاف جنيه أو بإحدى هاتين العقوبتين ، كل من ارتكب أحد الأفعال الآتية :
أولا - بيع أو تأجير مصنف أو تسجيل صوتى أو برنامج إذاعى محمى طبقا لأحكام هذا القانون ، أو طرحه للتداول بأية صورة من الصور بدون إذن كتابى مسبق من المؤلف أو صاحب الحق المجاور .
ثانيا - تقليد مصنف أو تسجيل صوتى أو برنامج إذاعى أو بيعه أو عرضه للبيع أو للتداول أو للإيجار مع العلم بتقليده .
ثالثا - التقليد فى الداخل لمصنف أو تسجيل صوتى أو برنامج إذاعى منشور فى الخارج أو بيعه أو عرضه للبيع أو التداول أو للإيجار أو تصديره إلى الخارج مع العلم بتقليده .
رابعا - نشر مصنف أو تسجيل صوتى أو برنامج إذاعى أو أداء محمى طبقا لأحكام هذا القانون عبر أجهزة الحاسب الآلى أو شبكات الإنترنت أو شبكات المعلومات أو شبكات الاتصالات أو غيرها من الوسائل بدون إذن كتابى مسبق من المؤلف أو صاحب الحق المجاور .
خامسا - التصنيع أو التجميع أو الاستيراد بغرض البيع أو التأجير لأى جهاز أو وسيلة أو أداة مصممة أو معدة للتحايل على حماية تقنية يستخدمها المؤلف أو صاحب الحق المجاور كالتشفير أو غيره .
سادسا - الإزالة أو التعطيل أو التعييب بسوء نية لأية حماية تقنية يستخدمها المؤلف أو صاحب الحق المجاور كالتشفير أو غيره .
سابعا - الاعتداء على أى حق أدبى أو مالى من حقوق المؤلف أو من الحقوق المجاورة المنصوص عليها فى هذا القانون .
وتتعدد العقوبة بتعدد المصنفات أو التسجيلات الصوتية أو البرامج الإذاعية أو الأداءات محل الجريمة .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن ثلاثة أشهر والغرامة التى لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه .
وفى جميع الأحوال تقضى المحكمة بمصادرة النسخ محل الجريمة أو المتحصلة منها وكذلك المعدات والأدوات المستخدمة فى ارتكابها .
ويجوز للمحكمة عند الحكم بالإدانة أن تقضى بغلق المنشأة التى استغلها المحكوم عليه فى ارتكاب الجريمة مدة لا تزيد على ستة أشهر ، ويكون الغلق وجوبيا فى حالة العود فى الجرائم المنصوص عليها فى البندين ( ثانيا ، وثالثا ) من هذه المادة .
وتقضى المحكمة بنشر ملخص الحكم الصادر بالإدانة فى جريدة يومية أو أكثر على نفقة المحكوم عليه .$m239$,'35a085cd203c9a206dd299099d900d75',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(182,0,1,$m239$فى حالة اتفاق طرفى النزاع على التحكيم تسرى أحكام قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994 ما لم يتفقا على غير ذلك .$m239$,'2b585caf755b97b63f06170cc1a54545',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(183,0,1,$m239$تصدر الوزارة المختصة الترخيص بالاستغلال التجارى أو المهنى للمصنف أو التسجيل الصوتى أو الأداء أو البرنامج الإذاعى الذى يسقط فى الملك العام مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه .$m239$,'294ebe39261e2bbe19a7c498cdb8d0e9',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(184,0,1,$m239$يلتزم ناشرو وطابعو ومنتجو المصنفات والتسجيلات الصوتية والأداءات المسجلة والبرامج الإذاعية بالتضامن فيما بينهم بإيداع نسخة منها أو أكثر بما لا يجاوز عشرة ، ويصدر الوزير المختص قرارا بتحديد عدد النسخ أو نظائرها البديلة مراعيا طبيعة كل مصنف ، وكذلك الجهة التى يتم فيها الإيداع .
ولا يترتب على عدم الإيداع المساس بحقوق المؤلف أو الحقوق المجاورة المنصوص عليها فى هذا القانون .
ويعاقب الناشر والطابع والمنتج عند مخالفة أحكام الفقرة الأولى من هذه المادة بغرامة لا تقل عن ألف جنيه ولا تجاوز ثلاثة آلاف جنيه عن كل مصنف أو تسجيل صوتى أو برنامج إذاعى وذلك دون الإخلال بالالتزام بالإيداع .
وتعفى من الإيداع المصنفات المنشورة فى الصحف والمجلات والدوريات إلا إذا نشر المصنف منفردا .$m239$,'1449388ec21e96bf1785a1b0912fe33e',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(185,0,1,$m239$تنشىء الوزارة المختصة سجلا لقيد التصرفات الواردة على المصنفات والأداءات والتسجيلات الصوتية والبرامج الإذاعية الخاضعة لأحكام هذا القانون ، وتحدد اللائحة التنفيذية نظام القيد فى هذا السجل مقابل رسم بما لا يجاوز ألف جنيه للقيد الواحد .
ولا يكون التصرف نافذا فى حق الغير إلا بعد إتمام القيد .$m239$,'e4349e1039d625051e2a86f7ac1f0817',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(186,0,1,$m239$يجوز لأى شخص الحصول من الوزارة المختصة على شهادة إيداع لمصنف أو أداء مسجل أو تسجيل صوتى أو برنامج إذاعى مودع ، وذلك مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه عن كل شهادة .$m239$,'eeae8b7ecad4ebf02468d4cde6571f87',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(187,0,1,$m239$تلتزم جميع المحال التى تطرح للتداول بالبيع أو بالإيجار أو بالإعارة أو بالترخيص بالاستخدام مصنفات أو أداءات مسجلة أو تسجيلات صوتية أو برامج إذاعية بالآتى :
1 - الحصول على ترخيص بذلك من الوزير المختص مقابل رسم تحدده اللائحة التنفيذية لهذا القانون بما لا يجاوز ألف جنيه .
2 - إمساك دفاتر منتظمة تثبت فيها بيانات كل مصنف أو تسجيل صوتى أو برنامج إذاعى وسنة تداوله .
ومع عدم الإخلال بأية عقوبة أشد فى أى قانون آخر يعاقب على مخالفة أحكام هذه المادة بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرة آلاف جنيه .
وفى حالة العود تكون العقوبة الغرامة التى لا تقل عن عشرة آلاف جنيه ولا تجاوز عشرين ألف جنيه .$m239$,'bad4fc03465125d8ed74f05a3401e86a',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(188,0,1,$m239$يصدر وزير العدل بالاتفاق مع الوزير المختص قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا القانون .$m239$,'3e0cb9f006050c6369ec6572a50acfe3',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(189,0,1,$m239$تتمتع بالحماية طبقا لأحكام هذا القانون الأصناف النباتية المستنبطة فى جمهورية مصر العربية أو فى الخارج سواء تم التوصل إليها بطريقة بيولوجية أو غير بيولوجية وذلك متى قيدت فى السجل الخاص بالأصناف النباتية التى تمنح حق الحماية .$m239$,'182046cf4e51c7b9d8f5c4dc9a05c3cc',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(190,0,1,$m239$ينشأ بقرار من رئيس مجلس الوزراء مكتب يسمى مكتب حماية الأصناف النباتية ويختص هذا المكتب بتلقى الطلبات المقدمة للحصول على حماية الأصناف النباتية وفحصها والبت فيها ومنح شهادة الحماية ، وذلك طبقا للقواعد والإجراءات التى يحددها قرار الإنشاء .$m239$,'336c62aa1bd6ed1b39aeb453cb4249a2',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(191,0,1,$m239$مع عدم الإخلال بأحكام الاتفاقيات الدولية النافذة فى جمهورية مصر العربية ، يكون لكل شخص طبيعى أو اعتبارى من المصريين أو من الأجانب الذين ينتمون أو يقيمون أو يتخذون مركز نشاط حقيقى وفعال لهم فى إحدى الدول أو الكيانات الأعضاء فى منظمة التجارة العالمية أو التى تعامل جمهورية مصر العربية معاملة المثل ، أن يتمتع بالحماية المقررة فى هذا الكتاب للأصناف النباتية .$m239$,'96d68f9a76a0bed8887cc08604006f96',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(192,0,1,$m239$يشترط للتمتع بالحماية أن يكون الصنف متصفا بالجدة والتميز والتجانس والثبات وأن يحمل تسمية خاصة به .
ويكون الصنف جديدا إذا لم يقم مربى الصنف النباتى حتى تاريخ تقديم الطلب ببيع مواد الإكثار النباتى للصنف أو تداولها بنفسه أو بموافقته لأغراض الاستغلال ، ولا يفقد الصنف شرط الجدة إذا تم الطرح أو التداول فى جمهورية مصر العربية لمدة لا تزيد على سنة سابقة على تقديم الطلب . فإذا كان الطرح أو التداول قد تم فى الخارج فيجب ألا تزيد المدة على ست سنوات بالنسبة للأشجار والأعناب وألا تزيد على أربع سنوات بالنسبة لغيرها من الحاصلات الزراعية ، كما لا يفقد الصنف شرط الجدة إذا تم بيعه أو منح حق استغلاله بموافقة المربى للغير قبل منحه حق الحماية .
ويكون الصنف متميزا إذا أمكن تمييزه عن غيره من الأصناف المعروفة بصفة واحدة ظاهرة على الأقل مع احتفاظه بهذه الصفة عند إكثاره .
ويكون الصنف متجانسا إذا كان الاختلاف بين أفراده يقع فى نطاق الحدود المسموح بها .
ويكون الصنف ثابتا - عند تكرار زراعته - إذا لم تتغير خصائصه الأساسية بتكرار إكثاره لفترة تحددها اللائحة التنفيذية لهذا القانون .
وتمنح شهادة حق المربى لمستنبط الصنف النباتى الذى تتوافر فيه شروط الحماية سواء أكان المستنبط شخصا طبيعيا أو اعتباريا .$m239$,'33c396699ef362f16acd01d62551ed65',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(193,0,1,$m239$تكون مدة حماية الأصناف النباتية خمس وعشرين سنة بالنسبة للأشجار والأعناب وعشرين سنة بالنسبة لغيرها من الحاصلات الزراعية .
وتبدأ مدة الحماية اعتبارا من تاريخ منحها .
ومع ذلك يمنح الصنف المقدم عنه الطلب حماية مؤقتة تبدأ من تاريخ إيداع الطلب وتنتهى بنشر الإعلان عن قبول منح الحماية على أن يقتصر حق المربى - المنصوص عليه بالمادة ( 194 ) من هذا القانون - خلال هذه الفترة على الحق فى التعويض العادل بمجرد منحه هذه الحماية ، بشرط أن يكون المربى قد وجه إخطارا بإيداعه الطلب إلى من قام باستغلال الصنف النباتى قبل منحه الحماية .$m239$,'da4e47b21738167380c71b2a4b616196',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(194,0,1,$m239$يتمتع من يحصل على شهادة حق المربى بحق استئثارى يخول له الاستغلال التجارى للصنف النباتى المحمى بأى صورة من الصور ولا يجوز للغير إنتاج أو إكثار أو تداول أو بيع أو تسويق أو استيراد أو تصدير مواد الإكثار إلا بموافقة كتابية من المربى .$m239$,'f7bbdb82ebf37383b246f655df73c32c',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(195,0,1,$m239$لا تمنع الحماية الغير من القيام بالأعمال الآتية :
1 - الأنشطة غير التجارية والاستخدام بغرض الإكثار الشخصى لناتج مادة الإكثار بواسطة المزارع على أرض فى حيازته الخاصة .
2 - الأنشطة المتصلة بالتجارب وبأغراض البحث العلمى .
3 - أنشطة التربية والتهجين والانتخاب وغيرها التى تستهدف استنباط أصناف جديدة .
4 - الأنشطة التى تتعلق بأغراض التعليم والتدريب .
5 - أنشطة الاستخدام والاستغلال التجارى والاستهلاك لمادة المحصول والمواد الأولية الوسيطة والمنتجات النهائية التى تصنع أو تستخرج من مادة المحصول بشكل مباشر أو غير مباشر سواء تمثلت مادة المحصول فى هيئة نبات كامل أو كانت جزءا منه .$m239$,'1c7912a38daf9cb2b2daca49db045806',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(196,0,1,$m239$يمنح مكتب حماية الأصناف النباتية ، بناء على عرض وزير الزراعة وبعد موافقة لجنة وزارية تشكل بقرار من رئيس مجلس الوزراء ، تراخيص إجبارية باستخدام واستغلال الصنف المحمى دون موافقة المربى وذلك فى الحالات التى تقتضيها المصلحة العامة ، وكذلك فى حالات امتناع المربى عن إنتاج الصنف بمعرفته أو توفير مواد الإكثار للصنف المحمى أو رفضه منح حق استغلال الصنف للغير رغم مناسبة الشروط المعروضة عليه أو قيامه بالممارسات المضادة للتنافس .
ويستحق المربى تعويضا عادلا مقابل منح الغير حق استخدام واستغلال الصنف خلال مدة الترخيص الإجبارى وتراعى فى تقدير التعويض القيمة الاقتصادية لهذا الصنف .$m239$,'cb29d7a160921cf579aa6fdc922baed8',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(197,0,1,$m239$يجب على المرخص له تطبيقا لأحكام المادة ( 196 ) من هذا القانون أن يلتزم بشروط الترخيص الإجبارى ، ولا يجوز له التنازل عنه للغير أو المساس بالحقوق الأخرى للمربى أثناء مدة الترخيص .
وينتهى هذا الترخيص بانتهاء المدة المحددة له ويلغى إذا خالف المرخص له لأى شرط من شروط الترخيص .$m239$,'d380569cdaea68efe2d53fbd825219c6',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(198,0,1,$m239$تستنفد حقوق المربى على مواد الصنف المحمى إذا طرحت للتداول بمعرفته أو بموافقته خارج جمهورية مصر العربية ، ويحق للغير فى هذه الحالة تداول أو بيع أو تسويق أو توزيع أو استيراد الصنف المحمى سواء فى هيئة مواد إكثار أو مواد محصول من نبات كامل أو أى جزء منه أو المنتجات المستخرجة أو المصنعة من المحصول أو غير ذلك من مكونات النبات .
ويحق للمربى أن يمنع الغير من تصدير الصنف المحمى إذا كان التصدير يؤدى إلى إكثار الصنف فى بلد لا يتمتع الصنف فيه بالحماية . ومع ذلك لا يحق للمربى منع الغير من تصدير الصنف المحمى إلى أى دولة إذا كان الغرض منه هو الاستهلاك .$m239$,'df88f62282aa3775c1ac1285faa5fbcd',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(199,0,1,$m239$لوزير الزراعة - بناء على توصية اللجنة الوزارية المشار إليها فى المادة ( 196 ) من هذا القانون - أن يقيد مباشرة المربى لكل أو بعض حقوقه المنصوص عليها فى هذا القانون بأى صورة من الصور بهدف تحقيق المصلحة العامة خاصة فى الأحوال الآتية :
1 - إذا ظهر للصنف النباتى المحمى تأثير ضار على البيئة الطبيعية أو على سلامة التنوع البيولوجى فى جمهورية مصر العربية ، أو على القطاع الزراعى فيها ، أو على حياة أو صحة الإنسان أو الحيوان أو النبات .
2 - إذا ظهر للصنف النباتى المحمى تأثير اقتصادى أو اجتماعى ضار أو معوق للأنشطة الزراعية المحلية ، أو إذا ظهر له استخدام يتناقض مع قيم ومعتقدات المجتمع .$m239$,'461cac5c1bdaaaa5b0c6287a32b888ba',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(200,0,1,$m239$يلتزم المربى بالكشف عن المصدر الوراثى الذى اعتمد عليه لاستنباط الصنف النباتى الجديد ، ويشترط لتمتع الصنف النباتى الجديد بالحماية أن يكون المربى قد حصل على ذلك المصدر بطريق مشروع وفقا للقانون المصرى .
ويمتد هذا الالتزام إلى المعلومات التراثية والخبرات التى تراكمت لدى الجماعات المحلية التى يكون المربى قد اعتمد عليها فى جهوده لاستنباط هذا الصنف النباتى الجديد .
وبالمثل يلتزم المربى الذى يتعامل مع الموارد الوراثية المصرية بهدف استنباط أصناف جديدة مشتقة منها بالحصول على موافقة الجهة الإدارية المختصة على هذا التعامل ، كما يتعهد باحترام المعارف التراثية المصرية كمصادر لما يكون قد توصل إليه من إنجازات استخدمت فيها تلك المعارف والخبرات ، ويكون ذلك بالإعلان عن المصدر المصرى الذى استفاد منه ذلك المربى وباقتسام العوائد التى يحققها مع صاحب المصلحة ، وذلك على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
وينشأ بوزارة الزراعة سجل لقيد الموارد الوراثية المصرية النباتية ، البرية والبلدية منها .$m239$,'4ce163a87a8524dd3d7151488b8556a9',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(201,0,1,$m239$يصدر مكتب حماية الأصناف النباتية شهادة حق المربى وفقا للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون وبعد أداء رسم تحدده هذه اللائحة بما لا يجاوز خمسة آلاف جنيه .
ويتم النشر عن ذلك على نفقة صاحب الحق فى جريدة شهرية يصدرها المكتب ، ويخطر من رفض طلبه بقرار الرفض وأسبابه ، ويكون لكل ذى شأن حق التظلم من قرار منح شهادة حق المربى أو رفض طلب حماية الصنف النباتى ، وذلك خلال خمسة عشر يوما من تاريخ النشر أو من تاريخ الإخطار على حسب الأحوال .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات الإخطار ونظر التظلم والبت فيه .$m239$,'6e474a034218197dbb248964bed15c58',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(202,0,1,$m239$تلغى شهادة حق المربى وذلك فى أحوال فقد الصنف لأحد الشروط الخاصة بمنحها أو فى حالة منحها بالمخالفة لأحكام هذا القانون ، وذلك وفقا للقواعد والإجراءات التى يصدر بها قرار من وزير الزراعة .
ويكون إخطار ذى الشأن بهذا القرار بموجب كتاب موصى عليه مصحوبا بعلم الوصول ، وله أن يتظلم منه خلال خمسة عشر يوما من تاريخ الإخطار .
ويصدر وزير الزراعة قرارا بقواعد وإجراءات نظر التظلم والبت فيه .$m239$,'f7cf4b4cbb3b7d8a25be9e19d3ab8f6b',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(203,0,1,$m239$مع عدم الإخلال بأية عقوبة أشد منصوص عليها فى أى قانون آخر يعاقب كل من يخالف عمدا أحكام هذا الكتاب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه .
وفى حالة العود تكون العقوبة الحبس مدة لا تقل عن ثلاثة أشهر ولا تجاوز سنة ، وبغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه .
وفى جميع الأحوال يحكم بمصادرة التقاوى ومواد الإكثار المضبوطة .$m239$,'f7bdf93578effce81577315d97a3e4e9',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(204,0,1,$m239$لرئيس المحكمة المختصة بأصل النزاع وبناء على طلب كل ذى شأن ، وبمقتضى أمر يصدر على عريضة ، أن يأمر بإجراء أو أكثر من الإجراءات التحفظية المناسبة ، وعلى وجه الخصوص :
1 - إثبات واقعة الاعتداء على الحق محل الحماية .
2 - إجراء حصر ووصف تفصيلى للمنتجات المخالفة والأدوات التى استخدمت أو تستخدم فى ارتكاب الجريمة .
3 - توقيع الحجز على الأشياء المذكورة فى البند ( 2 ) .
ولرئيس المحكمة فى جميع الأحوال أن يأمر بندب خبير أو أكثر لمعاونة المحضر المكلف بالتنفيذ ، وأن يفرض على الطالب إيداع كفالة مناسبة .
ويجب أن يرفع الطالب أصل النزاع إلى المحكمة المختصة خلال خمسة عشر يوما من تاريخ صدور الأمر وإلا زال كل أثر له .$m239$,'02d3191eea741666671f347e01b9fcb0',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(205,0,1,$m239$لذوى الشأن التظلم من الأمر إلى رئيس المحكمة الآمر خلال ثلاثين يوما من تاريخ صدوره أو إعلانه على حسب الأحوال ، ويكون لرئيس المحكمة تأييد الأمر أو إلغاؤه كليا أو جزئيا ، وفقا للقواعد والإجراءات المنصوص عليها فى قانون المرافعات المدنية والتجارية .$m239$,'aa27aaf2f5f021e8e38d1423b6a3e800',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL),
(206,0,1,$m239$يصدر وزير العدل بالاتفاق مع وزير الزراعة قرارا بتحديد من لهم صفة الضبطية القضائية فى تنفيذ أحكام هذا الكتاب .$m239$,'a24225b480385d77024136fd374b8faa',DATE '2002-06-03',NULL,'active',NULL,NULL,NULL);

DO $m239$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m239_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m239_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[239] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m239_art) <> 211 OR (SELECT sum(char_length(body)) FROM m239_art) <> 103968 OR (SELECT count(*) FROM m239_ver) <> 211 THEN
    RAISE EXCEPTION '[239] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=82 AND law_year=2002 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الملكية الفكرية%' THEN
    RAISE EXCEPTION '[239] يوجد مستند آخر برقم 82 لسنة 2002 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (82, 2002, $t239$قانون رقم 82 لسنة 2002 بإصدار قانون حماية حقوق الملكية الفكرية$t239$, $t239$قانون حماية حقوق الملكية الفكرية 82/2002$t239$, 'other', 'in_force', NULL, DATE '2002-06-02', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m239_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m239_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m239_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 211 THEN
    RAISE EXCEPTION '[239] عدد صفوف النص % بدل 211', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 211 THEN
    RAISE EXCEPTION '[239] عدد نسخ النص % بدل 211', v_vcnt;
  END IF;
  RAISE NOTICE '[239] قانون 82/2002: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m239$;
